/* Gerado por tools/extract-propers.js — não editar à mão. Fonte: Divinum Officium (Latin / Portugues), rubricas de 1960; português adaptado à norma brasileira. */
(function(DG){ DG.data = DG.data || {}; DG.data.propersRaw = {"_fonte":"Divinum Officium (Latin / Portugues), rubricas de 1960; português adaptado à norma brasileira.","celebrations":[{"id":"adv1","la":"Dominica I Adventus","pt":"I Domingo do Advento","color":"violaceus","classis":1,"tempus":"adventus","date":"adv1","gloria":false,"credo":true,"praef":"Trinitate","notes":["No Advento não se diz o Glória.","Domingo sem prefácio próprio: em 1962 diz-se o Prefácio da Santíssima Trindade."],"source":"Tempora/Adv1-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 24:1-3"},{"k":"text","t":"Ad te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."},{"k":"ref","t":"Ps 24:4"},{"k":"text","t":"Vias tuas, Dómine, demónstra mihi: et sémitas tuas édoce me."},{"k":"gloriapatri"},{"k":"text","t":"Ad te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."}],"pt":[{"k":"ref","t":"Sl 24:1-3"},{"k":"text","t":"A Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos."},{"k":"ref","t":"Sl 24:4"},{"k":"text","t":"Mostrai-me, Senhor, os vossos caminhos: e ensinai-me a conhecer as vossas veredas."},{"k":"gloriapatri"},{"k":"text","t":"A Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos."}]},"Oratio":{"la":[{"k":"text","t":"Excita, quǽsumus, Dómine, poténtiam tuam, et veni: ut ab imminéntibus peccatórum nostrórum perículis, te mereámur protegénte éripi, te liberánte salvári:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Senhor Vos suplicamos, manifestai o vosso poder, e “vinde já ao mundo”, a fim de que com vossa proteção mereçamos ser preservados dos iminentes perigos em que incorremos por causa dos nossos pecados, e sejamos livres e salvos:"},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]},"Lectio":{"la":[{"k":"text","t":"Lectio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","t":"Rom 13:11-14."},{"k":"text","t":"Fratres: Sciéntes, quia hora est jam nos de somno súrgere. Nunc enim própior est nostra salus, quam cum credídimus. Nox præcéssit, dies autem appropinquávit. Abjiciámus ergo ópera tenebrárum, et induámur arma lucis. Sicut in die honéste ambulémus: non in comessatiónibus et ebrietátibus, non in cubílibus et impudicítiis, non in contentióne et æmulatióne: sed induímini Dóminum Jesum Christum."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Romanos."},{"k":"ref","t":"Rom 13:11-14"},{"k":"text","t":"Meus irmãos: Sabeis que soou a hora em que devemos despertar do sono. Agora, a nossa salvação está mais próxima do que quando recebemos o dom da fé. A noite passou e o dia vem chegando. Despojemo-nos, pois, das obras das trevas, e revistamo-nos das armas da luz. Andemos honestamente, como de dia: nem em excessos de comidas e bebidas nem em luxúrias e impurezas, nem em contendas e invejas; mas revistamo-nos de Nosso Senhor Jesus Cristo."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 24:3; 24:4"},{"k":"text","t":"Univérsi, qui te exspéctant, non confundéntur, Dómine."},{"k":"V","t":"Vias tuas, Dómine, notas fac mihi: et sémitas tuas édoce me. Allelúja, allelúja."},{"k":"ref","t":"Ps 84:8."},{"k":"V","t":"Osténde nobis, Dómine, misericórdiam tuam: et salutáre tuum da nobis. Allelúja."}],"pt":[{"k":"ref","t":"Sl 24:3-4"},{"k":"text","t":"Senhor, todos os que esperam em Vós não serão confundidos."},{"k":"V","t":"Mostrai-me, Senhor, os vossos caminhos: e ensinai-me a conhecer as vossas veredas. Aleluia, aleluia."},{"k":"ref","t":"Sl 84:8"},{"k":"V","t":"Mostrai-nos, Senhor, a vossa misericórdia: e dai-nos a salvação. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secundum Lucam"},{"k":"ref","t":"Luc 21:25-33."},{"k":"text","t":"In illo témpore: Dixit Jesus discípulis suis: Erunt signa in sole et luna et stellis, et in terris pressúra géntium præ confusióne sónitus maris et flúctuum: arescéntibus homínibus præ timóre et exspectatióne, quæ supervénient univérso orbi: nam virtútes cœlórum movebúntur. Et tunc vidébunt Fílium hóminis veniéntem in nube cum potestáte magna et majestáte. His autem fíeri incipiéntibus, respícite et leváte cápita vestra: quóniam appropínquat redémptio vestra. Et dixit illis similitúdinem: Vidéte ficúlneam et omnes árbores: cum prodúcunt jam ex se fructum, scitis, quóniam prope est æstas. Ita et vos, cum vidéritis hæc fíeri, scitóte, quóniam prope est regnum Dei. Amen, dico vobis, quia non præteríbit generátio hæc, donec ómnia fiant. Cœlum et terra transíbunt: verba autem mea non transíbunt."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Lucas."},{"k":"ref","t":"Lc 21:25-33"},{"k":"text","t":"Naquele tempo, disse Jesus a seus discípulos: “Haverá sinais no sol, na lua e nas estrelas; e haverá angústia nos povos da terra por causa do bramido do mar e das ondas, mirrando-se os homens de susto, na expectativa daquelas coisas que irão acontecer em todo o mundo; pois os poderes do céu estremecerão. Então aparecerá o Filho do homem, que virá em uma nuvem, revestido de grande poder e majestade. Quando estas coisas começarem a acontecer, olhai para o alto e erguei as vossas cabeças, porque se avizinha a vossa redenção”. Depois deu-lhes esta comparação: “Vede a figueira e as demais árvores. Quando elas começam a frutificar, por aí conheceis que está próximo o estio. Do mesmo modo, quando estas coisas acontecerem, sabereis que está próximo o reino de Deus. Em verdade vos digo: não acabará esta geração sem que isto aconteça. O céu e a terra passarão; mas as minhas palavras permanecerão para sempre”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 24:1-3."},{"k":"text","t":"Ad te levávi ánimam meam: Deus meus, in te confído, non erubéscam: neque irrídeant me inimíci mei: étenim univérsi, qui te exspéctant, non confundéntur."}],"pt":[{"k":"ref","t":"Sl 24:1-3"},{"k":"text","t":"A Vós elevo a minha alma. Ó meu Deus, confio em Vós: não permitireis que fique confundido; nem que meus inimigos zombem de mim: porquanto aqueles que em Vós esperam não serão confundidos."}]},"Secreta":{"la":[{"k":"text","t":"Hæc sacra nos, Dómine, poténti virtúte mundátos ad suum fáciant purióres veníre princípium."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Permiti, Senhor, que estes mistérios, depois de nos haverem purificado com vossa poderosa virtude, nos façam chegar mais puros ainda junto daquele que é o seu princípio."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 84:13."},{"k":"text","t":"Dóminus dabit benignitátem: et terra nostra dabit fructum suum."}],"pt":[{"k":"ref","t":"Sl 84:13"},{"k":"text","t":"O Senhor mostrará a sua bondade: e a nossa terra dará “o seu fruto”."}]},"Postcommunio":{"la":[{"k":"text","t":"Suscipiámus, Dómine, misericórdiam tuam in médio templi tui: ut reparatiónis nostræ ventúra sollémnia cóngruis honóribus præcedámus."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, permiti que alcancemos a vossa misericórdia no meio do vosso templo, para que celebremos com a conveniente preparação a próxima solenidade da nossa reparação."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"adv3","la":"Dominica III Adventus (Gaudete)","pt":"III Domingo do Advento — Gaudete","color":"rosaceus","classis":1,"tempus":"adventus","date":"adv3","gloria":false,"credo":true,"praef":"Trinitate","notes":["Domingo Gaudete: podem usar-se paramentos de cor rosácea, sinal de alegria no meio da penitência."],"source":"Tempora/Adv3-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Phil 4:4-6"},{"k":"text","t":"Gaudéte in Dómino semper: íterum dico, gaudéte. Modéstia vestra nota sit ómnibus homínibus: Dóminus enim prope est. Nihil sollíciti sitis: sed in omni oratióne petitiónes vestræ innotéscant apud Deum."},{"k":"ref","t":"Ps 84:2"},{"k":"text","t":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"gloriapatri"},{"k":"text","t":"Gaudéte in Dómino semper: íterum dico, gaudéte. Modéstia vestra nota sit ómnibus homínibus: Dóminus enim prope est. Nihil sollíciti sitis: sed in omni oratióne petitiónes vestræ innotéscant apud Deum."}],"pt":[{"k":"ref","t":"Fl. 4:4-6"},{"k":"text","t":"Regozijai-vos incessantemente no Senhor. Eu vo-lo repito: regozijai-vos. Que todos os homens vejam a vossa modéstia, Pois o Senhor está perto. Não vos inquieteis com coisa alguma; mas mostrai a Deus nas vossas orações e súplicas todas vossas necessidades."},{"k":"ref","t":"Sl 84:2"},{"k":"text","t":"Abençoastes, Senhor, a vossa terra: e livrastes Jacob do cativeiro."},{"k":"gloriapatri"},{"k":"text","t":"Regozijai-vos incessantemente no Senhor. Eu vo-lo repito: regozijai-vos. Que todos os homens vejam a vossa modéstia, Pois o Senhor está perto. Não vos inquieteis com coisa alguma; mas mostrai a Deus nas vossas orações e súplicas todas vossas necessidades."}]},"Oratio":{"la":[{"k":"text","t":"Aurem tuam, quǽsumus, Dómine, précibus nostris accómmoda: et mentis nostræ ténebras, grátia tuæ visitatiónis illústra:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Ouvi, Senhor, Vos suplicamos, as nossas orações; e, pela graça da vossa visita, esclarecei as trevas da nossa alma:"},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]},"Lectio":{"la":[{"k":"text","t":"Lectio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","t":"Philipp 4:4-7"},{"k":"text","t":"Fratres: Gaudéte in Dómino semper: íterum dico, gaudéte. Modéstia vestra nota sit ómnibus homínibus: Dóminus prope est. Nihil sollíciti sitis: sed in omni oratióne et obsecratióne, cum gratiárum actióne, petitiónes vestræ innotéscant apud Deum. Et pax Dei, quæ exsúperat omnem sensum, custódiat corda vestra et intellegéntias vestras, in Christo Jesu, Dómino nostro."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Filipenses."},{"k":"ref","t":"Fl 4:4-7"},{"k":"text","t":"Meus irmãos: Regozijai-vos incessantemente no Senhor. Eu vo-lo repito: regozijai-vos. Que todos os homens vejam a vossa modéstia. Não vos inquieteis com coisa alguma; mas mostrai a Deus pelas vossas orações e súplicas todas vossas necessidades. A paz de Deus, que ultrapassa toda nossa inteligência, guardará os vossos corações e inteligências em Jesus Cristo, Nosso Senhor."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 79:2; 79:3; 79:2"},{"k":"text","t":"Qui sedes, Dómine, super Chérubim, éxcita poténtiam tuam, et veni."},{"k":"V","t":"Qui regis Israël, inténde: qui dedúcis, velut ovem, Joseph. Allelúja, allelúja,"},{"k":"V","t":"Excita, Dómine, potentiam tuam, et veni, ut salvos fácias nos. Allelúja."}],"pt":[{"k":"ref","t":"Sl 79:2-3, 2."},{"k":"text","t":"Senhor, que estais sentado acima dos Querubins, mostrai o vosso poder, e vinde."},{"k":"V","t":"Ouvi, ó vós, que governais Israel; ó vós, que conduzis José, como um pastor conduz um rebanho. Aleluia, aleluia."},{"k":"V","t":"Mostrai, Senhor, o vosso poder, e vinde, para que sejamos salvos. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem"},{"k":"ref","t":"Joann 1:19-28"},{"k":"text","t":"In illo tempore: Misérunt Judǽi ab Jerosólymis sacerdótes et levítas ad Joánnem, ut interrogárent eum: Tu quis es? Et conféssus est, et non negávit: et conféssus est: Quia non sum ego Christus. Et interrogavérunt eum: Quid ergo? Elías es tu? Et dixit: Non sum. Prophéta es tu? Et respondit: Non. Dixérunt ergo ei: Quis es, ut respónsum demus his, qui misérunt nos? Quid dicis de te ipso? Ait: Ego vox clamántis in desérto: Dirígite viam Dómini, sicut dixit Isaías Prophéta. Et qui missi fúerant, erant ex pharisǽis. Et interrogavérunt eum, et dixérunt ei: Quid ergo baptízas, si tu non es Christus, neque Elías, neque Prophéta? Respóndit eis Joánnes, dicens: Ego baptízo in aqua: médius autem vestrum stetit, quem vos nescítis. Ipse est, qui post me ventúrus est, qui ante me factus est: cujus ego non sum dignus ut solvam ejus corrígiam calceaménti. Hæc in Bethánia facta sunt trans Jordánem, ubi erat Joánnes baptízans."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 1:19-28"},{"k":"text","t":"Naquele tempo, os judeus enviaram de Jerusalém alguns sacerdotes e levitas a João, perguntando-lhe: “Quem és tu?”. Ele confessou e não negou. Ele confessou: “Eu não sou Cristo”. E de novo o interrogaram: “Então quem és? És Elias?” João respondeu: “Não sou”. “És algum Profeta?”. Ele respondeu: “Não sou”. “Diz, pois, quem és, a fim de que respondamos àqueles que nos enviaram. Que dizes de ti?” E João respondeu: “Eu sou a voz daquele que clama no deserto: “Endireitai o caminho de Senhor”, como disse o Profeta Isaías”. Ora, como alguns daqueles que lhe haviam sido enviados eram fariseus, interrogaram-no e disseram-lhe: “Então, se não és nem Cristo, nem Elias, nem algum Profeta, porque batizas?” João respondeu-lhes: a “Eu batizo na água; porém, entre vós está Alguém, a quem não conheceis, que é Aquele que havia de vir depois de mim, mas que já existia antes de mim, e a quem não sou digno de desatar as correias das sandálias”. Isto aconteceu em Betânia, além-Jordão, onde João batizava."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 84:2"},{"k":"text","t":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob: remisísti iniquitatem plebis tuæ."}],"pt":[{"k":"ref","t":"Sl 84:2"},{"k":"text","t":"Abençoastes Senhor, a vossa terra; e livrastes Jacob do cativeiro: perdoastes a iniquidade do vosso povo."}]},"Secreta":{"la":[{"k":"text","t":"Devotiónis nostræ tibi, quǽsumus, Dómine, hóstia júgiter immolétur: quæ et sacri péragat institúta mystérii, et salutáre tuum in nobis mirabíliter operétur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, Vos suplicamos, fazei que a nossa piedade Vos ofereça continuamente o sacrifício desta hóstia, para que ela nos alcance aquelas graças para que instituístes estes sagrados mistérios, produzindo em nós de uma maneira admirável a salvação que esperamos da vossa bondade."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Is 35:4."},{"k":"text","t":"Dícite: pusillánimes, confortámini et nolíte timére: ecce, Deus noster véniet et salvábit nos."}],"pt":[{"k":"ref","t":"Is 35:4"},{"k":"text","t":"Dizei:“Pusilânimes, confortai-vos e nada receeis: Eis que vem o nosso Deus e nos salvará”."}]},"Postcommunio":{"la":[{"k":"text","t":"Implorámus, Dómine, cleméntiam tuam: ut hæc divína subsídia, a vítiis expiátos, ad festa ventúra nos prǽparent."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Imploramos, Senhor, a vossa clemência, a fim de que estes divinos mistérios, purificando-nos dos nossos vícios, nos Preparem para a solenidade que se aproxima."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"immac","la":"In Conceptione Immaculata B. Mariæ Virginis","pt":"Imaculada Conceição da Bem-aventurada Virgem Maria","color":"albus","classis":1,"tempus":"adventus","date":"12-08","gloria":true,"credo":true,"praef":"Maria","praefIns":{"la":"Conceptióne immaculáta","pt":"Imaculada Conceição"},"gradualeSec":"Graduale","notes":["Festa de I classe: Glória e Credo.","Prefácio de Nossa Senhora com a inserção “Et te in Conceptione immaculata”."],"source":"Sancti/12-08","parts":{"Introitus":{"la":[{"k":"ref","t":"Is 61:10"},{"k":"text","t":"Gaudens gaudébo in Dómino, et exsultábit ánima mea in Deo meo: quia índuit me vestiméntis salútis: et induménto justítiæ circúmdedit me, quasi sponsam ornátam monílibus suis."},{"k":"ref","t":"Ps 29:2"},{"k":"text","t":"Exaltábo te, Dómine, quóniam suscepísti me: nec delectásti inimícos meos super me."},{"k":"gloriapatri"},{"k":"text","t":"Gaudens gaudébo in Dómino, et exsultábit ánima mea in Deo meo: quia índuit me vestiméntis salútis: et induménto justítiæ circúmdedit me, quasi sponsam ornátam monílibus suis."}],"pt":[{"k":"ref","t":"Is 61:10"},{"k":"text","t":"Rejubilarei no Senhor. Minha alma exultará de alegria no meu Deus. Pois Ele ornou-me com as vestes da salvação e embelezou-me com o manto da santidade, como uma esposa adornada com suas joias."},{"k":"ref","t":"Sl 29:2"},{"k":"text","t":"Louvar-Vos-ei, Senhor, porque me protegestes e não consentistes que meus inimigos zombassem de mim."},{"k":"gloriapatri"},{"k":"text","t":"Rejubilarei no Senhor. Minha alma exultará de alegria no meu Deus. Pois Ele ornou-me com as vestes da salvação e embelezou-me com o manto da santidade, como uma esposa adornada com suas joias."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui per immaculátam Vírginis Conceptiónem dignum Fílio tuo habitáculum præparásti: quǽsumus; ut, qui ex morte ejúsdem Filii tui prævísa eam ab omni labe præservásti, nos quoque mundos ejus intercessióne ad te perveníre concédas."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eundem"}],"pt":[{"k":"text","t":"Ó Deus, que pela Imaculada Conceição da Virgem preparastes para o vosso Filho uma habitação digna d’Ele, dignai-Vos permitir que, assim como em previsão da morte deste mesmo Filho a preservastes de toda a mácula, assim também por sua intercessão sejamos purificados de todos os pecados e possamos ir até vós."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eundem"}]},"Lectio":{"la":[{"k":"text","t":"Léctio libri Sapiéntiæ"},{"k":"ref","t":"Prov 8:22-35"},{"k":"text","t":"Dóminus possedit me in inítio viárum suárum, ántequam quidquam fáceret a princípio. Ab ætérno ordináta sum, et ex antíquis, ántequam terra fíeret. Nondum erant abýssi, et ego jam concépta eram: necdum fontes aquárum erúperant: necdum montes gravi mole constíterant: ante colles ego parturiébar: adhuc terram non fécerat et flúmina et cárdines orbis terræ. Quando præparábat cœlos, áderam: quando certa lege et gyro vallábat abýssos: quando æthera firmábat sursum et librábat fontes aquárum: quando circúmdabat mari términum suum et legem ponébat aquis, ne transírent fines suos: quando appendébat fundaménta terræ. Cum eo eram cuncta compónens: et delectábar per síngulos dies, ludens coram eo omni témpore: ludens in orbe terrárum: et delíciæ meæ esse cum filiis hóminum. Nunc ergo, filii, audíte me: Beáti, qui custódiunt vias meas. Audíte disciplínam, et estóte sapiéntes, et nolíte abjícere eam. Beátus homo, qui audit me et qui vígilat ad fores meas cotídie, et obsérvat ad postes óstii mei. Qui me invénerit, invéniet vitam et háuriet salútem a Dómino."}],"pt":[{"k":"text","t":"Lição do Livro da Sabedoria."},{"k":"ref","t":"Pr 8:22-35"},{"k":"text","t":"O Senhor possuiu-me desde o princípio das suas vias e ainda antes de criar qualquer coisa, no Princípio, antes da origem da terra. Quando fui concebida, ainda não existiam os abismos; ainda as fontes não brotavam águas; nem as montanhas se erguiam sobre as suas pesadas massas; nem existiam as colinas. Já eu tinha sido dada à luz, e ainda Ele não havia criado nem a terra, nem os rios, nem os primeiros elementos do globo terrestre! Quando Ele preparava os céus, já eu lá estava; quando Ele cercava os abismos, sujeitando-os a uma lei certa; quando Ele segurava as nuvens no alto; quando regulava as fontes das águas; quando fixava ao mar os seus limites para que as águas não invadissem a terra; quando lançava as bases da terra: já eu estava lá com Ele, regulando todas estas coisas, regozijando-me em cada dia, gozando continuamente a sua companhia, alegrando-me no globo da terra e deliciando-me em estar com os filhos dos homens. E agora, meus filhos, escutai-me: Bem-aventurados aqueles que transitam pelas minhas vias. Atendei às instruções, para que sejais prudentes. Não as rejeiteis. Bem-aventurado o homem que me escuta; que vigia continuamente às minhas portas; e que está sempre pronto à sua entrada. Aquele que me tiver achado, terá achado a vida e gozará a salvação do Senhor."}]},"Graduale":{"la":[{"k":"ref","t":"Judith 13:23"},{"k":"text","t":"Benedícta es tu. Virgo María, a Dómino, Deo excélso, præ ómnibus muliéribus super terram."},{"k":"ref","t":"Judith 15:10"},{"k":"text","t":"Tu glória Jerúsalem, tu lætítia Israël, tu honorificéntia pópuli nostri."},{"k":"text","t":"Allelúja, allelúja."},{"k":"ref","t":"Cant 4:7"},{"k":"text","t":"Tota pulchra es, María: et mácula originális non est in te. Allelúja."}],"pt":[{"k":"ref","t":"Jdt 13:23"},{"k":"text","t":"Fostes abençoada pelo Senhor, pelo Deus altíssimo, ó V. Maria, tendo sido colocada superior a todas as mulheres da terra."},{"k":"ref","t":"Jdt 15:10"},{"k":"text","t":"Sois a glória de Jerusalém; sois a alegria de Israel; sois a honra do nosso povo. Aleluia, aleluia."},{"k":"ref","t":"Cant 4:7"},{"k":"text","t":"Toda sois formosa, ó Maria; e a mácula original não existe em vós. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Lucam"},{"k":"ref","t":"Luc 1:26-28"},{"k":"text","t":"In illo témpore: Missus est Angelus Gábriël a Deo in civitátem Galilææ, cui nomen Názareth, ad Vírginem desponsátam viro, cui nomen erat Joseph, de domo David, et nomen Vírginis María. Et ingréssus Angelus ad eam, dixit: Ave, grátia plena; Dóminus tecum: benedícta tu in muliéribus."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Lucas."},{"k":"ref","t":"Lc 1:26-28"},{"k":"text","t":"Naquele tempo, foi mandado por Deus o Anjo Gabriel a uma cidade da Galileia, cujo nome era Nazaré, a uma Virgem desposada com um varão, cujo nome era José, da casa de David; e o nome da Virgem era Maria. E, entrando o Anjo onde ela estava, disse-lhe: “Ave, ó cheia de graça: o Senhor é convosco: bendita sois entre as mulheres”."}]},"Offertorium":{"la":[{"k":"ref","t":"Luc 1:28"},{"k":"text","t":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, allelúja."}],"pt":[{"k":"ref","t":"Lc 1:28"},{"k":"text","t":"Ave, Maria, cheia de graça; o Senhor é convosco: bendita sois vós entre as mulheres. Aleluia."}]},"Secreta":{"la":[{"k":"text","t":"Salutárem hóstiam, quam in sollemnitáte immaculátæ Conceptiónis beátæ Vírginis Maríæ tibi, Dómine, offérimus, súscipe et præsta: ut, sicut illam tua grátia præveniénte ab omni labe immúnem profitémur; ita ejus intercessióne a culpis ómnibus liberémur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Aceitai, Senhor, a hóstia de salvação, que Vos oferecemos nesta festividade da Imaculada Conceição da B. V. Maria; e, assim como acreditamos que ela, prevenida com a plenitude da vossa graça, foi isenta de toda a mácula, assim também por sua intercessão sejamos livres de todas nossas culpas."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 86:3, Luc 1:49"},{"k":"text","t":"Gloriósa dicta sunt de te, María: quia fecit tibi magna qui potens est."}],"pt":[{"k":"ref","t":"Sl 86:3, Lc 1:49"},{"k":"text","t":"Gloriosas coisas se têm narrado de vós, ó Maria; pois o Onipotente operou grandes maravilhas em vosso favor."}]},"Postcommunio":{"la":[{"k":"text","t":"Sacraménta quæ súmpsimus, Dómine, Deus noster: illíus in nobis culpæ vúlnera réparent; a qua immaculátam beátæ Maríæ Conceptiónem singuláriter præservásti."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, nosso Deus, fazei que os sacramentos, que recebemos, curem as feridas que em nós abriu aquele pecado de que por um privilégio singular preservastes a Imaculada Conceição da B. V. Maria."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"nat1","la":"In Nativitate Domini — Ad Missam in nocte","pt":"Natal do Senhor — Missa da Noite","color":"albus","classis":1,"tempus":"nativitatis","date":"12-25","gloria":true,"credo":true,"praef":"Nat","comm":"Nat","notes":["No Credo, às palavras “Et incarnatus est”, na Missa do Natal o celebrante ajoelha-se (genuflexão prolongada).","Communicantes próprio do Natal."],"source":"Sancti/12-25m1","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 2:7."},{"k":"text","t":"Dóminus dixit ad me: Fílius meus es tu, ego hódie génui te."},{"k":"ref","t":"Ps 2:1"},{"k":"text","t":"Quare fremuérunt gentes: et pópuli meditáti sunt inánia?"},{"k":"gloriapatri"},{"k":"text","t":"Dóminus dixit ad me: Fílius meus es tu, ego hódie génui te."}],"pt":[{"k":"ref","t":"Sl 2:7"},{"k":"text","t":"O Senhor disse-me: Sois o meu Filho: Eu Vos gerei hoje."},{"k":"ref","t":"Sl 2:1"},{"k":"text","t":"Porque se agitaram as nações? Porque meditaram os povos vãos projetos contra mim?"},{"k":"gloriapatri"},{"k":"text","t":"O Senhor disse-me: Sois o meu Filho: Eu Vos gerei hoje."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui hanc sacratíssimam noctem veri lúminis fecísti illustratióne claréscere: da, quǽsumus; ut, cujus lucis mystéria in terra cognóvimus, ejus quoque gáudiis in cœlo perfruámur:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Ó Deus, que fizestes brilhar nesta noite santíssima os esplendores da verdadeira luz, permiti, Vos pedimos, que, depois de havermos conhecido esta luz misteriosa neste mundo, possamos gozar no céu as delícias de que é origem Aquele que,"},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beati Pauli Apóstoli ad Titum"},{"k":"ref","t":"Tit 2:11-15"},{"k":"text","t":"Caríssime: Appáruit grátia Dei Salvatóris nostri ómnibus homínibus, erúdiens nos, ut, abnegántes impietátem et sæculária desidéria, sóbrie et juste et pie vivámus in hoc sǽculo, exspectántes beátam spem et advéntum glóriæ magni Dei et Salvatóris nostri Jesu Christi: qui dedit semetípsum pro nobis: ut nos redímeret ab omni iniquitáte, et mundáret sibi pópulum acceptábilem, sectatórem bonórum óperum. Hæc lóquere et exhortáre: in Christo Jesu, Dómino nostro."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo a Tito."},{"k":"ref","t":"Tt 2:11-15"},{"k":"text","t":"Caríssimo: A graça de Deus, nosso Salvador, manifestou-se a todos os homens, ensinando-nos, a fim de que, repudiando a impiedade e os apetites terrenos, vivamos neste mundo com temperança, justiça e piedade, pensando na esperança, na bem-aventurança eterna e na vinda da glória do nosso grande Deus e Salvador, Jesus Cristo: que se ofereceu espontaneamente por nós, para nos resgatar de todas as iniquidades, e tornar-nos numa raça purificada, escolhida e zelosa em suas boas obras. Ensina e prega estas coisas, em Jesus Cristo, Nosso Senhor!"}]},"Graduale":{"la":[{"k":"ref","t":"Ps 109:3; 109:1"},{"k":"text","t":"Tecum princípium in die virtútis tuæ: in splendóribus Sanctórum, ex útero ante lucíferum génui te."},{"k":"V","t":"Dixit Dóminus Dómino meo: Sede a dextris meis: donec ponam inimícos tuos, scabéllum pedum tuórum. Allelúja, allelúja."},{"k":"ref","t":"Ps 2:7"},{"k":"V","t":"Dóminus dixit ad me: Fílius meus es tu, ego hódie génui te. Allelúja."}],"pt":[{"k":"ref","t":"Sl 109:3; 109:1"},{"k":"text","t":"Em Vós estará o poder soberano no dia do vosso império, no meio dos esplendores dos escolhidos."},{"k":"V","t":"Eu Vos gerei no meu seio, antes da aurora. O soberano Senhor disse ao meu Senhor: “Assentai-Vos à minha dextra até que eu torne os meus inimigos em escabelo dos vossos pés”. Aleluia, aleluia."},{"k":"ref","t":"Sl 2:7"},{"k":"V","t":"O Senhor disse-me: “Vós sois o meu Filho; gerei-Vos hoje”. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secundum Lucam"},{"k":"ref","t":"Luc 2:1-14"},{"k":"text","t":"In illo témpore: Exiit edíctum a Cæsare Augústo, ut describerétur univérsus orbis. Hæc descríptio prima facta est a præside Sýriæ Cyríno: et ibant omnes ut profiteréntur sínguli in suam civitátem. Ascéndit autem et Joseph a Galilæa de civitáte Názareth, in Judæam in civitátem David, quæ vocatur Béthlehem: eo quod esset de domo et fámilia David, ut profiterétur cum María desponsáta sibi uxóre prægnánte. Factum est autem, cum essent ibi, impléti sunt dies, ut páreret. Et péperit fílium suum primogénitum, et pannis eum invólvit, et reclinávit eum in præsépio: quia non erat eis locus in diversório. Et pastóres erant in regióne eádem vigilántes, et custodiéntes vigílias noctis super gregem suum. Et ecce, Angelus Dómini stetit juxta illos, et cláritas Dei circumfúlsit illos, et timuérunt timóre magno. Et dixit illis Angelus: Nolíte timére: ecce enim, evangelízo vobis gáudium magnum, quod erit omni pópulo: quia natus est vobis hódie Salvátor, qui est Christus Dóminus, in civitáte David. Et hoc vobis signum: Inveniétis infántem pannis involútum, et pósitum in præsépio. Et súbito facta est cum Angelo multitúdo milítiæ cœléstis, laudántium Deum et dicéntium: Glória in altíssimis Deo, et in terra pax hóminibus bonæ voluntátis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Lucas."},{"k":"ref","t":"Lc 2:1-14"},{"k":"text","t":"Naquele tempo, foi publicado um édito de César Augusto para que se fizesse o recenseamento de todo o universo. Este primeiro recenseamento foi feito por Cirino, governador da Síria. E todos, pois, iam à sua cidade para se inscreverem. José saiu também da Galileia, da cidade de Nazaré, para a Judeia, e foi a Belém, cidade de David, porque ele era da casa e da família de David, para aí ser recenseado com Maria, sua esposa, que estava próximo a dar à luz. Ora, aconteceu que, enquanto eles estavam em Belém, completaram-se os dias em que ela devia dar à luz. E, com efeito, ela deu à luz o seu Filho primogênito, envolvendo-O em uns panos e colocando-O em um presépio, porque não tiveram lugar na hospedaria. Ora, havia naquele lugar uns pastores, guardando durante a noite os seus gados; e eis que um Anjo do céu lhes apareceu, envolvendo-os com a claridade de Deus, o que os encheu de grande temor. Então, o Anjo disse-lhes: “Não tenhais receio, pois venho anunciar-vos uma grande alegria, que se estenderá a todo o povo: é que nasceu hoje, na cidade de David, um Salvador, que é o Cristo Senhor. Isto vos servirá de sinal: Achareis um Menino, envolvido em uns panos e deitado num presépio”, E no mesmo instante reuniu-se com o Anjo uma multidão da milícia celestial, louvando Deus e dizendo: “Glória a Deus no mais alto dos céus, e, na terra, paz aos homens de boa vontade!”"}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 95:11; 95:13"},{"k":"text","t":"Læténtur cœli et exsúltet terra ante fáciem Dómini: quóniam venit."}],"pt":[{"k":"ref","t":"Sl 95:11; 95:13"},{"k":"text","t":"Alegrem-se os céus! Regozije-se a terra ante a face do Senhor, pois Ele veio."}]},"Secreta":{"la":[{"k":"text","t":"Accépta tibi sit, Dómine, quǽsumus, hodiérnæ festivitátis oblátio: ut, tua gratia largiénte, per hæc sacrosáncta commércia, in illíus inveniámur forma, in quo tecum est nostra substántia:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Dignai-Vos, Senhor, aceitar a oblação que Vos oferecemos na festividade deste dia, e pela vossa graça permiti que por meio deste sacrossanto comércio nos assemelhemos Àquele em quem a nossa substância humana está unida à vossa divindade."},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 109:3"},{"k":"text","t":"In splendóribus Sanctórum, ex útero ante lucíferum génui te."}],"pt":[{"k":"ref","t":"Sl 109:3"},{"k":"text","t":"Eu Vos gerei no meu seio, antes do romper da aurora, entre os esplendores dos escolhidos."}]},"Postcommunio":{"la":[{"k":"text","t":"Da nobis, quǽsumus, Dómine, Deus noster: ut, qui Nativitátem Dómini nostri Jesu Christi mystériis nos frequentáre gaudémus; dignis conversatiónibus ad ejus mereámur perveníre consórtium:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Senhor, nosso Deus, permiti, Vos suplicamos, que, celebrando alegremente o Nascimento de Nosso Senhor Jesus Cristo, pela frequência destes divinos mistérios, mereçamos, com uma conduta santa, gozar a união perfeita com Aquele:"},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]}}},{"id":"nat3","la":"In Nativitate Domini — Ad tertiam Missam in die","pt":"Natal do Senhor — Missa do Dia","color":"albus","classis":1,"tempus":"nativitatis","date":"12-25","gloria":true,"credo":true,"praef":"Nat","comm":"Nat","ultimaEv":false,"notes":["O Evangelho desta Missa é o prólogo de São João; por isso, segundo as rubricas de 1960 (n. 509), omite-se o Último Evangelho.","Ao “Et Verbum caro factum est” do Evangelho, todos genuflectem."],"source":"Sancti/12-25m3","parts":{"Introitus":{"la":[{"k":"ref","t":"Isa 9:6"},{"k":"text","t":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."},{"k":"ref","t":"Ps 97:1"},{"k":"text","t":"Cantáte Dómino cánticum novum, quia mirabília fecit."},{"k":"gloriapatri"},{"k":"text","t":"Puer natus est nobis, et fílius datus est nobis: cujus impérium super húmerum ejus: et vocábitur nomen ejus magni consílii Angelus."}],"pt":[{"k":"ref","t":"Is 9:6"},{"k":"text","t":"Nasceu para nós um Menino e foi-nos dado um Filho que traz sobre os ombros o manto da realeza, o qual será chamado “Anjo do admirável conselho”."},{"k":"ref","t":"Sl 97:1"},{"k":"text","t":"Cantai ao Senhor um hino novo, pois Ele operou maravilhas."},{"k":"gloriapatri"},{"k":"text","t":"Nasceu para nós um Menino e foi-nos dado um Filho que traz sobre os ombros o manto da realeza, o qual será chamado “Anjo do admirável conselho”."}]},"Oratio":{"la":[{"k":"text","t":"Concéde, quǽsumus, omnípotens Deus: ut nos Unigéniti tui nova per carnem Natívitas líberet; quos sub peccáti jugo vetústa sérvitus tenet."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eundem"}],"pt":[{"k":"text","t":"Ó Deus onipotente, Vos imploramos, dignai-Vos permitir que o novo Nascimento do vosso Filho Unigênito Incarnado nos livre do antigo cativeiro em que nos conserva o jugo do pecado."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eundem"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","t":"Hebr 1:1-12"},{"k":"text","t":"Multifáriam, multísque modis olim Deus loquens pátribus in Prophétis: novíssime diébus istis locútus est nobis in Fílio, quem constítuit herédem universórum, per quem fecit et sǽcula: qui cum sit splendor glóriæ, et figúra substántia? ejus, portánsque ómnia verbo virtútis suæ, purgatiónem peccatórum fáciens, sedet ad déxteram majestátis in excélsis: tanto mélior Angelis efféctus, quanto differéntius præ illis nomen hereditávit. Cui enim dixit aliquándo Angelórum: Fílius meus es tu, ego hódie génui te? Et rursum: Ego ero illi in patrem, et ipse erit mihi in fílium? Et cum íterum introdúcit Primogénitum in orbem terræ, dicit: Et adórent eum omnes Angeli Dei. Et ad Angelos quidem dicit: Qui facit Angelos suos spíritus, et minístros suos flammam ignis. Ad Fílium autem: Thronus tuus, Deus, in sǽculum sǽculi: virga æquitátis, virga regni tui. Dilexísti justítiam et odísti iniquitátem: proptérea unxit te Deus, Deus tuus, óleo exsultatiónis præ particípibus tuis. Et: Tu in princípio, Dómine, terram fundásti: et ópera mánuum tuárum sunt cœli. Ipsi períbunt, tu autem permanébis; et omnes ut vestiméntum veteráscent: et velut amíctum mutábis eos, et mutabúntur: tu autem idem ipse es, et anni tui non defícient."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Hebreus."},{"k":"ref","t":"Heb 1:1-12"},{"k":"text","t":"Deus, que falara muitas vezes e de muitas maneiras a nossos pais pelos Profetas, falou-nos nos últimos tempos pelo seu Filho, que constituíra herdeiro de todas as coisas, e por quem, também, criou os séculos, o qual, sendo a irradiação esplendorosa da sua glória e a figura da sua substância e sustentando todas as coisas com sua palavra onipotente depois de nos haver purificado dos nossos pecados, assentou-se à dextra da majestade divina, no mais alto dos céus, tanto mais superior aos Anjos quanto mais excelente e maior é o nome que herdou. Com efeito, a qual dos Anjos disse Deus estas palavras: “Tu és o meu Filho, gerei-te hoje?”. E ainda estoutras: “Eu serei sen Pai e Ele será para mim Filho?”. E também, quando mandou o seu primogênito ao mundo, disse: “Que todos os Anjos de Deus O adorem!”. E, pelo que respeita aos Anjos, a Escritura diz: “Ele, que aos Anjos faz ventos e aos seus ministros chamas de fogo”. Mas a respeito do Filho exprime-se assim: “Vosso trono, ó Deus, será eterno; o cetro da vossa realeza será um cetro de justiça e de retidão. Vós amastes a justiça e odiastes a iniquidade. Por isso, ó Deus, o vosso Deus (o Pai) Vos ungiu com o bálsamo da alegria, mais ainda do que àqueles que convosco participam da glória”. E também disse: “Vós, Senhor, no princípio criastes a terra; os céus são obra das vossas mãos. Eles perecerão, mas Vós permanecereis; eles envelhecerão todos, como um vestido, e Vós os mudareis, como se fossem um manto, e ficarão mudados; mas Vós sois sempre o mesmo, e os anos não acabarão para Vós”."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 97:3; 97:2"},{"k":"text","t":"Vidérunt omnes fines terræ salutare Dei nostri: jubiláte Deo, omnis terra."},{"k":"V","t":"Notum fecit Dominus salutare suum: ante conspéctum géntium revelávit justitiam suam. Allelúja, allelúja."},{"k":"V","t":"Dies sanctificátus illúxit nobis: veníte, gentes, et adoráte Dóminum: quia hódie descéndit lux magna super terram. Allelúja."}],"pt":[{"k":"ref","t":"Sl 97:3; 97:2"},{"k":"text","t":"Toda a terra viu o Salvador, que o nosso Deus enviou: aclamai Deus, ó povos de toda a terra."},{"k":"V","t":"O Senhor manifestou o Salvador, que havia prometido: e manifestou a sua justiça aos olhos dos povos. Aleluia, aleluia."},{"k":"V","t":"Um dia de santidade resplandeceu para nós: vinde, ó povos, e adorai o Senhor: pois hoje desceu a grande luz à terra. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Initium ++ sancti Evangélii secúndum Joánnem"},{"k":"ref","t":"Joann 1:1-14"},{"k":"text","t":"In princípio erat Verbum, et Verbum erat apud Deum, et Deus erat Verbum. Hoc erat in princípio apud Deum. Omnia per ipsum facta sunt: et sine ipso factum est nihil, quod factum est: in ipso vita erat, et vita erat lux hóminum: et lux in ténebris lucet, et ténebræ eam non comprehendérunt. Fuit homo missus a Deo, cui nomen erat Joánnes. Hic venit in testimónium, ut testimónium perhibéret de lúmine, ut omnes créderent per illum. Non erat ille lux, sed ut testimónium perhibéret de lúmine. Erat lux vera, quæ illúminat omnem hóminem veniéntem in hunc mundum. In mundo erat, et mundus per ipsum factus est, et mundus eum non cognóvit. In própria venit, et sui eum non recepérunt. Quotquot autem recepérunt eum, dedit eis potestátem fílios Dei fíeri, his, qui credunt in nómine ejus: qui non ex sanguínibus, neque ex voluntáte carnis, neque ex voluntáte viri, sed ex Deo nati sunt. (Hic genuflectitur) Et Verbum caro factum est, et habitávit in nobis: et vídimus glóriam ejus, glóriam quasi Unigéniti a Patre, plenum grátiæ et veritátis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 1:1-14"},{"k":"text","t":"No princípio existia o Verbo, e o Verbo estava com Deus, e o Verbo era Deus. Este estava no princípio com Deus. Todas as coisas foram por Ele criadas, e nada daquilo que foi criado teria sido criado sem Ele. N’Ele havia vida, e a vida era a luz dos homens. A luz resplandeceu nas trevas, mas as trevas a não receberam. Apareceu um homem, mandado por Deus, e o seu nome era João, o qual veio como testemunha, para dar testemunho da luz, a fim de que por ele todos acreditassem. Ele não era a luz, mas aquele que havia de dar testemunho da luz. Existia a luz verdadeira, a luz que ilumina todo o homem que vem a este mundo. Ele estava no mundo, e o mundo, embora houvesse sido criado por Ele, O não conheceu. Veio ao que era seu, e os seus O não receberam. Porém, Ele a todos quantos O receberam e aos que acreditaram no seu nome deu o poder de serem filhos de Deus, os quais não nasceram do sangue, nem do desejo da carne, mas somente da vontade de Deus. E o Verbo fez-se carne (genuflecte-se) e habitou entre nós; e contemplamos a sua glória, como era própria do Filho Unigênito do Pai, cheio de graça e de verdade."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 88:12; 88:15"},{"k":"text","t":"Tui sunt cœli et tua est terra: orbem terrárum et plenitúdinem ejus tu fundásti: justítia et judícium præparátio sedis tuæ."}],"pt":[{"k":"ref","t":"Sl 88:12; 88:15"},{"k":"text","t":"A Vós, Senhor, pertencem os céus e a terra; pois criastes o universo e tudo o que ele encerra. A justiça e a equidade são a base do vosso trono."}]},"Secreta":{"la":[{"k":"text","t":"Obláta, Dómine, múnera, nova Unigéniti tui Nativitáte sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eundem"}],"pt":[{"k":"text","t":"Santificai, Senhor, pelo novo Nascimento do vosso Filho Unigênito, as oblatas que Vos apresentamos, e purificai-nos das manchas dos nossos pecados."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eundem"}]},"Communio":{"la":[{"k":"ref","t":"Ps 97:3"},{"k":"text","t":"Vidérunt omnes fines terræ salutáre Dei nostri."}],"pt":[{"k":"ref","t":"Sl 97:3"},{"k":"text","t":"Toda a terra viu o Salvador que o nosso Deus enviou."}]},"Postcommunio":{"la":[{"k":"text","t":"Præsta, quǽsumus, omnípotens Deus: ut natus hódie Salvátor mundi, sicut divínæ nobis generatiónis est auctor; ita et immortalitátis sit ipse largítor:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Ó Deus onipotente, dignai-Vos permitir que, assim como o Salvador do mundo, nascendo neste dia, nos comunicou a geração divina, assim também nos conceda a imortalidade."},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]}}},{"id":"epi","la":"In Epiphania Domini","pt":"Epifania do Senhor","color":"albus","classis":1,"tempus":"epiphaniae","date":"01-06","gloria":true,"credo":true,"praef":"Epi","comm":"Epi","genuflectGospel":"procidéntes adoravérunt eum","notes":["No Evangelho, às palavras “et procidentes adoraverunt eum”, o celebrante e todos genuflectem.","Communicantes próprio da Epifania."],"source":"Sancti/01-06","parts":{"Introitus":{"la":[{"k":"ref","t":"Malach 3:1; 1 Par 29:12"},{"k":"text","t":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."},{"k":"ref","t":"Ps 71:1"},{"k":"text","t":"Deus, judícium tuum Regi da: et justítiam tuam Fílio Regis."},{"k":"gloriapatri"},{"k":"text","t":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."}],"pt":[{"k":"ref","t":"Ml 3:1; 1 Cr. 29:12"},{"k":"text","t":"Eis que apareceu soberano Senhor: e traz empunhado o cetro da realeza, do poder e do império."},{"k":"ref","t":"Sl 71:1"},{"k":"text","t":"Ó Deus, concedei ao Rei a graça de saber julgar: e ao filho do Rei a vossa justiça."},{"k":"gloriapatri"},{"k":"text","t":"Eis que apareceu soberano Senhor: e traz empunhado o cetro da realeza, do poder e do império."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui hodiérna die Unigénitum tuum géntibus stella duce revelásti: concéde propítius; ut, qui jam te ex fide cognóvimus, usque ad contemplándam spéciem tuæ celsitúdinis perducámur."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eumdem"}],"pt":[{"k":"text","t":"Ó Deus, que neste dia manifestastes o vosso Filho Unigênito aos gentios, enviando-lhes uma estrela para os guiar até onde Ele estava, concedei-nos propício que, conhecendo-Vos nós, já, pela fé, consigamos contemplar face a face o esplendor da vossa majestade."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eundem"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Isaíæ Prophétæ"},{"k":"ref","t":"Is 60:1-6"},{"k":"text","t":"Surge, illumináre, Jerúsalem: quia venit lumen tuum, et glória Dómini super te orta est. Quia ecce, ténebræ opérient terram et calígo pópulos: super te autem oriétur Dóminus, et glória ejus in te vidébitur. Et ambulábunt gentes in lúmine tuo, et reges in splendóre ortus tui. Leva in circúitu óculos tuos, et vide: omnes isti congregáti sunt, venérunt tibi: fílii tui de longe vénient, et fíliæ tuæ de látere surgent. Tunc vidébis et áfflues, mirábitur et dilatábitur cor tuum, quando convérsa fúerit ad te multitúdo maris, fortitúdo géntium vénerit tibi. Inundátio camelórum opériet te, dromedárii Mádian et Epha: omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."}],"pt":[{"k":"text","t":"Lição do Profeta Isaías."},{"k":"ref","t":"Is 60:1-6"},{"k":"text","t":"Ergue-te e resplandece, Jerusalém, pois a tua luz raiou, e a glória do Senhor brilhou sobre ti. Enquanto as trevas cobrem a terra, e uma noite escura envolve os povos, eis que desponta sobre ti a aurora do Senhor; e a sua glória resplandece em ti. As nações caminharão, guiadas pelo clarão da tua luz, e os reis pelo fulgor da tua aurora. Ergue os teus olhos; volve-os em torno de ti e vê: todos se congregam e vêm a ti. Os teus filhos vêm de longe e as tuas filhas surgirão ao lado. Então, tu o verás e te encontrarás na opulência. O teu coração se alegrará e dilatará, pois, as riquezas do mar virão a ti; os tesouros das nações virão à tua posse! Numerosos camelos e dromedários de Mádian e de Efa virão a ti. Todos os de Sabá virão junto de ti, trazendo ouro e incenso e louvando o Senhor."}]},"Graduale":{"la":[{"k":"ref","t":"Isa 60:6; 60:1"},{"k":"text","t":"Omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."},{"k":"V","t":"Surge et illumináre, Jerúsalem: quia glória Dómini super te orta est. Allelúja, allelúja"},{"k":"ref","t":"Matt 2:2."},{"k":"text","t":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum. Allelúja."}],"pt":[{"k":"ref","t":"Is 60:6; 60:1"},{"k":"text","t":"Todos os de Sabá virão, trazendo ouro em incenso e louvando o Senhor."},{"k":"V","t":"Ergue-te, Jerusalém, e resplandece, porque a glória do Senhor brilhou sobre ti. Aleluia, aleluia."},{"k":"ref","t":"Mt 2:2"},{"k":"text","t":"Vimos a sua estrela no Oriente e viemos com ofertas adorar o Senhor. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 2:1-12"},{"k":"text","t":"Cum natus esset Jesus in Béthlehem Juda in diébus Heródis regis, ecce, Magi ab Oriénte venerunt Jerosólymam, dicéntes: Ubi est, qui natus est rex Judæórum? Vidimus enim stellam ejus in Oriénte, et vénimus adoráre eum. Audiens autem Heródes rex, turbatus est, et omnis Jerosólyma cum illo. Et cóngregans omnes principes sacerdotum et scribas pópuli, sciscitabátur ab eis, ubi Christus nasceretur. At illi dixérunt ei: In Béthlehem Judæ: sic enim scriptum est per Prophétam: Et tu, Béthlehem terra Juda, nequáquam mínima es in princípibus Juda; ex te enim éxiet dux, qui regat pópulum meum Israël. Tunc Heródes, clam vocátis Magis, diligénter dídicit ab eis tempus stellæ, quæ appáruit eis: et mittens illos in Béthlehem, dixit: Ite, et interrogáte diligénter de púero: et cum invenéritis, renuntiáte mihi, ut et ego véniens adórem eum. Qui cum audíssent regem, abiérunt. Et ecce, stella, quam víderant in Oriénte, antecedébat eos, usque dum véniens staret supra, ubi erat Puer. Vidéntes autem stellam, gavísi sunt gáudio magno valde. Et intrántes domum, invenérunt Púerum cum María Matre ejus, (hic genuflectitur) et procidéntes adoravérunt eum. Et, apértis thesáuris suis, obtulérunt ei múnera, aurum, thus et myrrham. Et respónso accépto in somnis, ne redírent ad Heródem, per aliam viam revérsi sunt in regiónem suam."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt 2:1-12"},{"k":"text","t":"Havendo Jesus nascido em Belém, de Judá, no tempo do rei Herodes, eis que vieram a Jerusalém os Magos do Oriente, dizendo: “Onde está o rei dos Judeus, que acaba de nascer? Pois vimos a sua estrela no Oriente e viemos adorá-l’O”. Logo que o rei Herodes ouviu esta notícia, ficou perturbado, assim como toda a gente de Jerusalém, convocando logo todos os príncipes dos sacerdotes e os escribas do povo, para saber deles onde deveria nascer Cristo. Responderam-lhe eles: “Em Belém, de Judá, pois está escrito pelo Profeta: “E tu, Belém, terra de Judá, não serás certamente a menos importante entre as terras principais de Judá, pois em ti nascerá o Rei, que governará o meu povo de Israel”. Então Herodes mandou chamar em segredo os Magos, informando-se com eles diligentemente acerca do tempo em que a estrela havia aparecido. E, enviando-os a Belém, disse-lhes: “Ide, procurai diligentemente o Menino, e, logo que O houverdes achado, avisai-me, para que eu vá, também, adorá-l’O”. Os Magos, tendo ouvido estas palavras, partiram. Ora, a estrela, que tinham visto no Oriente, ia adiante deles, até que, chegando ao lugar onde estava o Menino, parou. Quando os Magos viram a estrela, alegraram-se muito. Entrando, então, na casa, encontraram o Menino com Maria, sua mãe; e, de joelhos, O adoraram. (Ajoelhar) E, tendo aberto os seus tesouros, ofereceram-Lhe presentes de ouro, incenso e mirra. Depois, havendo tido em sonhos aviso de que não deveriam voltar a encontrar Herodes, retiraram-se por outro caminho para o seu país."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 71:10-11"},{"k":"text","t":"Reges Tharsis, et ínsulæ múnera ófferent: reges Arabum et Saba dona addúcent: et adorábunt eum omnes reges terræ, omnes gentes sérvient ei."}],"pt":[{"k":"ref","t":"Sl 71:10-11"},{"k":"text","t":"Os reis de Társis e as ilhas oferecer-Lhe-ão tributos: Os reis de Arábia e de Sabá levar-Lhe-ão ofertas; todos os reis da terra O adorarão; e todas as nações O servirão."}]},"Secreta":{"la":[{"k":"text","t":"Ecclésiæ tuæ, quǽsumus, Dómine, dona propítius intuere: quibus non jam aurum, thus et myrrha profertur; sed quod eisdem munéribus declarátur, immolátur et súmitur, Jesus Christus, fílius tuus, Dóminus noster:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Dignai-Vos olhar benigno, Senhor, para os dons que a vossa Igreja Vos oferece, não o ouro, o incenso e a mirra, mas o que estas dádivas representam, e que agora é imolado e dado em alimento, Jesus Cristo, vosso Filho, Nosso Senhor:"},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]},"Communio":{"la":[{"k":"ref","t":"Matt 2:2"},{"k":"text","t":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum."}],"pt":[{"k":"ref","t":"Mt 2:2"},{"k":"text","t":"Vimos a sua estrela no Oriente e viemos com ofertas adorar o Senhor."}]},"Postcommunio":{"la":[{"k":"text","t":"Præsta, quǽsumus, omnípotens Deus: ut, quæ sollémni celebrámus officio, purificátæ mentis intellegéntia consequámur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus onipotente, dignai-Vos purificar inteiramente o nosso espírito, a fim de que compreenda os mistérios que celebrámos neste solene ofício."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"septua","la":"Dominica in Septuagesima","pt":"Domingo da Septuagésima","color":"violaceus","classis":2,"tempus":"septuagesimae","date":"septua","gloria":false,"credo":true,"praef":"Trinitate","notes":["A partir da Septuagésima cessa o Aleluia; após o Gradual diz-se o Trato.","Não se diz o Glória."],"source":"Tempora/Quadp1-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 17:5; 17:6; 17:7"},{"k":"text","t":"Circumdedérunt me gémitus mortis, dolóres inférni circumdedérunt me: et in tribulatióne mea invocávi Dóminum, et exaudívit de templo sancto suo vocem meam."},{"k":"ref","t":"Ps 17:2-3"},{"k":"text","t":"Díligam te, Dómine, fortitúdo mea: Dóminus firmaméntum meum, et refúgium meum, et liberátor meus."},{"k":"gloriapatri"},{"k":"text","t":"Circumdedérunt me gémitus mortis, dolóres inférni circumdedérunt me: et in tribulatióne mea invocávi Dóminum, et exaudívit de templo sancto suo vocem meam."}],"pt":[{"k":"ref","t":"Sl 17:5-7"},{"k":"text","t":"Rodearam-me os gemidos da morte e cercaram-me as dores do inferno; mas na minha tribulação invoquei o Senhor, que lá no seu santo templo ouviu a minha voz."},{"k":"ref","t":"Sl 17:2-3"},{"k":"text","t":"Eu Vos amarei, Senhor, que sois a minha fortaleza, o meu sustentáculo, o meu refúgio e o meu libertador."},{"k":"gloriapatri"},{"k":"text","t":"Rodearam-me os gemidos da morte e cercaram-me as dores do inferno; mas na minha tribulação invoquei o Senhor, que lá no seu santo templo ouviu a minha voz."}]},"Oratio":{"la":[{"k":"text","t":"Preces pópuli tui, quǽsumus, Dómine, cleménter exáudi: ut, qui juste pro peccátis nostris afflígimur, pro tui nóminis glória misericórditer liberémur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ouvi benigno, Senhor, Vos rogamos, as preces do vosso povo, a fim de que nós, que estamos justamente aflitos com o peso dos nossos pecados, sejamos misericordiosamente livres, pela glória do vosso nome."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","t":"1 Cor 9:24-27; 10:1-5"},{"k":"text","t":"Fratres: Nescítis, quod ii, qui in stádio currunt, omnes quidem currunt, sed unus áccipit bravíum? Sic cúrrite, ut comprehendátis. Omnis autem, qui in agóne conténdit, ab ómnibus se ábstinet: et illi quidem, ut corruptíbilem corónam accípiant; nos autem incorrúptam. Ego ígitur sic curro, non quasi in incértum: sic pugno, non quasi áërem vérberans: sed castígo corpus meum, et in servitútem rédigo: ne forte, cum áliis prædicáverim, ipse réprobus effíciar. Nolo enim vos ignoráre, fratres, quóniam patres nostri omnes sub nube fuérunt, et omnes mare transiérunt, et omnes in Móyse baptizáti sunt in nube et in mari: et omnes eándem escam spiritálem manducavérunt, et omnes eúndem potum spiritálem bibérunt bibébant autem de spiritáli, consequénte eos, petra: petra autem erat Christus: sed non in plúribus eórum beneplácitum est Deo."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Coríntios"},{"k":"ref","t":"1 Cor. 9:24-27; 10:1-5"},{"k":"text","t":"Meus irmãos: Não sabeis que aqueles que correm no circo, todos correm, mas somente um ganha o prêmio? Correi, pois, de tal modo que o ganheis. Aqueles que combatem na arena abstêm-se de tudo; e procedem assim para alcançar uma coroa corruptível. Nós, porém, para alcançarmos uma coroa incorruptível. Eu também assim corro, mas não ao acaso; eu pelejo, mas não como quem fere o ar; pois castigo o meu corpo e o reduzo à servidão, com medo de que, depois de ter pregado aos outros, seja condenado. Ora, meus irmãos, não quero que ignoreis que nossos pais estiveram debaixo da nuvem, passaram o mar e todos foram batizados e guiados por Moisés na nuvem e no mar; nem mesmo que ignoreis que todos eles, também, comeram o mesmo alimento espiritual e beberam a mesma bebida. Com efeito, beberam em um rochedo espiritual, que os seguia, o qual era Cristo. Todavia, a maior parte deles não agradou a Deus."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 9:10-11; 9:19-20"},{"k":"text","t":"Adjútor in opportunitátibus, in tribulatióne: sperent in te, qui novérunt te: quóniam non derelínquis quæréntes te, Dómine,"},{"k":"V","t":"Quóniam non in finem oblívio erit páuperis: patiéntia páuperum non períbit in ætérnum: exsúrge, Dómine, non præváleat homo."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Ps 129:1-4"},{"k":"text","t":"De profúndis clamávi ad te. Dómine: Dómine, exáudi vocem meam."},{"k":"V","t":"Fiant aures tuæ intendéntes in oratiónem servi tui."},{"k":"V","t":"Si iniquitátes observáveris, Dómine: Dómine, quis sustinébit?"},{"k":"V","t":"Quia apud te propitiátio est, et propter legem tuam sustínui te, Dómine."}],"pt":[{"k":"ref","t":"Sl 9:10-11; 9:19-20"},{"k":"text","t":"Senhor, sois o nosso auxílio nas necessidades e nas tribulações: esperem, pois, em Vós aqueles que Vos conhecem, porque nunca abandonais os que Vos procuram. O infeliz não será sempre esquecido; a paciência do pobre não será frustrada para sempre. Erguei-Vos, para que o homem mau não triunfe."},{"k":"ref","t":"Sl 129:1-4"},{"k":"text","t":"Das profundezas do abismo clamei por Vós, Senhor: ouvi a minha voz."},{"k":"V","t":"Que os vossos ouvidos estejam atentos à voz deste vosso servo."},{"k":"V","t":"Se julgais as nossas iniquidades, Senhor, quem poderá subsistir ante Vós?"},{"k":"V","t":"Mas sois propício; por amor da vossa lei esperei em Vós."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 20:1-16"},{"k":"text","t":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Simile est regnum coelórum hómini patrifamílias, qui éxiit primo mane condúcere operários in víneam suam. Conventióne autem facta cum operáriis ex denário diúrno, misit eos in víneam suam. Et egréssus circa horam tértiam, vidit álios stantes in foro otiósos, et dixit illis: Ite et vos in víneam meam, et quod justum fúerit, dabo vobis. Illi autem abiérunt. Iterum autem éxiit circa sextam et nonam horam: et fecit simíliter. Circa undécimam vero éxiit, et invénit álios stantes, et dicit illis: Quid hic statis tota die otiósi? Dicunt ei: Quia nemo nos condúxit. Dicit illis: Ite et vos in víneam meam. Cum sero autem factum esset, dicit dóminus víneæ procuratóri suo: Voca operários, et redde illis mercédem, incípiens a novíssimis usque ad primos. Cum veníssent ergo qui circa undécimam horam vénerant, accepérunt síngulos denários. Veniéntes autem et primi, arbitráti sunt, quod plus essent acceptúri: accepérunt autem et ipsi síngulos denários. Et accipiéntes murmurábant advérsus patremfamílias, dicéntes: Hi novíssimi una hora fecérunt et pares illos nobis fecísti, qui portávimus pondus diéi et æstus. At ille respóndens uni eórum, dixit: Amíce, non facio tibi injúriam: nonne ex denário convenísti mecum? Tolle quod tuum est, et vade: volo autem et huic novíssimo dare sicut et tibi. Aut non licet mihi, quod volo, fácere? an óculus tuus nequam est, quia ego bonus sum? Sic erunt novíssimi primi, et primi novíssimi. Multi enim sunt vocáti, pauci vero elécti."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus"},{"k":"ref","t":"Mt 20:1-16"},{"k":"text","t":"Naquele tempo, disse Jesus a seus discípulos: “O reino dos céus é semelhante a um pai de família que sai da sua casa cedo para ajustar jornaleiros, para a sua vinha. E, tendo ajustado com eles dar a cada um por dia um dinheiro, mandou-os para a vinha. Cerca da hora terceira, saiu outra vez e viu que estavam ociosos na praça outros jornaleiros. Disse-lhes: “Ide, também, trabalhar para a minha vinha, e pagar-vos-ei o que for justo”; e eles foram. Saiu, ainda, cerca da hora sexta e cerca da hora nona, e fez a mesma coisa. Enfim, havendo saído cerca da hora undécima, encontrou outros e disse-lhes: “Porque estais todo o dia ociosos?”. Eles responderam: “Porque ninguém nos ajustou”. E disse-lhes: “Ide vós, também, para a minha vinha”. Quando era já pela tarde, disse o senhor da vinha ao seu intendente: “Chama os jornaleiros e paga-lhes os salários, começando pelos últimos e acabando nos primeiros”. Quando vieram os jornaleiros da hora undécima, receberam um dinheiro cada um. Vindo, por sua vez, os primeiros, cuidavam que receberiam mais; porém receberam, também, um dinheiro cada um. Então, estes, recebendo o dinheiro, murmuraram contra o pai de família, dizendo: “Estes últimos não trabalharam senão uma hora, e dais-lhes tanto como a nós, que aguentámos no dia inteiro o peso do trabalho e do calor?”. Mas o senhor, dirigindo-se a um deles, respondeu: “Meu amigo, não te faço injustiça. Não ajustaste comigo receber um dinheiro? Toma, pois, o que te pertence, e vai-te. Quanto a mim, quero dar a este último tanto como a ti. Porventura me não é lícito ser generoso para com quem quiser? Diz-me: o teu olho é mau, porque o meu é bom? Assim, os últimos serão os primeiros, e os primeiros serão os últimos; pois muitos são os chamados e poucos os escolhidos”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 91:2"},{"k":"text","t":"Bonum est confitéri Dómino, et psállere nómini tuo, Altíssime."}],"pt":[{"k":"ref","t":"Sl 91:2"},{"k":"text","t":"É bom louvar o Senhor; e cantar Salmos em honra do vosso nome, ó Altíssimo."}]},"Secreta":{"la":[{"k":"text","t":"Munéribus nostris, quǽsumus, Dómine, precibúsque suscéptis: et cœléstibus nos munda mystériis, et cleménter exáudi."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Recebendo as nossas ofertas e orações, Senhor, dignai-Vos purificar-nos por virtude dos vossos celestiais mistérios e ouvi misericordioso os nossos rogos."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 30:17-18"},{"k":"text","t":"Illúmina fáciem tuam super servum tuum, et salvum me fac in tua misericórdia: Dómine, non confúndar, quóniam invocávi te."}],"pt":[{"k":"ref","t":"Sl 30:17-18"},{"k":"text","t":"Fazei resplandecer a vossa face sobre este vosso servo, e salvai-me pela vossa misericórdia, Senhor; que eu não seja confundido, pois Vos invoquei."}]},"Postcommunio":{"la":[{"k":"text","t":"Fidéles tui, Deus, per tua dona firméntur: ut eadem et percipiéndo requírant, et quæréndo sine fine percípiant."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Que os vossos fiéis, ó Deus, sejam fortificados com vossos dons, a fim de que, recebendo-os, continuem a procurá-los, e, havendo-os achado, sirvam para a nossa eternidade."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"quad1","la":"Dominica I in Quadragesima","pt":"I Domingo da Quaresma","color":"violaceus","classis":1,"tempus":"quadragesimae","date":"quad1","gloria":false,"credo":true,"praef":"Quad","notes":["Prefácio da Quaresma.","O Trato “Qui habitat” (Salmo 90) é dos mais longos do Missal."],"source":"Tempora/Quad1-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 90:15; 90:16"},{"k":"text","t":"Invocábit me, et ego exáudiam eum: erípiam eum, et glorificábo eum: longitúdine diérum adimplébo eum."},{"k":"ref","t":"Ps 90:1"},{"k":"text","t":"Qui hábitat in adjutório Altíssimi, in protectióne Dei cœli commorábitur."},{"k":"gloriapatri"},{"k":"text","t":"Invocábit me, et ego exáudiam eum: erípiam eum, et glorificábo eum: longitúdine diérum adimplébo eum."}],"pt":[{"k":"ref","t":"Sl 90:15-16"},{"k":"text","t":"Invocar-me-á, e ouvi-lo-ei: livrá-lo-ei, e glorificá-lo-ei: conceder-lhe-ei longa vida."},{"k":"ref","t":"Sl 90:1"},{"k":"text","t":"Aquele que habita à sombra do Altíssimo descansará sob a proteção de Deus do céu."},{"k":"gloriapatri"},{"k":"text","t":"Invocar-me-á, e ouvi-lo-ei: livrá-lo-ei, e glorificá-lo-ei: conceder-lhe-ei longa vida."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui Ecclésiam tuam ánnua quadragesimáli observatióne puríficas: præsta famíliæ tuæ; ut, quod a te obtinére abstinéndo nítitur, hoc bonis opéribus exsequátur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus, que purificais a vossa Igreja com a observância anual da quaresma, concedei à vossa família que o que ela deseja alcançar pela abstinência o pratique com suas boas obras."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","t":"2 Cor 6:1-10."},{"k":"text","t":"Fratres: Exhortámur vos, ne in vácuum grátiam Dei recipiátis. Ait enim: Témpore accépto exaudívi te, et in die salútis adjúvi te. Ecce, nunc tempus acceptábile, ecce, nunc dies salútis. Némini dantes ullam offensiónem, ut non vituperétur ministérium nostrum: sed in ómnibus exhibeámus nosmetípsos sicut Dei minístros, in multa patiéntia, in tribulatiónibus, in necessitátibus, in angústiis, in plagis, in carcéribus, in seditiónibus, in labóribus, in vigíliis, in jejúniis, in castitáte, in sciéntia, in longanimitáte, in suavitáte, in Spíritu Sancto, in caritáte non ficta, in verbo veritátis, in virtúte Dei, per arma justítiæ a dextris et a sinístris: per glóriam et ignobilitátem: per infámiam et bonam famam: ut seductóres et veráces: sicut qui ignóti et cógniti: quasi moriéntes et ecce, vívimus: ut castigáti et non mortificáti: quasi tristes, semper autem gaudéntes: sicut egéntes, multos autem locupletántes: tamquam nihil habéntes et ómnia possidéntes."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Coríntios."},{"k":"ref","t":"2 Cor. 6:1-10"},{"k":"text","t":"Meus irmãos: Vos exortamos a que não recebais em vão a graça de Deus, pois Ele diz: “No tempo propício ouço-te, e no dia da salvação socorro-te”. Eis, pois, agora o tempo propício; eis agora os dias da salvação. Não dêmos a ninguém escândalo, para que o nosso ministério não seja censurado; mas portemo-nos em tudo como ministros de Deus, com muita paciência nas tribulações, nas necessidades, nas angústias, nas ofensas corporais, nas prisões, nas sedições, nos trabalhos, nas vigílias, nos jejuns, pela castidade, pela ciência, pela longanimidade, pela mansidão, pelo Espírito Santo, pela caridade sincera, pela palavra da verdade, pelo poder de Deus, pelas armas da justiça com que devemos combater, à direita ou à esquerda, na honra ou na desonra, na boa reputação ou na infâmia; sendo julgados sedutores, ainda que sejamos sinceros e verdadeiros; sendo reputados desconhecidos, e, contudo, sendo bem conhecidos; pensando eles que éramos moribundos, mas estando bem vivos; como castigados, mas escapando à morte; como tristes, mas sempre alegres; como pobres, mas enriquecendo os outros; como não tendo nada, mas possuindo tudo."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 90:11-12"},{"k":"text","t":"Angelis suis Deus mandávit de te, ut custódiant te in ómnibus viis tuis."},{"k":"V","t":"In mánibus portábunt te, ne umquam offéndas ad lápidem pedem tuum."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Ps 90:1-7; 90:11-16"},{"k":"text","t":"Qui hábitat in adjutório Altíssimi, in protectióne Dei cœli commorántur."},{"k":"V","t":"Dicet Dómino: Suscéptor meus es tu et refúgium meum: Deus meus, sperábo in eum."},{"k":"V","t":"Quóniam ipse liberávit me de láqueo venántium et a verbo áspero."},{"k":"V","t":"Scápulis suis obumbrábit tibi, et sub pennis ejus sperábis."},{"k":"V","t":"Scuto circúmdabit te véritas ejus: non timébis a timóre noctúrno."},{"k":"V","t":"A sagítta volánte per diem, a negótio perambulánte in ténebris, a ruína et dæmónio meridiáno."},{"k":"V","t":"Cadent a látere tuo mille, et decem mília a dextris tuis: tibi autem non appropinquábit."},{"k":"V","t":"Quóniam Angelis suis mandávit de te, ut custódiant te in ómnibus viis tuis."},{"k":"V","t":"In mánibus portábunt te, ne umquam offéndas ad lápidem pedem tuum,"},{"k":"V","t":"Super áspidem et basilíscum ambulábis, et conculcábis leónem et dracónem."},{"k":"V","t":"Quóniam in me sperávit, liberábo eum: prótegam eum, quóniam cognóvit nomen meum,"},{"k":"V","t":"Invocábit me, et ego exáudiam eum: cum ipso sum in tribulatióne,"},{"k":"V","t":"Erípiam eum et glorificábo eum: longitúdine diérum adimplébo eum, et osténdam illi salutáre meum."}],"pt":[{"k":"ref","t":"Sl 90:11-12"},{"k":"text","t":"Deus ordenou aos seus Anjos que te guardassem em todos teus caminhos."},{"k":"V","t":"Levar-te-ão nas suas mãos, para que não tropeces nas pedras."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Sl 90:1-7, 11-16."},{"k":"text","t":"Aquele que habita à sombra do Altíssimo descansará sob a proteção de Deus do céu."},{"k":"V","t":"Ele dirá ao Senhor: sois o meu protetor e o meu refúgio; sois o meu Deus, em quem confio!"},{"k":"V","t":"Pois livrastes-me do laço do caçador e das palavras funestas!"},{"k":"V","t":"O Senhor te acolherá sob a sua proteção: agasalhar-te-á sob as suas asas!"},{"k":"V","t":"Sua fidelidade é como um escudo: livrar-te-á dos terrores da noite."},{"k":"V","t":"Da seta, que voa de dia; das traições, que se tramam durante a noite; e dos assaltos do demônio, em pleno meio-dia."},{"k":"V","t":"Cairão mil à tua esquerda e dez mil à tua direita; mas tu não serás atingido!"},{"k":"V","t":"Pois Deus ordenou aos seus Anjos que te guardassem em todos teus caminhos."},{"k":"V","t":"Levar-te-ão nas suas mãos, para que não tropeces nas pedras."},{"k":"V","t":"Caminharás sobre a víbora e o basilisco; pisarás o leão e o dragão."},{"k":"V","t":"Visto que esperou em mim, livrá-lo-ei; e protegê-lo-ei, pois, conhece e invoca o meu nome."},{"k":"V","t":"Invocar-me-á e ouvi-lo-ei: estarei com ele nos dias da tribulação."},{"k":"V","t":"Livrá-lo-ei e glorificá-lo-ei, conceder-lhe-ei longa vida e mostrar-lhe-ei a minha salvação."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 4:1-11"},{"k":"text","t":"In illo témpore: Ductus est Jesus in desértum a Spíritu, ut tentarétur a diábolo. Et cum jejunásset quadragínta diébus et quadragínta nóctibus, postea esúriit. Et accédens tentátor, dixit ei: Si Fílius Dei es, dic, ut lápides isti panes fiant. Qui respóndens, dixit: Scriptum est: Non in solo pane vivit homo, sed in omni verbo, quod procédit de ore Dei. Tunc assúmpsit eum diábolus in sanctam civitátem, et státuit eum super pinnáculum templi, et dixit ei: Si Fílius Dei es, mitte te deórsum. Scriptum est enim: Quia Angelis suis mandávit de te, et in mánibus tollent te, ne forte offéndas ad lápidem pedem tuum. Ait illi Jesus: Rursum scriptum est: Non tentábis Dóminum, Deum tuum. Iterum assúmpsit eum diábolus in montem excélsum valde: et ostendit ei ómnia regna mundi et glóriam eórum, et dixit ei: Hæc ómnia tibi dabo, si cadens adoráveris me. Tunc dicit ei Jesus: Vade, Sátana; scriptum est enim: Dóminum, Deum tuum, adorábis, et illi soli sérvies. Tunc relíquit eum diábolus: et ecce, Angeli accessérunt et ministrábant ei."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt. 4:1-11"},{"k":"text","t":"Naquele tempo, foi Jesus conduzido ao deserto pelo espírito, para ser tentado pelo demônio. E, havendo jejuado quarenta dias e quarenta noites, teve fome. Então o tentador aproximou-se de Jesus e disse-Lhe: “Se sois o filho de Deus, mandai que estas pedras se tornem em pães”. Jesus respondeu: “Está escrito: “não só de pão vive o homem, mas de toda a palavra que procede da boca de Deus”. Então o demônio conduziu Jesus à cidade santa; e, levando-O até ao pináculo do templo, disse-Lhe: “Se sois o Filho de Deus, lançai-Vos daqui para baixo, pois está escrito: “ordenou aos seus Anjos que Vos levassem nas suas mãos para que os vossos pés não tropeçassem nas pedras”. Jesus disse-lhe: “Também está escrito “não tentareis ao Senhor, teu Deus”. Ainda o demônio conduziu Jesus a um monte muito elevado; e, mostrando-Lhe todos os reinos do mundo, revestidos das suas glórias, disse-Lhe: “Dar-Vos-ei tudo isto, se, de joelhos, me adorardes”. Então disse-lhe Jesus: “Retira-te, Satanás, pois está escrito: “Adorarás ao Senhor, teu Deus, e só a Ele servirás”, Logo o demônio deixou Jesus, aproximando-se d’Ele os Anjos, que O serviram."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 90:4-5"},{"k":"text","t":"Scápulis suis obumbrábit tibi Dóminus, et sub pennis ejus sperábis: scuto circúmdabit te véritas ejus."}],"pt":[{"k":"ref","t":"Sl 90:4-5"},{"k":"text","t":"O Senhor vos acolherá à sua sombra: e sob as suas asas vos esperará: a sua fidelidade proteger-vos-á, como um escudo."}]},"Secreta":{"la":[{"k":"text","t":"Sacrifícium quadragesimális inítii sollémniter immolámus, te, Dómine, deprecántes: ut, cum epulárum restrictióne carnálium, a noxiis quoque voluptátibus temperémus."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, imolamos solenemente este sacrifício no princípio da Quaresma, suplicando-Vos que, fazendo-nos restringir o uso das carnes, nos abstenhamos também dos prazeres funestos."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 90:4-5"},{"k":"text","t":"Scápulis suis obumbrábit tibi Dóminus, et sub pennis ejus sperábis: scuto circúmdabit te véritas ejus."}],"pt":[{"k":"ref","t":"Sl 90:4-5"},{"k":"text","t":"O Senhor vos acolherá à sua sombra: e sob as suas asas vos esperará: a sua verdade proteger-vos-á, como um escudo."}]},"Postcommunio":{"la":[{"k":"text","t":"Tui nos, Dómine, sacraménti libátio sancta restáuret: et a vetustáte purgátos, in mystérii salutáris fáciat transíre consórtium."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Que a participação, que tomámos, no vosso sacramento, Senhor, nos restaure; e que, despojando-nos do “homem velho”, nos faça alcançar o mistério da salvação."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"laetare","la":"Dominica IV in Quadragesima (Lætare)","pt":"IV Domingo da Quaresma — Lætare","color":"rosaceus","classis":1,"tempus":"quadragesimae","date":"quad4","gloria":false,"credo":true,"praef":"Quad","notes":["Domingo Lætare: permite-se a cor rosácea."],"source":"Tempora/Quad4-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Is 66:10 et 11"},{"k":"text","t":"Lætáre, Jerúsalem: et convéntum fácite, omnes qui dilígitis eam: gaudéte cum lætítia, qui in tristítia fuístis: ut exsultétis, et satiémini ab ubéribus consolatiónis vestræ."},{"k":"ref","t":"Ps 121:1."},{"k":"text","t":"Lætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus."},{"k":"gloriapatri"},{"k":"text","t":"Lætáre, Jerúsalem: et convéntum fácite, omnes qui dilígitis eam: gaudéte cum lætítia, qui in tristítia fuístis: ut exsultétis, et satiémini ab ubéribus consolatiónis vestræ."}],"pt":[{"k":"ref","t":"Is 66:10-11"},{"k":"text","t":"Rejubilai, ó Jerusalém; ó vós todos, que a amais, uni-vos com júbilo; exultai de alegria, ó vós, que tendes estado tristes: e ficareis alegres e saciados com o leite das suas consolações."},{"k":"ref","t":"Sl 121:1"},{"k":"text","t":"Alegrei-me com estas palavras que me disseram: Iremos à Casa do Senhor."},{"k":"gloriapatri"},{"k":"text","t":"Rejubilai, ó Jerusalém; ó vós todos, que a amais, uni-vos com júbilo; exultai de alegria, ó vós, que tendes estado tristes: e ficareis alegres e saciados com o leite das suas consolações."}]},"Oratio":{"la":[{"k":"text","t":"Concéde, quǽsumus, omnípotens Deus: ut, qui ex mérito nostræ actiónis afflígimur, tuæ grátiæ consolatióne respirémus."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus onipotente, Vos suplicamos, visto que estamos justamente aflitos com o peso dos nossos pecados, concedei-nos que sejamos aliviados com a consolação da vossa graça."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas"},{"k":"ref","t":"Gal 4:22-31"},{"k":"text","t":"Fratres: Scriptum est: Quóniam Abraham duos fílios hábuit: unum de ancílla, et unum de líbera. Sed qui de ancílla, secúndum carnem natus est: qui autem de líbera, per repromissiónem: quæ sunt per allegoríam dicta. Hæc enim sunt duo testaménta. Unum quidem in monte Sina, in servitútem génerans: quæ est Agar: Sina enim mons est in Arábia, qui conjúnctus est ei, quæ nunc est Jerúsalem, et servit cum fíliis suis. Illa autem, quæ sursum est Jerúsalem, líbera est, quæ est mater nostra. Scriptum est enim: Lætáre, stérilis, quæ non paris: erúmpe, et clama, quæ non párturis: quia multi fílii desértæ, magis quam ejus, quæ habet virum. Nos autem, fratres, secúndum Isaac promissiónis fílii sumus. Sed quómodo tunc is, qui secúndum carnem natus fúerat, persequebátur eum, qui secúndum spíritum: ita et nunc. Sed quid dicit Scriptúra? Ejice ancíllam et fílium ejus: non enim heres erit fílius ancíllæ cum fílio líberæ. Itaque, fratres, non sumus ancíllæ fílii, sed líberæ: qua libertáte Christus nos liberávit."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Gálatas."},{"k":"ref","t":"Gl 4:22-31"},{"k":"text","t":"Meus irmãos: Está escrito que Abraão teve dois filhos: um da escrava e outro da mulher livre. O da escrava nasceu segundo a carne, enquanto que o da mulher livre nasceu segundo a promessa. Digo-vos estas coisas em sentido alegórico: estas mulheres são as duas alianças. A primeira (a do Sinai) gera para a escravidão: assim Agar. Com efeito, o Sinai é um monte situado na Arábia, o qual corresponde à atual Jerusalém, que está sob a escravidão, assim como seus filhos. Porém a outra (a Jerusalém do alto) é livre. Esta é a nossa mãe; pis está escrito: “Alegra-te, ó estéril, que não geras! Regozija-te; canta sonoramente, ó tu, que não geras; pois os filhos da abandonada serão mais numerosos do que os da mulher casada”. Nós, meus irmãos, somos os filhos da promessa, figurados em Isaque; e, como então, aquele que nascia segundo a carne perseguia aquele que nascia segundo o espírito, assim acontece agora. Que diz a Escritura? “Expulsa a escrava e o seu filho, porque o filho da escrava não será herdeiro como o filho da mulher livre”. Assim, meus irmãos, nós não somos filhos da escrava, mas da mulher livre, em cuja liberdade Cristo nos libertou."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 121:1, 7"},{"k":"text","t":"Lætátus sum in his, quæ dicta sunt mihi: in domum Dómini íbimus."},{"k":"V","t":"Fiat pax in virtúte tua: et abundántia in túrribus tuis."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Ps 124:1-2"},{"k":"text","t":"Qui confídunt in Dómino, sicut mons Sion: non commovébitur in ætérnum, qui hábitat in Jerúsalem."},{"k":"V","t":"Montes in circúitu ejus: et Dóminus in circúitu pópuli sui, ex hoc nunc et usque in sǽculum."}],"pt":[{"k":"ref","t":"Sl 121: 1, 7."},{"k":"text","t":"Alegrei-me com estas palavras que me disseram: Iremos à Casa do Senhor."},{"k":"V","t":"Que a paz reine dentro dos teus muros: e a abundância nos teus palácios."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Sl 124:1-2"},{"k":"text","t":"Aqueles que confiam no Senhor estão firmes, como o monte Sião. Aquele que habita em Jerusalém nunca será abalado."},{"k":"V","t":"O Senhor cerca com montanhas o seu povo, e fica em torno dele agora e em todos os séculos."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem"},{"k":"ref","t":"Joann 6:1-15"},{"k":"text","t":"In illo témpore: Abiit Jesus trans mare Galilǽæ, quod est Tiberíadis: et sequebátur eum multitúdo magna, quia vidébant signa, quæ faciébat super his, qui infirmabántur. Súbiit ergo in montem Jesus: et ibi sedébat cum discípulis suis. Erat autem próximum Pascha, dies festus Judæórum. Cum sublevásset ergo óculos Jesus et vidísset, quia multitúdo máxima venit ad eum, dixit ad Philíppum: Unde emémus panes, ut mandúcent hi? Hoc autem dicébat tentans eum: ipse enim sciébat, quid esset factúrus. Respóndit ei Philíppus: Ducentórum denariórum panes non suffíciunt eis, ut unusquísque módicum quid accípiat. Dicit ei unus ex discípulis ejus, Andréas, frater Simónis Petri: Est puer unus hic, qui habet quinque panes hordeáceos et duos pisces: sed hæc quid sunt inter tantos? Dixit ergo Jesus: Fácite hómines discúmbere. Erat autem fænum multum in loco. Discubuérunt ergo viri, número quasi quinque míllia. Accépit ergo Jesus panes, et cum grátias egísset, distríbuit discumbéntibus: simíliter et ex píscibus, quantum volébant. Ut autem impléti sunt, dixit discípulis suis: Collígite quæ superavérunt fragménta, ne péreant. Collegérunt ergo, et implevérunt duódecim cóphinos fragmentórum ex quinque pánibus hordeáceis, quæ superfuérunt his, qui manducáverant. Illi ergo hómines cum vidíssent, quod Jesus fécerat signum, dicébant: Quia hic est vere Prophéta, qui ventúrus est in mundum. Jesus ergo cum cognovísset, quia ventúri essent, ut ráperent eum et fácerent eum regem, fugit íterum in montem ipse solus."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 6:1-15"},{"k":"text","t":"Naquele tempo, foi Jesus para a outra margem do mar da Galileia ou de Tiberíades, acompanhando-O grande multidão; pois viam os milagres que operava, curando os doentes. Jesus subiu a um monte, e aí se assentou com seus discípulos. Ora a Páscoa, que era a principal festa dos judeus, estava. Próxima. E, levantando Jesus os olhos, viu que grande multidão de povo estava com Ele. Então, disse a Filipe: “Onde compraremos pão para tanta gente?”. Ele dizia isto para experimentar Filipe, pois bem sabia o que havia de fazer. Filipe respondeu-Lhe: “Duzentos dinheiros de pão não bastarão para que cada um receba um bocado!”. Mas um dos discípulos, André, irmão de Simão-Pedro, disse-Lhe: “Está aí um homem que tem cinco pães de aveia e dois peixes; porém, que é isto para tanta gente?!...” Jesus disse: “Mandai-os assentar todos”. Assentaram-se eles, sendo cerca de cinco mil! Então Jesus tomou os pães, e, tendo dado graças, distribuiu-os; do mesmo modo distribuiu os peixes. E comeu cada um quanto quis! Quando já estavam fartos, disse Jesus a seus discípulos: “Recolhei os sobejos, para que se não percam”. Recolheram-nos eles, enchendo doze cestos com os bocados, que haviam sobejado, dos cinco pães de aveia! Então, estes homens, vendo o milagre que Jesus acabava de fazer, diziam: “Verdadeiramente este é o Profeta que deve vir ao mundo!”. Porém Jesus, sabendo que eles queriam aclamá-l’O Rei, fugiu só para o monte."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 134:3, 6"},{"k":"text","t":"Laudáte Dóminum, quia benígnus est: psállite nómini ejus, quóniam suávis est: ómnia, quæcúmque vóluit, fecit in cœlo et in terra."}],"pt":[{"k":"ref","t":"Sl 134:3, 6."},{"k":"text","t":"Louvai o Senhor, porque Ele é bom: Cantai hinos em louvor do seu nome, porque Ele é suave. O Senhor criou no céu e na terra tudo quanto quis."}]},"Secreta":{"la":[{"k":"text","t":"Sacrifíciis præséntibus, Dómine, quǽsumus, inténde placátus: ut et devotióni nostræ profíciant et salúti."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, Vos suplicamos, olhai aplacado para este sacrifício; e que ele alente a nossa piedade e nos alcance a salvação."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 121:3-4"},{"k":"text","t":"Jerúsalem, quæ ædificátur ut cívitas, cujus participátio ejus in idípsum: illuc enim ascendérunt tribus, tribus Dómini, ad confiténdum nómini tuo, Dómine."}],"pt":[{"k":"ref","t":"Sl 121:3-4"},{"k":"text","t":"Jerusalém é uma cidade tão bem edificada, que está agrupada em um conjunto. Foi lá que subiram as tribos (as tribos do Senhor) para louvar o vosso nome, ó Senhor."}]},"Postcommunio":{"la":[{"k":"text","t":"Da nobis, quǽsumus, miséricors Deus: ut sancta tua, quibus incessánter explémur, sincéris tractémus obséquiis, et fidéli semper mente sumámus."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus de misericórdia, concedei-nos a graça de nos aproximarmos com respeito sincero dos vossos sagrados mistérios, de que fomos saciados, e de os recebermos sempre com espírito de fé."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"joseph","la":"S. Joseph Sponsi B.M.V. Confessoris","pt":"São José, Esposo da Bem-aventurada Virgem Maria","color":"albus","classis":1,"tempus":"quadragesimae","date":"03-19","gloria":true,"credo":true,"praef":"Joseph","praefIns":{"la":"Festivitáte","pt":"Festividade"},"notes":["Festa de I classe, mesmo na Quaresma: Glória e Credo, Prefácio de São José."],"source":"Sancti/03-19","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 91:13-14"},{"k":"text","t":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."},{"k":"ref","t":"Ps 91:2"},{"k":"text","t":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"gloriapatri"},{"k":"text","t":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."}],"pt":[{"k":"ref","t":"Sl 91:13-14"},{"k":"text","t":"O justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano: Ele está plantado na casa do Senhor, nos átrios da casa do nosso Deus. ((T. P. Aleluia, aleluia.))"},{"k":"ref","t":"Sl 91:2"},{"k":"text","t":"É bom louvar o Senhor: e cantar hinos em honra do vosso nome, ó Altíssimo."},{"k":"gloriapatri"},{"k":"text","t":"O justo florescerá, como a palmeira, e multiplicar-se-á, como o cedro do Líbano: Ele está plantado na casa do Senhor, nos átrios da casa do nosso Deus. ((T. P. Aleluia, aleluia.))"}]},"Oratio":{"la":[{"k":"text","t":"Sanctíssimæ Genetrícis tuæ Sponsi, quǽsumus, Dómine, méritis adjuvémur: ut, quod possibílitas nostra non óbtinet, ejus nobis intercessióne donétur:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Senhor, Vos suplicamos, permiti que sejamos auxiliados pelos méritos do Esposo da vossa Santíssima Mãe, a fim de que aquelas graças que não temos possibilidade de obter por causa da nossa fraqueza as alcancemos pela sua intercessão."},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]},"Lectio":{"la":[{"k":"text","t":"Léctio libri Sapiéntiæ"},{"k":"ref","t":"Eccli 45:1-6"},{"k":"text","t":"Diléctus Deo et homínibus, cujus memória in benedictióne est. Símilem illum fecit in glória sanctórum, et magnificávit eum in timóre inimicórum, et in verbis suis monstra placávit. Glorificávit illum in conspéctu regum, et jussit illi coram pópulo suo, et osténdit illi glóriam suam. In fide et lenitáte ipsíus sanctum fecit illum, et elégit eum ex omni carne. Audívit enim eum et vocem ipsíus, et indúxit illum in nubem. Et dedit illi coram præcépta, et legem vitæ et disciplínæ."}],"pt":[{"k":"text","t":"Lição do Livro da Sabedoria."},{"k":"ref","t":"Sb 45:1-6"},{"k":"text","t":"Foi amado de Deus e dos homens; a sua memória é uma bênção. O Senhor deu-lhe uma glória, semelhante à dos Santos; tornou-o temeroso e invencível perante seus inimigos; e com suas palavras aplacou os monstros. O Senhor honrou-o diante dos reis; deu-lhe as suas ordens diante do seu povo; e mostrou-lhe a sua glória. O Senhor santificou-o pela sua fé e mansidão; e escolheu-o entre todos os homens. Deus escutou-o; ouviu a sua voz; e fê-lo entrar na nuvem. Então, deu-lhe face a face os seus preceitos e a lei da vida e da doutrina."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 20:4-5"},{"k":"text","t":"Dómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"V","t":"Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Ps 111:1-3"},{"k":"text","t":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"V","t":"Potens in terra erit semen ejus: generátio rectórum benedicétur."},{"k":"V","t":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi."}],"pt":[{"k":"ref","t":"Sl 20:4-5"},{"k":"text","t":"Senhor, concedestes-lhe bênçãos escolhidas as mais suaves; e impusestes na sua cabeça uma coroa de pedras preciosas."},{"k":"V","t":"Concedestes-lhe a vida, que ele Vos suplicara, e prolongastes-lhe a duração dos seus dias pelos séculos dos séculos."},{"k":"ref","t":"Sl 111:1-3"},{"k":"text","t":"Bem-aventuradourado o varão que teme o Senhor e que emprega todo o zelo em obedecer-Lhe."},{"k":"V","t":"Sua descendência será poderosa na terra; pois a geração dos justos será abençoada."},{"k":"V","t":"Na sua casa haverá glória e riqueza: e a sua justiça subsistirá em todos os séculos dos séculos."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 1:18-21"},{"k":"text","t":"Cum esset desponsáta Mater Jesu María Joseph, ántequam convenírent, invénta est in útero habens de Spíritu Sancto. Joseph autem, vir ejus, cum esset justus et nollet eam tradúcere, vóluit occúlte dimíttere eam. Hæc autem eo cogitánte, ecce, Angelus Dómini appáruit in somnis ei, dicens: Joseph, fili David, noli timére accípere Maríam cónjugem tuam: quod enim in ea natum est, de Spíritu Sancto est. Páriet autem fílium, et vocábis nomen ejus Jesum: ipse enim salvum fáciet pópulum suum a peccátis eórum."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt 1:18-21"},{"k":"text","t":"Naquele tempo, estando Maria, Mãe de Jesus, desposada com José, achou este que, sem que os dois houvessem coabitado, havia ela concebido por obra do Espírito Santo. Então José, seu marido, que era justo e não queria difamá-la, resolveu abandoná-la secretamente. E, pensando nisto, apareceu-lhe um Anjo do Senhor em sonhos, dizendo-lhe: “José, filho de David, não temas receber Maria como tua esposa porque Aquele que ela gerou vem do Espírito Santo. Ela dará à luz um filho, e tu Lhe darás o nome de Jesus, O qual salvará o seu povo, livrando-o dos seus pecados”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 88:25"},{"k":"text","t":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus."}],"pt":[{"k":"ref","t":"Sl 88:25"},{"k":"text","t":"A minha verdade e a minha misericórdia estarão com ele; e o seu poder será exaltado em meu nome."}]},"Secreta":{"la":[{"k":"text","t":"Débitum tibi, Dómine, nostræ réddimus servitútis, supplíciter exorántes: ut, suffrágiis beáti Joseph, Sponsi Genetrícis Fílii tui Jesu Christi, Dómini nostri, in nobis tua múnera tueáris, ob cujus venerándam festivitátem laudis tibi hóstias immolámus."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eundem"}],"pt":[{"k":"text","t":"Vos oferecemos, Senhor, o justo tributo da nossa servidão, e instantemente Vos suplicamos queirais conservar em nós os vossos dons pela intercessão do B. José, Esposo da Mãe de Jesus Cristo, vosso Filho e Nosso Senhor, em cuja festa, que celebramos, imolamos nossas hóstias em vossa honra."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eundem"}]},"Communio":{"la":[{"k":"ref","t":"Matt 1:20"},{"k":"text","t":"Joseph, fili David, noli timére accípere Maríam cónjugem tuam: quod enim in ea natum est, de Spíritu Sancto est."}],"pt":[{"k":"ref","t":"Mt 1:20"},{"k":"text","t":"José, filho de David, não temas receber Maria como tua esposa, porque Aquele que ela gerou vem do Espírito Santo. (T. P. Aleluia.)"}]},"Postcommunio":{"la":[{"k":"text","t":"Adésto nobis, quǽsumus, miséricors Deus: et, intercedénte pro nobis beáto Joseph Confessóre, tua circa nos propitiátus dona custódi."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Assisti-nos, ó Deus de misericórdia, Vos suplicamos; e pela intercessão do B. José, Confessor, dignai-Vos propício conservar em nós os vossos dons."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"passio","la":"Dominica I Passionis","pt":"I Domingo da Paixão","color":"violaceus","classis":1,"tempus":"passionis","date":"quad5","gloria":false,"credo":true,"praef":"Quad5","ps42":false,"gloriaPatri":false,"notes":["No Tempo da Paixão omite-se o Salmo 42 (Judica me) ao pé do altar.","Omite-se o “Gloria Patri” no Intróito e no Lavabo.","Prefácio da Santa Cruz.","As cruzes e imagens estão veladas de roxo."],"source":"Tempora/Quad5-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 42:1-2."},{"k":"text","t":"Júdica me, Deus, et discérne causam meam de gente non sancta: ab hómine iníquo et dolóso éripe me: quia tu es Deus meus et fortitúdo mea."},{"k":"ref","t":"Ps 42:3"},{"k":"text","t":"Emítte lucem tuam et veritátem tuam: ipsa me de duxérunt et adduxérunt in montem sanctum tuum et in tabernácula tua."},{"k":"text","t":"Júdica me, Deus, et discérne causam meam de gente non sancta: ab hómine iníquo et dolóso éripe me: quia tu es Deus meus et fortitúdo mea."}],"pt":[{"k":"ref","t":"Sl 42:1 - 2."},{"k":"text","t":"Julgai-me, ó Deus, e defendei a minha causa da causa de um povo infiel; livrai-me do homem iníquo e ardiloso: pois sois, ó meu Deus, a minha fortaleza."},{"k":"ref","t":"Sl 42:3"},{"k":"text","t":"Enviai-me a vossa luz e a vossa verdade, para que me guiem até ao vosso monte sagrado, até aos vossos tabernáculos."},{"k":"text","t":"Julgai-me, ó Deus, e defendei a minha causa da causa de um povo infiel; livrai-me do homem iníquo e ardiloso: pois sois, ó meu Deus, a minha fortaleza."}]},"Oratio":{"la":[{"k":"text","t":"Quǽsumus, omnípotens Deus, famíliam tuam propítius réspice: ut, te largiénte, regátur in córpore; et, te servánte, custodiátur in mente."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus onipotente, olhai propício para a vossa família, Vos rogamos, a fim de que com vossa graça sejam dominados os nossos corpos e com vossa proteção sejam preservadas as nossas almas."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos."},{"k":"ref","t":"Hebr 9:11-15"},{"k":"text","t":"Fratres: Christus assístens Póntifex futurórum bonórum, per ámplius et perféctius tabernáculum non manufáctum, id est, non hujus creatiónis: neque per sánguinem hircórum aut vitulórum, sed per próprium sánguinem introívit semel in Sancta, ætérna redemptióne invénta. Si enim sanguis hircórum et taurórum, et cinis vítulæ aspérsus, inquinátos sanctíficat ad emundatiónem carnis: quanto magis sanguis Christi, qui per Spíritum Sanctum semetípsum óbtulit immaculátum Deo, emundábit consciéntiam nostram ab opéribus mórtuis, ad serviéndum Deo vivénti? Et ídeo novi Testaménti mediátor est: ut, morte intercedénte, in redemptiónem eárum prævaricatiónum, quæ erant sub prióri Testaménto, repromissiónem accípiant, qui vocáti sunt ætérnæ hereditátis, in Christo Jesu, Dómino nostro."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Hebreus."},{"k":"ref","t":"Heb 9:11-15."},{"k":"text","t":"Meus irmãos: Jesus Cristo, vindo como Pontífice dos bens futuros, penetrou em um tabernáculo maior e mais que não foi fabricado por mão humana, isto é, que não teve criação terrena; e, sem recorrer ao sangue dos carneiros ou dos bois, mas pelo seu próprio sangue, entrou uma vez no santuário, tendo alcançado a salvação eterna. Com efeito, se o sangue dos carneiros e dos bois e a aspersão da cinza de vitela santificam aqueles que estão manchados, dando-lhes a pureza legal e exterior, quanto mais o sangue de Cristo (que pelo Espírito Santo se ofereceu a si mesmo a Deus como vítima imaculada) purificará a nossa consciência das obras mortas, para nos tornar capazes de servir Deus vivo! Por isso Ele é o mediador do Novo Testamento, a fim de que sua morte, servindo de resgate das prevaricações cometidas no Antigo Testamento, transmita a eterna aliança prometida àqueles que foram chamados em Nosso Senhor Jesus Cristo."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 142:9, 10"},{"k":"text","t":"Eripe me, Dómine, de inimícis meis: doce me fácere voluntátem tuam"},{"k":"ref","t":"Ps 17:48-49"},{"k":"text","t":"Liberátor meus, Dómine, de géntibus iracúndis: ab insurgéntibus in me exaltábis me: a viro iníquo erípies me."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Ps 128:1-4"},{"k":"text","t":"Sæpe expugnavérunt me a juventúte mea."},{"k":"V","t":"Dicat nunc Israël: sæpe expugnavérunt me a juventúte mea."},{"k":"V","t":"Etenim non potuérunt mihi: supra dorsum meum fabricavérunt peccatóres."},{"k":"V","t":"Prolongavérunt iniquitátes suas: Dóminus justus concídit cervíces peccatórum."}],"pt":[{"k":"ref","t":"Sl 142:9-10."},{"k":"text","t":"Livrai-me dos meus inimigos, Senhor: ensinai-me a cumprir a vossa vontade."},{"k":"ref","t":"Sl 17:48-49"},{"k":"text","t":"Livrai-me, ó Senhor, das iras dos meus inimigos: elevai-me sobre aqueles que se insurgem contra mim e defendei-me do homem iníquo."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Sl 128:1-4"},{"k":"text","t":"Combateram-me desde a minha juventude."},{"k":"V","t":"Diga agora Israel: combateram-me desde a minha juventude."},{"k":"V","t":"Mas nada puderam contra mim. Nas minhas costas ficaram sinais das pancadas dos pecadores."},{"k":"V","t":"Durante bastante tempo continuaram as suas iniquidades; mas o Senhor, que é justo, cortará a cabeça dos pecadores."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem."},{"k":"ref","t":"Joann 8:46-59"},{"k":"text","t":"In illo témpore: Dicébat Jesus turbis Judæórum: Quis ex vobis árguet me de peccáto? Si veritátem dico vobis, quare non créditis mihi? Qui ex Deo est, verba Dei audit. Proptérea vos non audítis, quia ex Deo non estis. Respondérunt ergo Judǽi et dixérunt ei: Nonne bene dícimus nos, quia Samaritánus es tu, et dæmónium habes? Respóndit Jesus: Ego dæmónium non hábeo, sed honorífico Patrem meum, et vos inhonorástis me. Ego autem non quæro glóriam meam: est, qui quærat et júdicet. Amen, amen, dico vobis: si quis sermónem meum serváverit, mortem non vidébit in ætérnum. Dixérunt ergo Judǽi: Nunc cognóvimus, quia dæmónium habes. Abraham mórtuus est et Prophétæ; et tu dicis: Si quis sermónem meum serváverit, non gustábit mortem in ætérnum. Numquid tu major es patre nostro Abraham, qui mórtuus est? et Prophétæ mórtui sunt. Quem teípsum facis? Respóndit Jesus: Si ego glorífico meípsum, glória mea nihil est: est Pater meus, qui gloríficat me, quem vos dícitis, quia Deus vester est, et non cognovístis eum: ego autem novi eum: et si díxero, quia non scio eum, ero símilis vobis, mendax. Sed scio eum et sermónem ejus servo. Abraham pater vester exsultávit, ut vidéret diem meum: vidit, et gavísus est. Dixérunt ergo Judǽi ad eum: Quinquagínta annos nondum habes, et Abraham vidísti? Dixit eis Jesus: Amen, amen, dico vobis, ántequam Abraham fíeret, ego sum. Tulérunt ergo lápides, ut jácerent in eum: Jesus autem abscóndit se, et exívit de templo."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 8:46-59."},{"k":"text","t":"Naquele tempo, dizia Jesus à multidão dos judeus: “Qual de vós me acusará de pecado? Se vos digo a verdade, porque não me acreditais? Aquele que é de Deus, ouve a palavra de Deus. Vós não atendeis à palavra de Deus, porque não sois de Deus”. Os judeus responderam-Lhe: “Não temos nós razão para dizer que sois samaritano e que estais possesso do demônio?”. Jesus retorquiu: “Eu não estou possesso do demônio, mas honro a meu Pai; enquanto que vós desonrais-me. Eu não procuro a minha própria glória. Há alguém que tem esse cuidado e me fará justiça. Em verdade, em verdade vos digo: se alguém obedecer às minhas palavras, não terá a morte para sempre”. Os judeus disseram-Lhe: “Agora conhecemos que possuís o demônio. Abraão morreu, assim como os Profetas, e ainda dizeis: se alguém obedecer às minhas palavras, não morrerá para sempre? Sois, porventura, maior do que nosso pai Abraão, que morreu, assim como os Profetas? Quem pretendeis ser?”. Jesus respondeu: “Se me glorificasse a mim mesmo, a minha glória não era nada! Porém é meu Pai (a quem chamais vosso Deus) quem me glorifica. Contudo, vós O não conheceis; mas Eu conheço-O. Se dissesse que O não conhecia, seria mentiroso, semelhante a vós; mas Eu conheço-O e obedeço às suas palavras. Abraão, vosso pai, exultou de alegria, porque desejou ver o meu dia. Viu-o e rejubilou”. Os judeus disseram-Lhe, então: “Ainda não tendes cinquenta anos e vistes Abraão? Jesus respondeu-lhes: “Em verdade, em verdade vos digo: Antes que Abraão viesse a ser feito (isto é, nascesse) já Eu existo!”. Então, eles tomaram pedras, para Lhas atirarem; mas Jesus ocultou-se e saiu do templo."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 9:1, 118:17, 107"},{"k":"text","t":"Confitébor tibi, Dómine, in toto corde meo: retríbue servo tuo: vivam, et custódiam sermónes tuos: vivífica me secúndum verbum tuum, Dómine."}],"pt":[{"k":"ref","t":"Sl 9:1, 118:17, 107"},{"k":"text","t":"Senhor, louvar-Vos-ei de todo meu coração. Recompensai o vosso servo: Então viverei e observarei os vossos preceitos. Vivificai-me, segundo a vossa palavra, Senhor!"}]},"Secreta":{"la":[{"k":"text","t":"Hæc múnera, quǽsumus Dómine, et víncula nostræ pravitátis absólvant, et tuæ nobis misericórdiæ dona concílient."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Que estas ofertas, Senhor, Vos suplicamos, esmaguem os laços da nossa malícia e nos alcancem os dons da vossa misericórdia."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"1 Cor 11:24, 25"},{"k":"text","t":"Hoc corpus, quod pro vobis tradétur: hic calix novi Testaménti est in meo sánguine, dicit Dóminus: hoc fácite, quotiescúmque súmitis, in meam commemoratiónem."}],"pt":[{"k":"ref","t":"1 Cor. 11:24 - 25."},{"k":"text","t":"Este é o meu corpo, que será entregue por vós. Este é o cálice da nova aliança no meu sangue: diz o Senhor. Fazei isto em memória de mim todas as vezes que os receberdes."}]},"Postcommunio":{"la":[{"k":"text","t":"Adésto nobis, Dómine, Deus noster: et, quos tuis mystériis recreásti, perpétuis defénde subsídiis."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Assisti-nos, ó Senhor, nosso Deus; e concedei o vosso perpétuo auxílio aqueles a quem restaurastes com vossos mistérios."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"hebd2","la":"Feria II Hebdomadæ Sanctæ","pt":"Segunda-feira Santa","color":"violaceus","classis":1,"tempus":"passionis","date":"hebd2","gloria":false,"credo":false,"praef":"Quad5","ps42":false,"gloriaPatri":false,"superPopulum":true,"notes":["Féria de I classe da Semana Santa.","Após a Postcomunhão diz-se a “Oração sobre o povo”, precedida de “Humiliáte cápita vestra Deo”.","Sem Credo; omite-se o Salmo 42 e o “Gloria Patri”."],"source":"Tempora/Quad6-1","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 34:1-2."},{"k":"text","t":"Júdica, Dómine, nocéntes me, expúgna impugnántes me: apprehénde arma et scutum, et exsúrge in adjutórium meum, Dómine, virtus salútis meæ."},{"k":"ref","t":"Ps 34:3"},{"k":"text","t":"Effúnde frámeam, et conclúde advérsus eos, qui persequúntur me: dic ánimæ meæ: Salus tua ego sum."},{"k":"text","t":"Júdica, Dómine, nocéntes me, expúgna impugnántes me: apprehénde arma et scutum, et exsúrge in adjutórium meum, Dómine, virtus salútis meæ."}],"pt":[{"k":"ref","t":"Sl 34:1-2"},{"k":"text","t":"Julgai, Senhor, aqueles que me perseguem; exterminai aqueles que me combatem! Empunhai as armas e o escudo e erguei-Vos em meu auxílio, ó Senhor, que sois o meu sustentáculo e a minha salvação."},{"k":"ref","t":"Sl 34:3"},{"k":"text","t":"Desembainhai a vossa espada e enfrentai aqueles que me perseguem. Direi à minha alma: “Eu sou a tua salvação”."},{"k":"text","t":"Julgai, Senhor, aqueles que me perseguem; exterminai aqueles que me combatem! Empunhai as armas e o escudo e erguei-Vos em meu auxílio, ó Senhor, que sois o meu sustentáculo e a minha salvação."}]},"Oratio":{"la":[{"k":"text","t":"Da, quǽsumus, omnípotens Deus: ut, qui in tot advérsis ex nostra infirmitáte defícimus; intercedénte unigéniti Fílii tui passióne respirémus:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Ó Deus onipotente, que bem sabeis não poder a nossa fraqueza subsistir no meio de tantos perigos que a cercam, concedei-nos, Vos suplicamos, a graça de conseguirmos algum alívio pelos méritos da Paixão de vosso Filho Unigênito:"},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Isaíæ Prophétæ"},{"k":"ref","t":"Isa 50:5-10"},{"k":"text","t":"In diébus illis: Dixit Isaías: Dóminus Deus apéruit mihi aurem, ego autem non contradíco: retrórsum non ábii. Corpus meum dedi percutiéntibus et genas meas velléntibus: fáciem meam non avérti ab increpántibus et conspuéntibus in me. Dóminus Deus auxiliátor meus, ídeo non sum confúsus: ídeo posui fáciem meam ut petram duríssimam, et scio, quóniam non confúndar. Juxta est, qui justíficat me, quis contradícet mihi? Stemus simul, quis est adversárius meus? Accédat ad me. Ecce, Dóminus Deus auxiliátor meus: quis est, qui condémnet me? Ecce, omnes quasi vestiméntum conteréntur, tinea cómedet eos. Quis ex vobis timens Dóminum, áudiens vocem servi sui? Qui ambulávit in ténebris, et non est lumen ei, speret in nómine Dómini, et innitátur super Deum suum."}],"pt":[{"k":"text","t":"Lição do Profeta Isaías."},{"k":"ref","t":"Is 50:5-10"},{"k":"text","t":"Naqueles dias, disse Isaías: “O Senhor e Deus abriu-me os ouvidos, e lhe não resisti, nem voltei para trás. Entreguei o meu corpo aos que me maltratavam e as minhas faces aos que me arrancavam as barbas. Não voltei o rosto àqueles que me ultrajavam e cuspiam sobre mim. O Senhor e Deus é o meu protetor; assim, pois, não serei confundido! Meu rosto ficou impassível, como pedra duríssima; sei que não ficarei envergonhado. Aquele que me julgará está comigo; quem ousará, pois, contradizer-me? Compareceremos ambos. Quem será, pois, contra mim?! Aproxime-se de mim quem o ousar. O Senhor e Deus é o meu protetor; quem se atreverá a condenar-me? Meus inimigos serão destruídos, como vestidos velhos, devorados pela traça. Qual de vós teme o Senhor e escuta a voz do seu servo? Aquele que andou em trevas, privado da luz, confie no nome do Senhor, pois Deus será o seu sustentáculo”."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 34:23 et 3"},{"k":"text","t":"Exsúrge, Dómine, et inténde judício meo, Deus meus et Dóminus meus, in causam meam."},{"k":"V","t":"Effúnde frámeam, et conclúde advérsus eos, qui me persequúntur."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Ps 102:10"},{"k":"text","t":"Dómine, non secúndum peccáta nostra, quæ fécimus nos: neque secúndum iniquitátes nostras retríbuas nobis"},{"k":"ref","t":"Ps 78:8-9"},{"k":"text","t":"Dómine, ne memíneris iniquitátum nostrárum antiquárum: cito antícipent nos misericórdiæ tuæ, quia páuperes facti sumus nimis. (Hic genuflectitur)"},{"k":"V","t":"Adjuva nos, Deus, salutáris noster: et propter glóriam nóminis tui, Dómine, líbera nos: et propítius esto peccátis nostris, propter nomen tuum."}],"pt":[{"k":"ref","t":"Sl 34:23; 34:3"},{"k":"text","t":"Erguei-Vos, Senhor, e procedei ao meu julgamento. Ó meu Deus e meu Senhor, tomai a minha causa nas vossas mãos."},{"k":"V","t":"Desembainhai a vossa espada e enfrentai aqueles que me perseguem."},{"k":"rubric","t":"Tractus"},{"k":"ref","t":"Sl 102:10"},{"k":"text","t":"Senhor, nos não castigueis, consoante merecemos, pelos pecados que praticámos: nem nos julgueis, segundo as nossas iniquidades."},{"k":"ref","t":"Ps 78:8-9"},{"k":"text","t":"Esquecei-Vos, Senhor, das nossas iniquidades passadas, apressai-Vos em revestir-nos com vossas misericórdias, pois grande é a nossa miséria. (genufletir)"},{"k":"V","t":"Auxiliai-nos, ó Deus, nosso Salvador, e, pela glória do vosso nome, livrai-nos, Senhor, e perdoai os nossos pecados por causa do vosso nome."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem."},{"k":"ref","t":"Joann 12:1-9"},{"k":"text","t":"Ante sex dies Paschæ venit Jesus Bethániam, ubi Lázarus fúerat mórtuus, quem suscitávit Jesus. Fecérunt autem ei cenam ibi: et Martha ministrábat, Lázarus vero unus erat ex discumbéntibus cum eo. María ergo accépit libram unguénti nardi pístici pretiósi, et unxit pedes Jesu, et extérsit pedes ejus capíllis suis: et domus impléta est ex odóre unguénti. Dixit ergo unus ex discípulis ejus, Judas Iscariótes, qui erat eum traditúrus: Quare hoc unguéntum non véniit trecéntis denáriis, et datum est egénis? Dixit autem hoc, non quia de egénis pertinébat ad eum, sed quia fur erat, et lóculos habens, ea, quæ mittebántur, portábat. Dixit ergo Jesus: Sínite illam, ut in diem sepultúræ meæ servet illud. Páuperes enim semper habétis vobíscum: me autem non semper habétis. Cognóvit ergo turba multa ex Judǽis, quia illic est: et venérunt, non propter Jesum tantum, sed ut Lázarum vidérent, quem suscitávit a mórtuis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 12:1-9"},{"k":"text","t":"Seis dias antes da Páscoa, voltou Jesus a Betânia, onde morrera Lázaro, que Ele ressuscitara, Prepararam-Lhe a ceia, que Marta servia, sendo Lázaro um dos convivas. Então Maria pegou em uma libra de nardo puro e precioso, perfumando com ele os pés de Jesus e enxugando-lhos, depois, com seus cabelos. A casa estava cheia do odor daquele perfume. Vendo isto, disse um dos discípulos, Judas Iscariotes, que havia de traí-l’O: “Porque se não venderia, antes, este perfume por trezentos dinheiros, para se darem de esmola aos pobres?”. Ele disse isto, não porque tivesse compaixão dos pobres, mas porque era ladrão; e, como guardava a bolsa, tirava o que lhe entregavam. Jesus disse: “Deixai-a; ela guardou este perfume para o dia da minha sepultura. Vós tereis sempre pobres convosco, mas a mim nem sempre me tereis”. Então os judeus em grande multidão, sabendo que Jesus estava ali, acorreram lá, não tanto por causa d’Ele, como para verem Lázaro, que Jesus havia ressuscitado dos mortos."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 142:9-10"},{"k":"text","t":"Eripe me de inimícis meis, Dómine: ad te confúgi, doce me fácere voluntátem tuam: quia Deus meus es tu."}],"pt":[{"k":"ref","t":"Sl 142:9-10"},{"k":"text","t":"Salvai-me dos meus inimigos, Senhor. Em Vós procurei refúgio; ensinai-me a obedecer à vossa vontade, porquanto sois o meu Deus."}]},"Secreta":{"la":[{"k":"text","t":"Hæc sacrifícia nos, omnípotens Deus, poténti virtúte mundátos, ad suum fáciant purióres veníre princípium."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus onipotente, havendo sido purificados com a eficaz virtude destes sacrifícios, fazei que nos aproximemos cada vez mais puros d’Aquele que é o seu princípio."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 34:26"},{"k":"text","t":"Erubéscant et revereántur simul, qui gratulántur malis meis: induántur pudóre et reveréntia, qui malígna loquúntur advérsus me."}],"pt":[{"k":"ref","t":"Sl 34:26"},{"k":"text","t":"Sejam envergonhados e confundidos aqueles que se alegram com a minha desgraça; que a infâmia e o temor revistam aqueles que falam mal de mim."}]},"Postcommunio":{"la":[{"k":"text","t":"Prǽbeant nobis, Dómine, divínum tua sancta fervórem: quo eórum páriter et actu delectémur et fructu."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Que os vossos mistérios, Senhor, inspirem às nossas almas um fervor divino, a fim de que encontremos as nossas delícias tanto durante a sua celebração, como nos seus frutos."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Super populum":{"la":[{"k":"rubric","t":"Oratio super populum"},{"k":"text","t":"Orémus."},{"k":"text","t":"Humiliáte cápita vestra Deo."},{"k":"text","t":"Adjuva nos, Deus, salutáris noster: et ad benefícia recolénda, quibus nos instauráre dignátus es, tríbue veníre gaudéntes."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"rubric","t":"Oração sobre o povo"},{"k":"text","t":"Oremos."},{"k":"text","t":"Inclinai as vossas cabeças diante de Deus."},{"k":"text","t":"Ó Deus, nosso Salvador, vinde em nosso auxílio e concedei-nos a graça de celebrarmos com alegria o aniversário dos benefícios com que Vos dignastes regenerar-nos."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"pascha","la":"Dominica Resurrectionis","pt":"Domingo da Ressurreição — Páscoa","color":"albus","classis":1,"tempus":"paschale","date":"pascha","gloria":true,"credo":true,"praef":"Pasch","praefDie":true,"comm":"Pasc","hanc":"Pasc","ite":"iteAlleluia","sequentia":true,"notes":["Sequência “Victimæ paschali laudes”.","Communicantes e Hanc igitur próprios da Páscoa.","Na oitava da Páscoa acrescenta-se “allelúja, allelúja” ao “Ite, missa est” e ao “Deo grátias”."],"source":"Tempora/Pasc0-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 138:18; 138:5-6."},{"k":"text","t":"Resurréxi, et adhuc tecum sum, allelúja: posuísti super me manum tuam, allelúja: mirábilis facta est sciéntia tua, allelúja, allelúja."},{"k":"ref","t":"Ps 138:1-2."},{"k":"text","t":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"gloriapatri"},{"k":"text","t":"Resurréxi, et adhuc tecum sum, allelúja: posuísti super me manum tuam, allelúja: mirábilis facta est sciéntia tua, allelúja, allelúja."}],"pt":[{"k":"ref","t":"Sl. 1:38; 1:18; 1:5-6"},{"k":"text","t":"Ressuscitei e ainda estou convosco, aleluia. Pusestes sobre mim a vossa mão, aleluia. Vossa sabedoria mostrou-se admirável, aleluia, aleluia."},{"k":"ref","t":"Sl. 138. 1, 2"},{"k":"text","t":"Experimentastes-me, Senhor, e ficastes-me conhecendo: Ficastes conhecendo quando me deito e quando me levanto."},{"k":"gloriapatri"},{"k":"text","t":"Ressuscitei e ainda estou convosco, aleluia. Pusestes sobre mim a vossa mão, aleluia. Vossa sabedoria mostrou-se admirável, aleluia, aleluia."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui hodiérna die per Unigénitum tuum æternitátis nobis áditum, devícta morte, reserásti: vota nostra, quæ præveniéndo aspíras, étiam adjuvándo proséquere."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eumdem"}],"pt":[{"k":"text","t":"Ó Deus, que neste dia pelo triunfo do vosso Filho Unigênito, vencedor da morte, nos abristes o caminho da eternidade, auxiliai-nos com vosso socorro a realizar os votos que nos inspirais com vossa graça."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eumdem"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios."},{"k":"ref","t":"1 Cor 5:7-8"},{"k":"text","t":"Fratres: Expurgáte vetus ferméntum, ut sitis nova conspérsio, sicut estis ázymi. Etenim Pascha nostrum immolátus est Christus. Itaque epulémur: non in ferménto véteri, neque in ferménto malítiæ et nequítiæ: sed in ázymis sinceritátis et veritátis."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Coríntios."},{"k":"ref","t":"1 Cor 5:7-8"},{"k":"text","t":"Meus irmãos: Agora, que já sois ázimos, limpai-vos do fermento velho, para que vos torneis massa nova; pois Cristo, nossa Páscoa, foi imolado. Celebremos, então, a festa, não com o fermento da malícia e perversidade, mas com os ázimos da sinceridade e verdade."}]},"Graduale":{"la":[{"k":"ref","t":"Ps. 117:24; 117:1"},{"k":"text","t":"Hæc dies, quam fecit Dóminus: exsultémus et lætémur in ea."},{"k":"V","t":"Confitémini Dómino, quóniam bonus: quóniam in sǽculum misericórdia ejus. Allelúja, allelúja."},{"k":"ref","t":"1 Cor 5:7"},{"k":"V","t":"Pascha nostrum immolátus est Christus."}],"pt":[{"k":"text","t":"Aleluia, aleluia."},{"k":"ref","t":"Sl. 117:24; 117:1"},{"k":"text","t":"Eis o dia que o Senhor fez: exultemos e alegremo-nos n’Ele."},{"k":"V","t":"Louvai o Senhor, porque Ele é bom: e porque a sua misericórdia é eterna."},{"k":"ref","t":"1 Cor. 5. 7"},{"k":"text","t":"Cristo nossa Páscoa, foi imolado."}]},"Sequentia":{"la":[{"k":"text","t":"Víctimæ pascháli laudes ímmolent Christiáni."},{"k":"text","t":"Agnus rédemit oves: Christus ínnocens Patri reconciliávit peccatóres."},{"k":"text","t":"Mors et vita duéllo conflixére mirándo: dux vitæ mórtuus regnat vivus."},{"k":"text","t":"Dic nobis, María, quid vidísti in via?"},{"k":"text","t":"Sepúlcrum Christi vivéntis et glóriam vidi resurgéntis."},{"k":"text","t":"Angélicos testes, sudárium et vestes."},{"k":"text","t":"Surréxit Christus, spes mea: præcédet vos in Galilǽam."},{"k":"text","t":"Scimus Christum surrexísse a mórtuis vere: tu nobis, victor Rex, miserére. Amen. Allelúja."},{"k":"rubric","t":"Sequentia dicitur usque ad Sabbatum in Albis inclusive."}],"pt":[{"k":"text","t":"Venham os cristãos oferecer louvores à Vítima Pascal!"},{"k":"text","t":"O Cordeiro remiu as ovelhas; Cristo inocente reconciliou os pecadores com o Pai."},{"k":"text","t":"A morte e a vida travaram combate estupendo: o autor da vida morreu, mas Ele vive e reina."},{"k":"text","t":"Diz-nos, ó Maria, o que viste no caminho?"},{"k":"text","t":"Vi o sepulcro de Cristo, que está vivo; vi a glória de Cristo ressuscitado."},{"k":"text","t":"Vi presentes os Anjos, o sudário e as vestes."},{"k":"text","t":"Ressuscitou Cristo, minha esperança, que precederá na Galileia os discípulos."},{"k":"text","t":"Sabemos que Cristo ressuscitou dos mortos, verdadeiramente. Ó Rei vencedor, tende piedade de nós. Amen. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Marcum."},{"k":"ref","t":"Marc 16:1-7."},{"k":"text","t":"In illo témpore: María Magdaléne et María Jacóbi et Salóme emérunt arómata, ut veniéntes úngerent Jesum. Et valde mane una sabbatórum, véniunt ad monuméntum, orto jam sole. Et dicébant ad ínvicem: Quis revólvet nobis lápidem ab óstio monuménti? Et respiciéntes vidérunt revolútum lápidem. Erat quippe magnus valde. Et introëúntes in monuméntum vidérunt júvenem sedéntem in dextris, coopértum stola cándida, et obstupuérunt. Qui dicit illis: Nolíte expavéscere: Jesum quǽritis Nazarénum, crucifíxum: surréxit, non est hic, ecce locus, ubi posuérunt eum. Sed ite, dícite discípulis ejus et Petro, quia præcédit vos in Galilǽam: ibi eum vidébitis, sicut dixit vobis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Marcos."},{"k":"ref","t":"Mc 16:1-7"},{"k":"text","t":"Naquele tempo, Maria Madalena, Maria, mãe de Tiago, e Salomé compraram perfumes para ungir Jesus. Partindo, pois, de manhã cedo, no primeiro dia depois do sábado, chegaram ao sepulcro, tendo já nascido o sol. E diziam umas às outras: “Quem nos tirará a pedra da entrada do sepulcro?”. Olhando, então, viram que a pedra estava desviada para o lado: a qual, com efeito, era muito grande. Entrando no sepulcro, viram um jovem, sentado ao lado direito, vestido com uma túnica branca. Ficaram atônitas! Mas o jovem disse-lhes: “Não tenhais medo! Procurais a Jesus Nazareno, que foi crucificado? Ressuscitou, não está aqui: eis o lugar onde fora colocado! Ide, pois, dizer a seus discípulos e a Pedro, que Ele vos precede na Galileia e lá O vereis, como vos disse”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps. 75:9-10."},{"k":"text","t":"Terra trémuit, et quiévit, dum resúrgeret in judício Deus, allelúja."}],"pt":[{"k":"ref","t":"Sl. 75:9-10."},{"k":"text","t":"A terra tremeu e aquietou-se, logo que Deus se ergueu para a julgar, aleluia."}]},"Secreta":{"la":[{"k":"text","t":"Súscipe, quǽsumus, Dómine, preces pópuli tui cum oblatiónibus hostiárum: ut, Paschálibus initiáta mystériis, ad æternitátis nobis medélam, te operánte, profíciant."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, dignai-Vos aceitar com a oferta destas hóstias as preces do vosso povo, para que os mistérios da Páscoa, agora iniciados, nos sirvam, com vosso auxílio, de remédio para a eternidade."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"1 Cor 5:7-8"},{"k":"text","t":"Pascha nostrum immolátus est Christus, allelúja: itaque epulémur in ázymis sinceritátis et veritátis, allelúja, allelúja, allelúja."}],"pt":[{"k":"ref","t":"1 Cor 5:7-8"},{"k":"text","t":"Cristo, nossa Páscoa, foi imolado, aleluia. Celebremos, pois, a Páscoa com os ázimos da sinceridade e verdade, aleluia, aleluia, aleluia."}]},"Postcommunio":{"la":[{"k":"text","t":"Spíritum nobis, Dómine, tuæ caritátis infúnde: ut, quos sacraméntis paschálibus satiásti, tua fácias pietáte concordes."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte ejúsdem Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum eiusdem"}],"pt":[{"k":"text","t":"Infundi em nós, Senhor, o espírito da vossa caridade, para que todos aqueles que foram alimentados com vossos sacramentos nesta festa pascal vivam unidos em perfeita concórdia, pela vossa bondade."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do mesmo Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum eiusdem"}]}}},{"id":"asc","la":"In Ascensione Domini","pt":"Ascensão do Senhor","color":"albus","classis":1,"tempus":"paschale","date":"asc","gloria":true,"credo":true,"praef":"Asc","comm":"Asc","notes":["Após o Evangelho apaga-se o círio pascal.","Communicantes próprio da Ascensão."],"source":"Tempora/Pasc5-4","parts":{"Introitus":{"la":[{"k":"ref","t":"Acta 1:11"},{"k":"text","t":"Viri Galilǽi, quid admirámini aspiciéntes in cœlum? allelúja: quemádmodum vidístis eum ascendéntem in cœlum, ita véniet, allelúja, allelúja, allelúja."},{"k":"ref","t":"Ps 46:2"},{"k":"text","t":"Omnes gentes, pláudite mánibus: jubiláte Deo in voce exsultatiónis."},{"k":"gloriapatri"},{"k":"text","t":"Viri Galilǽi, quid admirámini aspiciéntes in cœlum? allelúja: quemádmodum vidístis eum ascendéntem in cœlum, ita véniet, allelúja, allelúja, allelúja."}],"pt":[{"k":"ref","t":"Acts 1:11"},{"k":"text","t":"Varões galileus, porque estais a olhar, admirados, para o céu? Aleluia! Como O vistes subir para o céu, assim Ele virá: aleluia, aleluia, aleluia."},{"k":"ref","t":"Sl 46:2"},{"k":"text","t":"Todos os povos, batei palmas com júbilo: aclamai Deus com vossos hinos de alegria!"},{"k":"gloriapatri"},{"k":"text","t":"Varões galileus, porque estais a olhar, admirados, para o céu? Aleluia! Como O vistes subir para o céu, assim Ele virá: aleluia, aleluia, aleluia."}]},"Oratio":{"la":[{"k":"text","t":"Concéde, quǽsumus, omnípotens Deus: ut, qui hodiérna die Unigénitum tuum, Redemptórem nostrum, ad cœlos ascendísse crédimus; ipsi quoque mente in cœléstibus habitémus."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eundem"}],"pt":[{"k":"text","t":"Ó Deus onipotente, assim como acreditamos que o vosso Filho Unigênito, nosso Redentor, subiu aos céus neste dia, assim também, Vos suplicamos, tenhamos a nossa morada em espírito lá no céu."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eumdem"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Actuum Apostólorum"},{"k":"ref","t":"Act 1:1-11"},{"k":"text","t":"Primum quidem sermónem feci de ómnibus, o Theóphile, quæ cœpit Jesus facere et docére usque in diem, qua, præcípiens Apóstolis per Spíritum Sanctum, quos elégit, assúmptus est: quibus et prǽbuit seípsum vivum post passiónem suam in multas arguméntis, per dies quadragínta appárens eis et loquens de regno Dei. Et convéscens, præcépit eis, ab Jerosólymis ne discéderent, sed exspectárent promissiónem Patris, quam audístis - inquit - per os meum: quia Joánnes quidem baptizávit aqua, vos autem baptizabímini Spíritu Sancto non post multos hos dies. Igitur qui convénerant, interrogábant eum, dicéntes: Dómine, si in témpore hoc restítues regnum Israël? Dixit autem eis: Non est vestrum nosse témpora vel moménta, quæ Pater pósuit in sua potestáte: sed accipiétis virtútem superveniéntis Spíritus Sancti in vos, et éritis mihi testes in Jerúsalem et in omni Judǽa et Samaría et usque ad últimum terræ. Et cum hæc dixísset, vidéntibus illis, elevátus est, et nubes suscépit eum ab óculis eórum. Cumque intueréntur in cœlum eúntem illum, ecce, duo viri astitérunt juxta illos in véstibus albis, qui et dixérunt: Viri Galilǽi, quid statis aspiciéntes in cœlum? Hic Jesus, qui assúmptus est a vobis in cœlum, sic véniet, quemádmodum vidístis eum eúntem in cœlum."}],"pt":[{"k":"text","t":"Lição dos Atos dos Apóstolos."},{"k":"ref","t":"Act 1:1-11"},{"k":"text","t":"Já vos narrei no meu primeiro livro, ó Teófilo, tudo quanto Jesus fez e ensinou, até ao dia em que, após ter dado as suas instruções pelo Espírito Santo aos Apóstolos, que Ele escolhera, subiu aos céus. A estes, também, depois da sua paixão, se apresentou vivo com muitas e infalíveis provas, aparecendo-lhes durante quarenta dias, e falando-lhes do reino de Deus. Em uma vez, comendo com eles à mesa, ordenou-lhes que se não afastassem de Jerusalém, mas que esperassem a realização da promessa do Pai, “que ouvistes (disse Ele) da minha boca; pois João batizou na água, mas vós sereis batizados com o Espírito Santo, pisados não muitos dias”. Então, aqueles que estavam reunidos perguntaram: “Senhor, será nessa ocasião que restaurareis o reino de Israel?”. Ele respondeu: “Não vos é dado conhecerdes nem os tempos, nem os momentos que o Pai fixou com sua autoridade; mas recebereis a virtude do Espírito Santo, que descerá sobre vós, e vos tornareis meus testemunhos em Jerusalém, na Judeia, na Samaria e até aos confins do mundo”. Havendo dito isto, elevou-se ao alto na sua presença, envolvendo-O uma nuvem, que O escondeu a seus olhos. E, como contemplassem atentamente o céu, para onde Jesus se elevara, apareceram ao pé deles dois homens, vestidos de branco, que lhes disseram: “Varões galileus, porque estais admirados a olhar para o céu? Este Jesus, que se elevou ao céu no meio de vós, de lá virá da mesma maneira que O vistes elevar-se”."}]},"Graduale":{"la":[{"k":"text","t":"Allelúja, allelúja."},{"k":"ref","t":"Ps 46:6"},{"k":"text","t":"Ascéndit Deus in jubilatióne, et Dóminus in voce tubæ. Allelúja."},{"k":"ref","t":"Ps 67:18-19"},{"k":"V","t":"Dóminus in Sina in sancto, ascéndens in altum, captívam duxit captivitátem. Allelúja."}],"pt":[{"k":"text","t":"Aleluia, aleluia."},{"k":"ref","t":"Sl 46:6"},{"k":"text","t":"Subiu Deus ao céu no meio de aclamações de júbilo: o Senhor subiu ao som da trombeta."},{"k":"text","t":"Aleluia."},{"k":"ref","t":"Sl 67:18-19"},{"k":"text","t":"O Senhor do Sinai entrou no seu santuário; e, subindo “ao alto”, levou consigo os cativos. Aleluia"}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Marcum."},{"k":"ref","t":"Marc 16:14-20"},{"k":"text","t":"In illo témpore: Recumbéntibus úndecim discípulis, appáruit illis Jesus: et exprobrávit incredulitátem eórum et durítiam cordis: quia iis, qui víderant eum resurrexísse, non credidérunt. Et dixit eis: Eúntes in mundum univérsum, prædicáte Evangélium omni creatúræ. Qui credíderit et baptizátus fúerit, salvus erit: qui vero non credíderit, condemnábitur. Signa autem eos, qui credíderint, hæc sequéntur: In nómine meo dæmónia ejícient: linguis loquentur novis: serpentes tollent: et si mortíferum quid bíberint, non eis nocébit: super ægros manus impónent, et bene habébunt. Et Dóminus quidem Jesus, postquam locútus est eis, assúmptus est in cœlum, et sedet a dextris Dei. Illi autem profécti, prædicavérunt ubíque, Dómino cooperánte et sermónem confirmánte, sequéntibus signis."},{"k":"rubric","t":"Dicto Evangelio exstinguitur Cereus paschalis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Marcos."},{"k":"ref","t":"Mc 16:14-20"},{"k":"text","t":"Naquele tempo, estando à mesa os Onze discípulos, apareceu-lhes Jesus e repreendeu-os por causa da sua incredulidade e dureza de coração; pois não tinham acreditado naqueles que já haviam visto Jesus depois da Ressurreição. E disse-lhes: “Ide por todo o mundo e pregai o Evangelho a todas as criaturas. Quem acreditar e for batizado será salvo; e quem não acreditar, será condenado. Eis os prodígios que operarão aqueles que tiverem acreditado: Em meu nome expulsarão os demônios; falarão novas línguas; dominarão as serpentes; se tomarem alguma bebida mortífera, nenhum mal lhes acontecerá; e imporão as mãos sobre os enfermos e curá-los-ão”. Então o Senhor Jesus, depois de haver assim falado, subiu ao céu, onde está sentado à direita de Deus. E eles partiram e pregaram em todos os lugares, cooperando o Senhor com eles e confirmando as suas palavras com milagres, que as acompanhavam."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 46:6"},{"k":"text","t":"Ascéndit Deus in jubilatióne, et Dóminus in voce tubæ, allelúja."}],"pt":[{"k":"ref","t":"Sl 46:6"},{"k":"text","t":"Subiu Deus no meio de aclamações jubilosas: o Senhor elevou-se ao som da trombeta, aleluia."}]},"Secreta":{"la":[{"k":"text","t":"Súscipe, Dómine, múnera, quæ pro Fílii tui gloriósa Ascensióne deférimus: et concéde propítius; ut a præséntibus perículis liberémur, et ad vitam perveniámus ætérnam."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eundem"}],"pt":[{"k":"text","t":"Aceitai, Senhor, os dons que Vos oferecemos em memória da gloriosa Ascensão de vosso Filho e concedei-nos benigno que sejamos livres dos perigos presentes e alcancemos a vida eterna."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eumdem"}]},"Communio":{"la":[{"k":"ref","t":"Ps 67:33-34"},{"k":"text","t":"Psállite Dómino, qui ascéndit super cœlos cœlórum ad Oriéntem, allelúja."}],"pt":[{"k":"ref","t":"Sl 67:33-34"},{"k":"text","t":"Cantai louvores ao Senhor, que sobe no Oriente ao mais alto dos céus, aleluia."}]},"Postcommunio":{"la":[{"k":"text","t":"Præsta nobis, quǽsumus, omnípotens et miséricors Deus: ut, quæ visibílibus mystériis suménda percépimus, invisíbili consequámur efféctu."},{"k":"concl","t":"Per Dominum.","key":"Per Dominum.","missing":true}],"pt":[{"k":"text","t":"Ó Deus onipotente e misericordioso, Vos suplicamos, permiti que sejamos participantes dos efeitos invisíveis dos mistérios em que visivelmente tomámos parte."},{"k":"concl","t":"Per Dominum.","key":"Per Dominum.","missing":true}]}}},{"id":"pent","la":"Dominica Pentecostes","pt":"Domingo de Pentecostes","color":"ruber","classis":1,"tempus":"paschale","date":"pent","gloria":true,"credo":true,"praef":"Spiritu","comm":"Pent","hanc":"Pasc","sequentia":true,"kneelAlleluia":"Veni, Sancte Spíritus","notes":["Ao versículo do Aleluia “Veni, Sancte Spiritus” o celebrante genuflecte.","Sequência “Veni, Sancte Spiritus”.","Communicantes e Hanc igitur próprios de Pentecostes."],"source":"Tempora/Pasc7-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Sap 1:7."},{"k":"text","t":"Spíritus Dómini replévit orbem terrárum, allelúja: et hoc quod cóntinet ómnia, sciéntiam habet vocis, allelúja, allelúja, allelúja."},{"k":"ref","t":"Ps 67:2"},{"k":"text","t":"Exsúrgat Deus, et dissipéntur inimíci ejus: et fúgiant, qui odérunt eum, a fácie ejus."},{"k":"gloriapatri"},{"k":"text","t":"Spíritus Dómini replévit orbem terrárum, allelúja: et hoc quod cóntinet ómnia, sciéntiam habet vocis, allelúja, allelúja, allelúja."}],"pt":[{"k":"ref","t":"Sb 1:7."},{"k":"text","t":"O Espírito do Senhor encheu todo o universo, aleluia. Ele, que abrange todas as coisas, sabe tudo quanto se diz: aleluia, aleluia."},{"k":"ref","t":"Sl. 67:2"},{"k":"text","t":"Erga-se Deus e sejam dispersos os seus inimigos: fujam da sua presença os seus inimigos!"},{"k":"gloriapatri"},{"k":"text","t":"O Espírito do Senhor encheu todo o universo, aleluia. Ele, que abrange todas as coisas, sabe tudo quanto se diz: aleluia, aleluia."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui hodiérna die corda fidélium Sancti Spíritus illustratióne docuísti: da nobis in eódem Spíritu recta sápere; et de ejus semper consolatióne gaudére."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte ejúsdem Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum eiusdem"}],"pt":[{"k":"text","t":"Ó Deus, que neste dia instruístes os corações dos fiéis, infundindo-lhes os dons do Espírito Santo, concedei-nos pelo mesmo Espírito a graça de amarmos o que é reto e de gozarmos incessantemente as suas consolações."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do mesmo Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum eiusdem"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Actuum Apostolórum"},{"k":"ref","t":"Acts 2:1-11"},{"k":"text","t":"Cum compleréntur dies Pentecóstes, erant omnes discípuli pariter in eódem loco: et factus est repénte de cœlo sonus, tamquam adveniéntis spíritus veheméntis: et replévit totam domum, ubi erant sedentes. Et apparuérunt illis dispertítæ linguæ tamquam ignis, sedítque supra síngulos eórum: et repléti sunt omnes Spíritu Sancto, et cœpérunt loqui váriis linguis, prout Spíritus Sanctus dabat éloqui illis. Erant autem in Jerúsalem habitántes Judǽi, viri religiósi ex omni natióne, quæ sub cœlo est. Facta autem hac voce, convénit multitúdo, et mente confúsa est, quóniam audiébat unusquísque lingua sua illos loquéntes. Stupébant autem omnes et mirabántur, dicéntes: Nonne ecce omnes isti, qui loquúntur, Galilǽi sunt? Et quómodo nos audívimus unusquísque linguam nostram, in qua nati sumus? Parthi et Medi et Ælamítæ et qui hábitant Mesopotámiam, Judǽam et Cappadóciam, Pontum et Asiam, Phrýgiam et Pamphýliam, Ægýptum et partes Líbyæ, quæ est circa Cyrénen, et ádvenæ Románi, Judǽi quoque et Prosélyti, Cretes et Arabes: audívimus eos loquéntes nostris linguis magnália Dei."}],"pt":[{"k":"text","t":"Lição dos Atos dos Apóstolos."},{"k":"ref","t":"Act 2:1-11."},{"k":"text","t":"Quando chegou o dia de Pentecostes, os discípulos estavam todos reunidos no mesmo lugar. De repente, ouviu-se um ruído, vindo do céu, semelhante a um vento impetuoso, que encheu toda a casa onde estavam reunidos. Então, apareceram-lhes línguas de fogo, que se dividiram umas das outras e pousaram sobre cada um deles, ficando ao mesmo tempo cheios de Espírito Santo e começando a falar várias línguas, corno o Espírito Santo lhes concedia que falassem. Estavam, então, em Jerusalém, judeus e homens religiosos de todas as nações, que existem na terra. Logo que este ruído foi ouvido correram muitas pessoas em multidão ao lugar e ficaram admiradas, porque cada uma ouvia os discípulos falar na sua própria língua. E as pessoas estavam de tal modo fora de si e maravilhadas que diziam: “Porventura estes, que nos falam, não são galileus? Como é, pois, que os ouvimos falar, a cada um de nós, na língua do nosso país natal? Partos, Medos, Elamitas, habitantes da Mesopotâmia, da Judeia, da Capadócia, do Ponto e da Ásia, da Frígia e da Panfília, do Egito, dos confins da Líbia, vizinha da Cirene, até os romanos de passagem e também os judeus e os prosélitos, os de Creta e da Arábia ouvimos os Apóstolos, nas nossas próprias línguas, encarecer as grandezas de Deus”."}]},"Graduale":{"la":[{"k":"text","t":"Allelúja, allelúja."},{"k":"ref","t":"Ps 103:30"},{"k":"text","t":"Emítte Spíritum tuum, et creabúntur, et renovábis fáciem terræ. Allelúja. (Hic genuflectitur)"},{"k":"V","t":"Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde."}],"pt":[{"k":"text","t":"Aleluia, aleluia."},{"k":"ref","t":"Sl. 103:30"},{"k":"V","t":"Enviai o vosso Espírito, e uma nova criação se operará: e renovareis a face da terra. Aleluia. (Genuflecte-se)"},{"k":"V","t":"Vinde, ó Espírito Santo; enchei os corações dos vossos fiéis e acendei neles o fogo do vosso amor."}]},"Sequentia":{"la":[{"k":"text","t":"Veni, Sancte Spíritus,"},{"k":"text","t":"et emítte cǽlitus"},{"k":"text","t":"lucis tuæ rádium."},{"k":"text","t":"Veni, pater páuperum;"},{"k":"text","t":"veni, dator múnerum;"},{"k":"text","t":"veni, lumen córdium."},{"k":"text","t":"Consolátor óptime,"},{"k":"text","t":"dulcis hospes ánimæ,"},{"k":"text","t":"dulce refrigérium."},{"k":"text","t":"In labóre réquies,"},{"k":"text","t":"in æstu tempéries,"},{"k":"text","t":"in fletu solácium."},{"k":"text","t":"O lux beatíssima,"},{"k":"text","t":"reple cordis íntima"},{"k":"text","t":"tuórum fidélium."},{"k":"text","t":"Sine tuo númine"},{"k":"text","t":"nihil est in hómine,"},{"k":"text","t":"nihil est innóxium."},{"k":"text","t":"Lava quod est sórdidum,"},{"k":"text","t":"riga quod est áridum,"},{"k":"text","t":"sana quod est sáucium."},{"k":"text","t":"Flecte quod est rígidum,"},{"k":"text","t":"fove quod est frígidum,"},{"k":"text","t":"rege quod est dévium."},{"k":"text","t":"Da tuis fidélibus,"},{"k":"text","t":"in te confidéntibus,"},{"k":"text","t":"sacrum septenárium."},{"k":"text","t":"Da virtútis méritum,"},{"k":"text","t":"da salútis éxitum,"},{"k":"text","t":"da perénne gáudium."},{"k":"text","t":"Amen. Allelúja."}],"pt":[{"k":"text","t":"Vinde, ó Espírito Santo,"},{"k":"text","t":"e enviai do céu um raio"},{"k":"text","t":"da vossa divina luz."},{"k":"text","t":"Vinde, ó pai dos pobres;"},{"k":"text","t":"vinde, distribuidor de todos os dons;"},{"k":"text","t":"vinde, luz dos corações."},{"k":"text","t":"Consolador supremo,"},{"k":"text","t":"doce hóspede da alma,"},{"k":"text","t":"suave refrigério!"},{"k":"text","t":"No trabalho sois repouso;"},{"k":"text","t":"sois calma no ardor;"},{"k":"text","t":"e consolação no pranto."},{"k":"text","t":"Ó luz felicíssima,"},{"k":"text","t":"enchei até ao íntimo os corações"},{"k":"text","t":"dos vossos fiéis."},{"k":"text","t":"Sem a vossa assistência"},{"k":"text","t":"nada há bom no homem,"},{"k":"text","t":"nada há que seja puro."},{"k":"text","t":"Lavai, pois, o que está manchado;"},{"k":"text","t":"regai o que está seco;"},{"k":"text","t":"curai o que está enfermo."},{"k":"text","t":"Abrandai o que é duro;"},{"k":"text","t":"aquecei o que está frio;"},{"k":"text","t":"guiai o que anda errado."},{"k":"text","t":"Concedei aos fiéis,"},{"k":"text","t":"que em Vós confiam,"},{"k":"text","t":"os sete dons sagrados."},{"k":"text","t":"Dai-lhes o mérito da virtude;"},{"k":"text","t":"dai-lhes um fim feliz;"},{"k":"text","t":"dai-lhes o gozo eterno."},{"k":"text","t":"Amen. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem"},{"k":"ref","t":"Joannes 14:23-31"},{"k":"text","t":"In illo témpore: Dixit Jesus discípulis suis: Si quis díligit me, sermónem meum servábit, et Pater meus díliget eum, et ad eum veniémus et mansiónem apud eum faciémus: qui non díligit me, sermónes meos non servat. Et sermónem quem audístis, non est meus: sed ejus, qui misit me, Patris. Hæc locútus sum vobis, apud vos manens. Paráclitus autem Spíritus Sanctus, quem mittet Pater in nómine meo, ille vos docébit ómnia et súggeret vobis ómnia, quæcúmque díxero vobis. Pacem relínquo vobis, pacem meam do vobis: non quómodo mundus dat, ego do vobis. Non turbétur cor vestrum neque formídet. Audístis, quia ego dixi vobis: Vado et vénio ad vos. Si diligerétis me, gauderétis útique, quia vado ad Patrem: quia Pater major me est. Et nunc dixi vobis, priúsquam fiat: ut, cum factum fúerit, credátis. Jam non multa loquar vobíscum. Venit enim princeps mundi hujus, et in me non habet quidquam. Sed ut cognóscat mundus, quia díligo Patrem, et sicut mandátum dedit mihi Pater, sic fácio."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 14:23-31."},{"k":"text","t":"Naquele tempo, disse Jesus aos discípulos: “Se alguém me ama, guardará a minha doutrina; e meu Pai o amará. E viremos a ele e nele faremos nossa morada. Quem me não ama, não guarda os meus ensinos”. A doutrina que ouvis não é minha, mas daquele que me enviou, isto é, do Pai. Disse-vos todas estas coisas, enquanto estive convosco. Porém o Paráclito o Espírito Santo que o Pai vos enviará em meu nome, ensinar-vos-á todas as coisas e vos inspirará tudo o que vos ensinei. Deixo-vos a paz; dou-vos a minha paz; mas a paz que vos dou não é como a que o mundo dá. Que o vosso coração não se perturbe, nem se intimide. Ouvistes o que disse: “Eu vou, mas depois volto”. Se me amais regozijar-vos-eis por Eu ir ao Pai, pois o Pai é maior do que Eu. Digo-vos estas coisas, antes de acontecerem, para que, quando acontecerem, acrediteis nelas. Já não falarei mais convosco, pois eis que vem o príncipe deste mundo. Ele não tem poder em mim, mas é para que o mundo conheça que amo o Pai e que procedo conforme o que o Pai me mandou."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 67:29-30"},{"k":"text","t":"Confírma hoc, Deus, quod operátus es in nobis: a templo tuo, quod est in Jerúsalem, tibi ófferent reges múnera, allelúja."}],"pt":[{"k":"ref","t":"Sl 67:2-3"},{"k":"text","t":"Confirmai, ó Deus, o que em nós começastes. Lá, no vosso templo, em Jerusalém, os reis oferecer-Vos-ão suas dádivas, aleluia."}]},"Secreta":{"la":[{"k":"text","t":"Múnera, quǽsumus, Dómine, obláta sanctífica: et corda nostra Sancti Spíritus illustratióne emúnda."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte ejúsdem Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum eiusdem"}],"pt":[{"k":"text","t":"Santificai, Senhor, Vos suplicamos, os dons que Vos oferecemos, e purificai os nossos corações com a luz do Espírito Santo."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do mesmo Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum eiusdem"}]},"Communio":{"la":[{"k":"ref","t":"Act 2:2; 2:4"},{"k":"text","t":"Factus est repénte de cœlo sonus, tamquam adveniéntis spíritus veheméntis, ubi erant sedéntes, allelúja: et repléti sunt omnes Spíritu Sancto, loquéntes magnália Dei, allelúja, allelúja."}],"pt":[{"k":"ref","t":"Act 2:2; 2:4"},{"k":"text","t":"De repente, ouviu-se, vindo do céu, um ruído, semelhante a um vento impetuoso, que encheu a casa onde estavam reunidos, aleluia: e ficaram cheios do Espírito Santo, anunciando as maravilhas de Deus, aleluia."}]},"Postcommunio":{"la":[{"k":"text","t":"Sancti Spíritus, Dómine, corda nostra mundet infúsio: et sui roris íntima aspersióne fecúndet."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte ejúsdem Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum eiusdem"}],"pt":[{"k":"text","t":"Senhor, que a efusão do Espírito Santo purifique os nossos corações e que, penetrando neles, a aspersão do seu orvalho fecunde o íntimo das nossas almas."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do mesmo Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum eiusdem"}]}}},{"id":"trin","la":"Dominica Sanctissimæ Trinitatis","pt":"Santíssima Trindade","color":"albus","classis":1,"tempus":"postpent","date":"trin","gloria":true,"credo":true,"praef":"Trinitate","notes":["Festa de I classe; Prefácio da Santíssima Trindade."],"source":"Tempora/Pent01-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Tob 12:6"},{"k":"text","t":"Benedícta sit sancta Trínitas atque indivísa Unitas: confitébimur ei, quia fecit nobíscum misericórdiam suam."},{"k":"ref","t":"Ps 8:2"},{"k":"text","t":"Dómine, Dóminus noster, quam admirábile est nomen tuum in univérsa terra!"},{"k":"gloriapatri"},{"k":"text","t":"Benedícta sit sancta Trínitas atque indivísa Unitas: confitébimur ei, quia fecit nobíscum misericórdiam suam."}],"pt":[{"k":"ref","t":"Tob 12:6"},{"k":"text","t":"Bendita seja a Santíssima Trindade e a indivisível Unidade! Nós A louvamos; pois foi misericordiosa para conosco."},{"k":"ref","t":"Sl 8:2"},{"k":"text","t":"Senhor, nosso Deus, como o vosso nome é admirável em todo o universo!"},{"k":"gloriapatri"},{"k":"text","t":"Bendita seja a Santíssima Trindade e a indivisível Unidade! Nós A louvamos; pois foi misericordiosa para conosco."}]},"Oratio":{"la":[{"k":"text","t":"Omnípotens sempitérne Deus, qui dedísti fámulis tuis in confessióne veræ fídei, ætérnæ Trinitátis glóriam agnóscere, et in poténtia majestátis adoráre Unitátem: quǽsumus; ut, ejúsdem fídei firmitáte, ab ómnibus semper muniámur advérsis."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó onipotente e eterno Deus, que quisestes que os vossos fiéis, acreditando e confessando a verdadeira fé, conhecessem a glória da sempiterna Trindade e adorassem a Unidade no poder da sua majestade, permiti, Vos imploramos, que, guardando nós firmemente a mesma fé, vençamos sempre todas as adversidades."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","t":"Rom 11:33-36."},{"k":"text","t":"O altitúdo divitiárum sapiéntiæ et sciéntiæ Dei: quam incomprehensibília sunt judícia ejus, et investigábiles viæ ejus! Quis enim cognovit sensum Dómini? Aut quis consiliárius ejus fuit? Aut quis prior dedit illi, et retribuétur ei? Quóniam ex ipso et per ipsum et in ipso sunt ómnia: ipsi glória in sǽcula. Amen."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Romanos."},{"k":"ref","t":"Rm. 11:33-36."},{"k":"text","t":"Ó abismo das riquezas, da sabedoria e da ciência de Deus! Como são incompreensíveis os seus juízos e impenetráveis os seus caminhos! Pois quem, porventura, conheceu já os desígnios do Senhor? Quem foi seu conselheiro? Quem foi o primeiro a dar-Lhe alguma coisa, para depois receber recompensa? Pois tudo quanto existe é d’Ele, para Ele e n’Ele. A Ele, pois, seja dada glória em todos os séculos. Amen."}]},"Graduale":{"la":[{"k":"ref","t":"Dan 3:55-56"},{"k":"text","t":"Benedíctus es, Dómine, qui intuéris abýssos, et sedes super Chérubim,"},{"k":"V","t":"Benedíctus es, Dómine, in firmaménto cæli, et laudábilis in sǽcula. Allelúja, allelúja."},{"k":"ref","t":"Dan 3:52"},{"k":"V","t":"Benedíctus es, Dómine, Deus patrum nostrórum, et laudábilis in sǽcula. Allelúja."}],"pt":[{"k":"ref","t":"Dn 3:55-56"},{"k":"text","t":"Bendito sois, Senhor, que sondais as profundezas dos abismos e estais sentado sobre os Querubins!"},{"k":"V","t":"Sim, Senhor, sois bendito no firmamento do céu; e digno de louvor em todos os séculos. Aleluia, aleluia."},{"k":"ref","t":"Dn 3:52"},{"k":"text","t":"Bendito sois, Senhor, Deus de nossos pais, e digno de louvor em todos os séculos. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 28:18-20"},{"k":"text","t":"In illo témpore: Dixit Jesus discípulis suis: Data est mihi omnis potéstas in cœlo et in terra. Eúntes ergo docéte omnes gentes, baptizántes eos in nómine Patris, et Fílii, et Spíritus Sancti: docéntes eos serváre ómnia, quæcúmque mandávi vobis. Et ecce, ego vobíscum sum ómnibus diébus usque ad consummatiónem sǽculi."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt 28:18-20"},{"k":"text","t":"Naquele tempo, disse Jesus aos discípulos: “Todo o poder me foi dado no céu e na terra. Ide, pois; ensinai todos os povos, baptizando-os em nome do Pai, e do Filho, e do Espírito Santo. Ensinai-os a observar tudo o que vos mandei. E sabei que estou convosco todos os dias até à consumação dos séculos”."}]},"Offertorium":{"la":[{"k":"ref","t":"Tob 12:6."},{"k":"text","t":"Benedíctus sit Deus Pater, unigenitúsque Dei Fílius, Sanctus quoque Spíritus: quia fecit nobíscum misericórdiam suam."}],"pt":[{"k":"ref","t":"Tb. 12:6."},{"k":"text","t":"Bendito seja Deus Pai, e o Filho Unigênito de Deus, e também o Espírito Santo: pois foi misericordioso para conosco."}]},"Secreta":{"la":[{"k":"text","t":"Sanctífica, quǽsumus, Dómine, Deus noster, per tui sancti nóminis invocatiónem, hujus oblatiónis hóstiam: et per eam nosmetípsos tibi pérfice munus ætérnum."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Dignai-Vos, Senhor, nosso Deus, Vos suplicamos, pela invocação do vosso santo nome, santificar esta hóstia, que Vos oferecemos; e que por ela nos convertamos em dom perpétuo de homenagem à vossa majestade."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Tob 12:6"},{"k":"text","t":"Benedícimus Deum cœli et coram ómnibus vivéntibus confitébimur ei: quia fecit nobíscum misericórdiam suam."}],"pt":[{"k":"ref","t":"Tb 12:6"},{"k":"text","t":"Bendizemos Deus do céu e cantamos os seus louvores diante de todos os viventes: pois foi misericordioso para conosco."}]},"Postcommunio":{"la":[{"k":"text","t":"Profíciat nobis ad salútem córporis et ánimæ, Dómine, Deus noster, hujus sacraménti suscéptio: et sempitérnæ sanctæ Trinitátis ejusdémque indivíduæ Unitátis conféssio."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Que a recepção deste sacramento, assim como a crença, que confessamos, na santa e eterna Trindade e indivisível Unidade, nos sirvam, Senhor, de proveito para a salvação da alma e do corpo."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"corpus","la":"Festum Sanctissimi Corporis Christi","pt":"Corpus Christi — Santíssimo Corpo de Cristo","color":"albus","classis":1,"tempus":"postpent","date":"corpus","gloria":true,"credo":true,"praef":"Communis","sequentia":true,"notes":["Sequência “Lauda Sion”, de Santo Tomás de Aquino.","Pelas rubricas de 1960 o Prefácio do Natal deixou de ser próprio desta festa: diz-se o Prefácio comum (O’Connell, The Celebration of Mass, 1964, p. 118-119)."],"source":"Tempora/Pent01-4","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 80:17"},{"k":"text","t":"Cibávit eos ex ádipe fruménti, allelúja: et de petra, melle saturávit eos, allelúja, allelúja, allelúja."},{"k":"ref","t":"Ps 80:2"},{"k":"text","t":"Exsultáte Deo, adjutóri nostro: jubiláte Deo Jacob."},{"k":"gloriapatri"},{"k":"text","t":"Cibávit eos ex ádipe fruménti, allelúja: et de petra, melle saturávit eos, allelúja, allelúja, allelúja."}],"pt":[{"k":"ref","t":"Sl. 80:17."},{"k":"text","t":"O Senhor alimentou-os com a flor da farinha, aleluia: e saciou-os com o mel tirado do rochedo, aleluia, aleluia, aleluia."},{"k":"ref","t":"Sl 80:2"},{"k":"text","t":"Exultai de alegria e louvai a Deus, que é o nosso sustentáculo: Aclamai com júbilo Deus de Jacob."},{"k":"gloriapatri"},{"k":"text","t":"O Senhor alimentou-os com a flor da farinha, aleluia: e saciou-os com o mel tirado do rochedo, aleluia, aleluia, aleluia."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui nobis sub Sacraménto mirábili passiónis tuæ memóriam reliquísti: tríbue, quǽsumus, ita nos Córporis et Sánguinis tui sacra mystéria venerári; ut redemptiónis tuæ fructum in nobis júgiter sentiámus:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Ó Deus, que neste admirável sacramento nos deixastes o memorial da vossa Paixão, concedei-nos, Vos pedimos, que de tal sorte veneremos os sacratíssimos mistérios do vosso Corpo e Sangue, que sintamos perpetuamente no nosso íntimo o fruto da vossa Redenção."},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epistolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","t":"1 Cor 11:23-29"},{"k":"text","t":"Fratres: Ego enim accépi a Dómino quod et trádidi vobis, quóniam Dóminus Jesus, in qua nocte tradebátur, accépit panem, et grátias agens fregit, et dixit: Accípite, et manducáte: hoc est corpus meum, quod pro vobis tradétur: hoc fácite in meam commemoratiónem. Simíliter et cálicem, postquam cenávit, dicens: Hic calix novum Testaméntum est in meo sánguine. Hoc fácite, quotiescúmque bibétis, in meam commemoratiónem. Quotiescúmque enim manducábitis panem hunc et cálicem bibétis, mortem Dómini annuntiábitis, donec véniat. Itaque quicúmque manducáverit panem hunc vel bíberit cálicem Dómini indígne, reus erit córporis et sánguinis Dómini. Probet autem seípsum homo: et sic de pane illo edat et de calice bibat. Qui enim mandúcat et bibit indígne, judícium sibi mandúcat et bibit: non dijúdicans corpus Dómini."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Coríntios."},{"k":"ref","t":"1 Cor 11:23-29"},{"k":"text","t":"Meus irmãos: Foi com o Senhor que aprendi aquilo que vos ensinei: Que o Senhor Jesus, naquela mesma noite em que foi traído, tomou o pão, e, dando graças, partiu-o e disse: “Tomai e comei: isto é o meu corpo, que será entregue por amor de vós. Fazei isto em minha memória”. E, de modo semelhante, após a ceia, tomou também o cálice, dizendo: “Este cálice é a nova aliança no meu sangue. Fazei isto todas as vezes que o beberdes, em minha memória; pois todas as vezes que comerdes este pão e que beberdes este cálice, anunciareis a morte do Senhor, até que Ele venha”. Assim, todo aquele que comer o pão ou beber o cálice do Senhor indignamente, será réu do Corpo e do Sangue do Senhor. Examine-se, pois, o homem a si mesmo; e, depois, coma deste pão e beba deste cálice; pois o que come e bebe indignamente, come e bebe a sua própria condenação, não distinguindo o Corpo do Senhor."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 144:15-16"},{"k":"text","t":"Oculi ómnium in te sperant, Dómine: et tu das illis escam in témpore opportúno,"},{"k":"V","t":"Aperis tu manum tuam: et imples omne ánimal benedictióne. Allelúja, allelúja,"},{"k":"ref","t":"Joannes 6:56-57"},{"k":"text","t":"Caro mea vere est cibus, et sanguis meus vere est potus: qui mandúcat meam carnem et bibit meum sánguinem, in me manet et ego in eo. Alleluia."}],"pt":[{"k":"ref","t":"Sl. 144:15-16."},{"k":"text","t":"Todos os olhos, Senhor, estão voltados para Vós, cheios de esperança: Pois dais a cada um, oportunamente, o seu sustento."},{"k":"V","t":"Abris as vossas mãos e saciais todos os viventes com vossas bênçãos. Aleluia, aleluia."},{"k":"ref","t":"Jo 6:56 - 57."},{"k":"V","t":"Minha Carne é verdadeira comida; e o meu Sangue é verdadeira bebida. Aquele, pois, que come a minha carne e bebe o meu sangue permanece em mim e Eu nele."}]},"Sequentia":{"la":[{"k":"rubric","t":"Thomæ de Aquino. (infra octavam ad libitum Celebrantis omitti potest, juxta Rubricas.)"},{"k":"text","t":"Lauda, Sion, Salvatórem,"},{"k":"text","t":"lauda ducem et pastórem"},{"k":"text","t":"in hymnis et cánticis."},{"k":"text","t":"Quantum potes, tantum aude:"},{"k":"text","t":"quia major omni laude,"},{"k":"text","t":"nec laudáre súfficis."},{"k":"text","t":"Laudis thema speciális,"},{"k":"text","t":"panis vivus et vitális"},{"k":"text","t":"hódie propónitur."},{"k":"text","t":"Quem in sacræ mensa cenæ"},{"k":"text","t":"turbæ fratrum duodénæ"},{"k":"text","t":"datum non ambígitur."},{"k":"text","t":"Sit laus plena, sit sonóra,"},{"k":"text","t":"sit jucúnda, sit decóra"},{"k":"text","t":"mentis jubilátio."},{"k":"text","t":"Dies enim sollémnis agitur,"},{"k":"text","t":"in qua mensæ prima recólitur"},{"k":"text","t":"hujus institútio."},{"k":"text","t":"In hac mensa novi Regis,"},{"k":"text","t":"novum Pascha novæ legis"},{"k":"text","t":"Phase vetus términat."},{"k":"text","t":"Vetustátem nóvitas,"},{"k":"text","t":"umbram fugat véritas,"},{"k":"text","t":"noctem lux elíminat."},{"k":"text","t":"Quod in cœna Christus gessit,"},{"k":"text","t":"faciéndum hoc expréssit"},{"k":"text","t":"in sui memóriam."},{"k":"text","t":"Docti sacris institútis,"},{"k":"text","t":"panem, vinum in salútis"},{"k":"text","t":"consecrámus hóstiam."},{"k":"text","t":"Dogma datur Christiánis,"},{"k":"text","t":"quod in carnem transit panis"},{"k":"text","t":"et vinum in sánguinem."},{"k":"text","t":"Quod non capis, quod non vides,"},{"k":"text","t":"animosa fírmat fides,"},{"k":"text","t":"præter rerum órdinem."},{"k":"text","t":"Sub divérsis speciébus,"},{"k":"text","t":"signis tantum, et non rebus,"},{"k":"text","t":"latent res exímiæ."},{"k":"text","t":"Caro cibus, sanguis potus:"},{"k":"text","t":"manet tamen Christus totus"},{"k":"text","t":"sub utráque spécie."},{"k":"text","t":"A suménte non concísus,"},{"k":"text","t":"non confráctus, non divísus:"},{"k":"text","t":"ínteger accípitur."},{"k":"text","t":"Sumit unus, sumunt mille:"},{"k":"text","t":"quantum isti, tantum ille:"},{"k":"text","t":"nec sumptus consúmitur."},{"k":"text","t":"Sumunt boni, sumunt mali"},{"k":"text","t":"sorte tamen inæquáli,"},{"k":"text","t":"vitæ vel intéritus."},{"k":"text","t":"Mors est malis, vita bonis:"},{"k":"text","t":"vide, paris sumptiónis"},{"k":"text","t":"quam sit dispar éxitus."},{"k":"text","t":"Fracto demum sacraménto,"},{"k":"text","t":"ne vacílles, sed meménto,"},{"k":"text","t":"tantum esse sub fragménto,"},{"k":"text","t":"quantum toto tégitur."},{"k":"text","t":"Nulla rei fit scissúra:"},{"k":"text","t":"signi tantum fit fractúra:"},{"k":"text","t":"qua nec status nec statúra"},{"k":"text","t":"signáti minúitur."},{"k":"text","t":"Ecce panis Angelórum,"},{"k":"text","t":"factus cibus viatórum:"},{"k":"text","t":"vere panis filiórum,"},{"k":"text","t":"non mitténdus cánibus."},{"k":"text","t":"In figúris præsignátur,"},{"k":"text","t":"cum Isaac immolátur:"},{"k":"text","t":"agnus paschæ deputátur:"},{"k":"text","t":"datur manna pátribus."},{"k":"text","t":"Bone pastor, panis vere,"},{"k":"text","t":"Jesu, nostri miserére:"},{"k":"text","t":"tu nos pasce, nos tuére:"},{"k":"text","t":"tu nos bona fac vidére"},{"k":"text","t":"in terra vivéntium."},{"k":"text","t":"Tu, qui cuncta scis et vales:"},{"k":"text","t":"qui nos pascis hic mortáles:"},{"k":"text","t":"tuos ibi commensáles,"},{"k":"text","t":"coherédes et sodáles"},{"k":"text","t":"fac sanctórum cívium."},{"k":"text","t":"Amen. Allelúja."}],"pt":[{"k":"text","t":"Louva, ó Sião, louva o teu Salvador!"},{"k":"text","t":"Louva com hinos e cânticos"},{"k":"text","t":"O teu Principe e Pastor!"},{"k":"text","t":"Louva-O tanto quanto possas:"},{"k":"text","t":"Nem tu podes louvá-l’O dignamente,"},{"k":"text","t":"Pois está acima de todos os louvores."},{"k":"text","t":"O tema dos teus louvores,"},{"k":"text","t":"O Pão vivo e vital"},{"k":"text","t":"É nos oferecido hoje."},{"k":"text","t":"O qual, na ceia"},{"k":"text","t":"Ao grupo dos Doze Irmãos"},{"k":"text","t":"Foi dado sem dúvida."},{"k":"text","t":"Que o louvor seja perene, sonoro e melodioso:"},{"k":"text","t":"Que seja agradável e belo,"},{"k":"text","t":"Como a alegria que transporta as nossas almas!"},{"k":"text","t":"Eis o dia solene,"},{"k":"text","t":"Que nos recorda a primitiva instituição"},{"k":"text","t":"Deste Banquete divino."},{"k":"text","t":"Nesta mesa do novo Rei"},{"k":"text","t":"A Páscoa da nova Lei"},{"k":"text","t":"Acaba com a páscoa antiga."},{"k":"text","t":"O rito antigo cede o lugar ao novo,"},{"k":"text","t":"Como a imagem desaparece diante da realidade,"},{"k":"text","t":"E a luz apaga a noite."},{"k":"text","t":"Aquilo que Cristo praticou na Ceia,"},{"k":"text","t":"Mandou que fizéssemos,"},{"k":"text","t":"Também, em sua memória."},{"k":"text","t":"E nós, instruídos pelo mandato divino,"},{"k":"text","t":"Consagrámos o pão"},{"k":"text","t":"E o vinho em hóstia de salvação."},{"k":"text","t":"É um dogma de fé para os cristãos"},{"k":"text","t":"Que o pão passa para Carne de Cristo"},{"k":"text","t":"E o vinho para seu Sangue."},{"k":"text","t":"Aquilo que não compreendeis, nem vedes,"},{"k":"text","t":"A fé viva o afirma"},{"k":"text","t":"Sem alterar a ordem da natureza."},{"k":"text","t":"Debaixo de diversas espécies,"},{"k":"text","t":"Distintas somente por sinais exteriores,"},{"k":"text","t":"Ocultam-se sublimes realidades."},{"k":"text","t":"A Carne é alimento, o Sangue bebida;"},{"k":"text","t":"Mas Cristo existe inteiro"},{"k":"text","t":"Em cada espécie."},{"k":"text","t":"Quem O recebe, nem O parte,"},{"k":"text","t":"Nem O corta, nem O divide;"},{"k":"text","t":"Porém recebe-O inteiro."},{"k":"text","t":"Quem O receba uma só pessoa, quer O recebam mil,"},{"k":"text","t":"Todas recebem o mesmo:"},{"k":"text","t":"Recebem-n’O sem O consumirem."},{"k":"text","t":"Recebem-n’O bons e maus;"},{"k":"text","t":"Porém com efeitos diferentes:"},{"k":"text","t":"Uns encontram vida; outros a morte!"},{"k":"text","t":"Para os maus é morte e para os bons é vida."},{"k":"text","t":"Vede que diferentes são"},{"k":"text","t":"Os efeitos que produz o mesmo alimento!"},{"k":"text","t":"Que a vossa fé não vacile quando a hóstia é dividida;"},{"k":"text","t":"Mas lembrai-vos de que Jesus"},{"k":"text","t":"Tanto está no fragmento,"},{"k":"text","t":"Como na hóstia inteira."},{"k":"text","t":"A substância não é dividida:"},{"k":"text","t":"Somente o sinal é que é partido,"},{"k":"text","t":"Mas sem diminuição, nem no estado,"},{"k":"text","t":"Nem na grandeza do que está sob as espécies."},{"k":"text","t":"Eis o Pão dos Anjos"},{"k":"text","t":"Que se fez alimento dos homens viadores,"},{"k":"text","t":"Verdadeiro pão dos inocentes,"},{"k":"text","t":"Que não deve ser dado aos cães!"},{"k":"text","t":"Antigamente foi representado por figuras:"},{"k":"text","t":"Imolado com Isaque"},{"k":"text","t":"E significado no cordeiro pascal"},{"k":"text","t":"E no maná do deserto."},{"k":"text","t":"Ó bom Pastor, ó Pão verdadeiro,"},{"k":"text","t":"Ó Jesus, tende piedade de nós:"},{"k":"text","t":"Alimentai-nos, defendei-nos do mal"},{"k":"text","t":"Permiti que gozemos os verdadeiros"},{"k":"text","t":"Bens da terra dos vivos."},{"k":"text","t":"Ó Vós, que tudo conheceis e podeis:"},{"k":"text","t":"Ó Vós, que nos alimentais nesta vida mortal,"},{"k":"text","t":"Tornai-nos co-herdeiros"},{"k":"text","t":"Companheiros dos habitantes"},{"k":"text","t":"Da cidade celestial."},{"k":"text","t":"Amen. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia sancti Evangéli secúndum Joánnem"},{"k":"ref","t":"Joann 6:56-59"},{"k":"text","t":"In illo témpore: Dixit Jesus turbis Judæórum: Caro mea vere est cibus et sanguis meus vere est potus. Qui mandúcat meam carnem et bibit meum sánguinem, in me manet et ego in illo. Sicut misit me vivens Pater, et ego vivo propter Patrem: et qui mandúcat me, et ipse vivet propter me. Hic est panis, qui de cœlo descéndit. Non sicut manducavérunt patres vestri manna, et mórtui sunt. Qui mandúcat hunc panem, vivet in ætérnum."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 6:56-59."},{"k":"text","t":"Naquele tempo, disse Jesus aos judeus: “Minha Carne é verdadeira comida e o meu Sangue é verdadeira bebida. Quem come a minha Carne e bebe o meu Sangue permanece em mim e Eu nele. Assim como meu Pai, que é fonte de vida e me mandou, e Eu vivo de meu Pai, assim também aquele que me comer viverá de mim. Este é o pão que desceu do céu. Porém não é como o maná, que os vossos pais comeram havendo morrido mais tarde. Quem comer este pão viverá eternamente”."}]},"Offertorium":{"la":[{"k":"ref","t":"Levit 21:6"},{"k":"text","t":"Sacerdótes Dómini incénsum et panes ófferunt Deo: et ideo sancti erunt Deo suo, et non pólluent nomen ejus, allelúja."}],"pt":[{"k":"ref","t":"Lev 21:6"},{"k":"text","t":"Os sacerdotes do Senhor oferecem a Deus incenso e pães: eis porque serão santos diante de Deus e não profanarão o seu nome, aleluia."}]},"Secreta":{"la":[{"k":"text","t":"Ecclésiæ tuæ, quǽsumus, Dómine, unitátis et pacis propítius dona concéde: quæ sub oblátis munéribus mýstice designántur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, Vos imploramos, dignai-Vos conceder à vossa Igreja os dons da unidade e da paz, que misticamente se figuram nas ofertas que Vos apresentamos."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"1 Cor 11:26-27"},{"k":"text","t":"Quotiescúmque manducábitis panem hunc et cálicem bibétis, mortem Dómini annuntiábitis, donec véniat: itaque quicúmque manducáverit panem vel bíberit calicem Dómini indígne, reus erit córporis et sánguinis Dómini, allelúja."}],"pt":[{"k":"ref","t":"1 Cor. 11:26-27."},{"k":"text","t":"Todas as vezes que comerdes este Pão e beberdes este Cálice anunciareis a morte do Senhor, até que Ele venha. Assim, todo aquele que comer este Pão ou beber este Cálice indignamente será réu do Corpo e do Sangue do Senhor. Aleluia."}]},"Postcommunio":{"la":[{"k":"text","t":"Fac nos, quǽsumus, Dómine, divinitátis tuæ sempitérna fruitióne repléri: quam pretiósi Corporis et Sanguinis tui temporalis percéptio præfigúrat:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Fazei, Senhor, Vos imploramos, que alcancemos eternamente a vossa divindade na glória eterna, que é figurada neste mundo pela recepção temporal do vosso Corpo e Sangue preciosíssimos."},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]}}},{"id":"cor","la":"Sacratissimi Cordis D.N. Jesu Christi","pt":"Sacratíssimo Coração de Jesus","color":"albus","classis":1,"tempus":"postpent","date":"cor","gloria":true,"credo":true,"praef":"Cord","notes":["Prefácio do Sagrado Coração."],"source":"Tempora/Pent02-5","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 32:11; 32:19"},{"k":"text","t":"Cogitatiónes Cordis ejus in generatióne et generatiónem: ut éruat a morte ánimas eórum et alat eos in fame."},{"k":"ref","t":"Ps 32:1"},{"k":"text","t":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"gloriapatri"},{"k":"text","t":"Cogitatiónes Cordis ejus in generatióne et generatiónem: ut éruat a morte ánimas eórum et alat eos in fame."}],"pt":[{"k":"ref","t":"Sl. 32:11, 19."},{"k":"text","t":"Os pensamentos do seu Coração subsistem de geração em geração, para preservar suas almas da morte e alimentá-las quando tiverem fome."},{"k":"ref","t":"Sl 32:1"},{"k":"text","t":"Exultai no Senhor, ó justos: Cantem seus louvores aqueles que possuem o coração reto."},{"k":"gloriapatri"},{"k":"text","t":"Os pensamentos do seu Coração subsistem de geração em geração, para preservar suas almas da morte e alimentá-las quando tiverem fome."}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui nobis in Corde Fílii tui, nostris vulneráto peccátis, infinítos dilectiónis thesáuros misericórditer largíri dignáris: concéde, quǽsumus; ut, illi devótum pietátis nostræ præstántes obséquium, dignæ quoque satisfactiónis exhibeámus offícium."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eumdem"}],"pt":[{"k":"text","t":"Ó Deus, que no Coração do vosso Filho, ferido pelos nossos pecados, Vos dignastes prodigalizar-nos os tesouros infinitos do seu amor, concedei-nos, Vos suplicamos, que, rendendo-Lhe a homenagem da nossa filial devoção, Lhe apresentemos também os dons da nossa reparação."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","t":"Eph 3:8-12, 14-19"},{"k":"text","t":"Fratres: Mihi, ómnium sanctórum mínimo, data est grátia hæc, in géntibus evangelizáre investigábiles divítias Christi, et illumináre omnes, quæ sit dispensátio sacraménti abscónditi a sǽculis in Deo, qui ómnia creávit: ut innotéscat principátibus et potestátibus in cœléstibus per Ecclésiam multifórmis sapiéntia Dei, secúndum præfinitiónem sæculórum, quam fecit in Christo Jesu, Dómino nostro, in quo habémus fidúciam et accéssum in confidéntia per fidem ejus. Hujus rei grátia flecto génua mea ad Patrem Dómini nostri Jesu Christi, ex quo omnis patérnitas in cœlis ei in terra nominátur, ut det vobis, secúndum divítias glóriæ suæ, virtúte corroborári per Spíritum ejus in interiórem hóminem, Christum habitáre per fidem in córdibus vestris: in caritáte radicáti et fundáti, ut póssitis comprehéndere cum ómnibus sanctis, quæ sit latitúdo, et longitúdo, et sublímitas, et profúndum: scire étiam supereminéntem sciéntiæ caritátem Christi, ut impleámini in omnem plenitúdinem Dei."}],"pt":[{"k":"text","t":"Lição da Epístola do B. Ap. Paulo aos Efésios."},{"k":"ref","t":"Ef. 3:8-12, 14-19."},{"k":"text","t":"Meus irmãos: Fui eu, que sou o mínimo de todos os santos, quem recebeu esta graça de anunciar aos povos as riquezas incompreensíveis de Jesus Cristo e de esclarecer todos os homens, revelando-lhes a economia do mistério, que desde tantos séculos está oculto em Deus, criador de todas as coisas, a fim de que, por meio da Igreja, os potentados e as potestades nos céus conheçam a sabedoria infinitamente variada de Deus, segundo o desígnio eterno que Ele realizou por Jesus Cristo, Nosso Senhor, em quem, pela fé que n’Ele depositamos, temos a franca segurança de nos aproximarmos de Deus com confiança. Por este motivo ajoelho diante do Pai de Nosso Senhor Jesus Cristo, que é o princípio desta grande família no céu e na terra, para que, segundo as riquezas da sua glória, sejais fortificados pelo seu Espírito e revestidos com a graça de homens interiores. Permita Ele que Jesus Cristo habite pela fé nos vossos corações, de modo que, enraizados e imbuídos na caridade, possais compreender com todos os santos a largura, o comprimento, a altura e a profundidade deste mistério e conhecer o amor de Jesus Cristo, o qual ultrapassa toda a ciência; e, assim, fiqueis repletos de plenitude dos dons de Deus."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 24:8-9"},{"k":"text","t":"Dulcis et rectus Dóminus: propter hoc legem dabit delinquéntibus in via."},{"k":"V","t":"Díriget mansúetos in judício, docébit mites vias suas."},{"k":"ref","t":"Mt 11:29"},{"k":"text","t":"Allelúja, allelúja. Tóllite jugum meum super vos, et díscite a me, quia mitis sum et húmilis Corde, et inveniétis réquiem animábus vestris. Allelúja."}],"pt":[{"k":"ref","t":"Sl. 24:8-9."},{"k":"text","t":"O Senhor é bom e reto: eis porque dá uma lei aos delinquentes."},{"k":"V","t":"Ele guia os pacíficos pela justiça e manifesta os seus caminhos aos humildes. Aleluia, aleluia."},{"k":"ref","t":"Mt 11:29"},{"k":"text","t":"Tomai o meu jugo sobre vós e aprendei de mim, que sou manso e humilde de Coração, e achareis paz para as vossas almas. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem"},{"k":"ref","t":"Joannes 19:31-37"},{"k":"text","t":"In illo témpore: Judǽi - quóniam Parascéve erat, - ut non remanérent in cruce córpora sábbato - erat enim magnus dies ille sábbati, - rogavérunt Pilátum, ut frangeréntur eórum crura, et tolleréntur. Venérunt ergo mílites: et primi quidem fregérunt crura et alteríus, qui crucifíxus est cum eo. Ad Jesum autem cum veníssent, ut vidérunt eum jam mórtuum, non fregérunt ejus crura, sed unus mílitum láncea latus ejus apéruit, et contínuo exívit sanguis et aqua. Et qui vidit, testimónium perhíbuit: et verum est testimónium ejus. Et ille scit quia vera dicit, ut et vos credátis. Facta sunt enim hæc ut Scriptúra implerétur: Os non comminuétis ex eo. Et íterum alia Scriptúra dicit: Vidébunt in quem transfixérunt."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 19:31-37."},{"k":"text","t":"Naquele tempo, os judeus (porque era o dia da preparação da Páscoa), não desejando que os corpos ficassem na cruz para o sábado (pois o sábado era solene), pediram a Pilatos consentisse que partissem as pernas aos crucificados e os descessem da cruz. Os soldados vieram, pois, e quebraram as pernas do primeiro e do outro que haviam sido crucificados com Jesus. Tendo vindo a Jesus, como O vissem já morto, Lhe não quebraram as pernas, mas um dos soldados abriu-Lhe o lado com a lança, do qual saiu sangue e água imediatamente. E quem isto viu dá testemunho disso, e o seu testemunho é verdadeiro, pois sabe que diz a verdade, para que também vós acrediteis. Aconteceram estas coisas para se cumprir o que dizia a Escritura: “Não quebrareis nenhum dos meus ossos”. E ainda a Escritura diz em outro lugar: “Contemplarão aquele que traspassaram”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 68:21"},{"k":"text","t":"Impropérium exspectávit Cor meum et misériam: et sustínui, qui simul mecum contristarétur, et non fuit: consolántem me quæsívi, et non invéni."}],"pt":[{"k":"ref","t":"Sl. 68:21."},{"k":"text","t":"Impropérios e misérias afrontaram o meu coração: E procurei quem compartilhasse a minha tristeza, mas não achei; Procurei alguém que me consolasse, mas não encontrei."}]},"Secreta":{"la":[{"k":"text","t":"Réspice, quǽsumus, Dómine, ad ineffábilem Cordis dilécti Fílii tui caritátem: ut quod offérimus sit tibi munus accéptum et nostrórum expiátio delictórum."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eumdem"}],"pt":[{"k":"text","t":"Senhor, Vos suplicamos, atendei benigno à caridade inefável do Coração do vosso amado Filho, a fim de que a oferta, que Vos apresentamos, por Vós seja recebida, e nos sirva de expiação dos nossos pecados."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Joannes 19:34"},{"k":"text","t":"Unus mílitum láncea latus ejus apéruit, et contínuo exívit sanguis et aqua."}],"pt":[{"k":"ref","t":"Jo 19:34."},{"k":"text","t":"Um dos soldados abriu-Lhe o lado com uma lança, e logo saiu sangue e água."}]},"Postcommunio":{"la":[{"k":"text","t":"Prǽbeant nobis, Dómine Jesu, divínum tua sancta fervórem: quo dulcíssimi Cordis tui suavitáte percépta; discámus terréna despícere, et amáre cœléstia:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Que os vossos sacrossantos mistérios nos comuniquem, ó Senhor Jesus, o divino fervor, a fim de que, sentindo as suavidades do vosso dulcíssimo Coração, aprendamos a desprezar as coisas terrenas e a amar as celestiais."},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]}}},{"id":"pent4","la":"Dominica IV post Pentecosten","pt":"IV Domingo depois de Pentecostes","color":"viridis","classis":2,"tempus":"postpent","date":"pent4","gloria":true,"credo":true,"praef":"Trinitate","notes":["Domingo de II classe do Tempo depois de Pentecostes: cor verde, Prefácio da Santíssima Trindade."],"source":"Tempora/Pent04-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 26:1; 26:2"},{"k":"text","t":"Dóminus illuminátio mea et salus mea, quem timebo? Dóminus defensor vitæ meæ, a quo trepidábo? qui tríbulant me inimíci mei, ipsi infirmáti sunt, et cecidérunt."},{"k":"ref","t":"Ps 26:3"},{"k":"text","t":"Si consístant advérsum me castra: non timébit cor meum."},{"k":"gloriapatri"},{"k":"text","t":"Dóminus illuminátio mea et salus mea, quem timebo? Dóminus defensor vitæ meæ, a quo trepidábo? qui tríbulant me inimíci mei, ipsi infirmáti sunt, et cecidérunt."}],"pt":[{"k":"ref","t":"Sl. 26:1-2"},{"k":"text","t":"O Senhor é a minha luz e a minha salvação: a quem, pois, temerei? O Senhor é o defensor da minha vida: quem poderá intimidar-me? Meus inimigos, que me atribulam, enfraqueceram e caíram."},{"k":"ref","t":"Sl 26:3"},{"k":"text","t":"Ainda que um exército me cercasse, o meu coração não temeria."},{"k":"gloriapatri"},{"k":"text","t":"O Senhor é a minha luz e a minha salvação: a quem, pois, temerei? O Senhor é o defensor da minha vida: quem poderá intimidar-me? Meus inimigos, que me atribulam, enfraqueceram e caíram."}]},"Oratio":{"la":[{"k":"text","t":"Da nobis, quǽsumus, Dómine: ut et mundi cursus pacífice nobis tuo órdine dirigátur; et Ecclésia tua tranquílla devotióne lætétur."},{"k":"concl","t":"Per Dominum.","key":"Per Dominum.","missing":true}],"pt":[{"k":"text","t":"Concedei-nos, Senhor, Vos suplicamos, que, sob a conduta da vossa providência, os acontecimentos do mundo decorram pacificamente; e que a vossa Igreja goze a alegria de Vos servir com tranquilidade."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","t":"Rom 8:18-23"},{"k":"text","t":"Fratres: Exístimo, quod non sunt condígnæ passiónes hujus témporis ad futúram glóriam, quæ revelábitur in nobis. Nam exspectátio creatúræ revelatiónem filiórum Dei exspéctat. Vanitáti enim creatúra subjécta est, non volens, sed propter eum, qui subjécit eam in spe: quia et ipsa creatúra liberábitur a servitúte corruptiónis, in libertátem glóriæ filiórum Dei. Scimus enim, quod omnis creatúra ingemíscit et párturit usque adhuc. Non solum autem illa, sed et nos ipsi primítias spíritus habéntes: et ipsi intra nos gémimus, adoptiónem filiórum Dei exspectántes, redemptiónem córporis nostri: in Christo Jesu, Dómino nostro."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Romanos."},{"k":"ref","t":"Rm. 8:18-23"},{"k":"text","t":"Meus irmãos: Estou persuadido de que os sofrimentos da vida presente não têm proporção alguma com a glória que nos há de ser manifestada. Com efeito, as criaturas esperam com viva impaciência a manifestação dos filhos de Deus; pois elas, agora, estão sujeitas à vaidade, não voluntariamente, mas pela vontade daquele que as sujeitou, com a esperança de que seriam livres da servidão da corrupção para participar da liberdade da glória dos filhos de Deus. Na verdade, sabemos que todas as criaturas gemem e estão como que com as dores da maternidade até ao presente. Também nós, que possuímos as primícias do Espírito (que não somente essas), gememos no nosso coração, desejando ardentemente a adoção, como filhos de Deus, e a redenção do corpo, em Nosso Senhor Jesus Cristo."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 78:9; 78:10"},{"k":"text","t":"Propítius esto, Dómine, peccátis nostris: ne quando dicant gentes: Ubi est Deus eórum?"},{"k":"V","t":"Adjuva nos, Deus, salutáris noster: et propter honórem nóminis tui, Dómine, líbera nos."},{"k":"text","t":"Allelúja, allelúja."},{"k":"ref","t":"Ps 9:5; 9:10"},{"k":"text","t":"Deus, qui sedes super thronum, et júdicas æquitátem: esto refúgium páuperum in tribulatióne. Allelúja."}],"pt":[{"k":"ref","t":"Sl. 78:9-10"},{"k":"text","t":"Perdoai os nossos pecados, Senhor, para que os povos não digam: Onde está o seu Deus?"},{"k":"V","t":"Auxiliai-nos, ó Senhor, nosso Salvador: e, pela glória do vosso nome, livrai-nos, Senhor. Aleluia, aleluia."},{"k":"ref","t":"Sl. 9:5; 9:10"},{"k":"text","t":"Deus, que estais sentado no vosso trono e julgais com justiça, sede o refúgio dos pobres na tribulação. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Lucam"},{"k":"ref","t":"Luc 5:1-11"},{"k":"text","t":"In illo témpore: Cum turbæ irrúerent in Jesum, ut audírent verbum Dei, et ipse stabat secus stagnum Genésareth. Et vidit duas naves stantes secus stagnum: piscatóres autem descénderant et lavábant rétia. Ascéndens autem in unam navim, quæ erat Simónis, rogávit eum a terra redúcere pusíllum. Et sedens docébat de navícula turbas. Ut cessávit autem loqui, dixit ad Simónem: Duc in altum, et laxáte rétia vestra in captúram. Et respóndens Simon, dixit illi: Præcéptor, per totam noctem laborántes, nihil cépimus: in verbo autem tuo laxábo rete. Et cum hoc fecíssent, conclusérunt píscium multitúdinem copiósam: rumpebátur autem rete eórum. Et annuérunt sóciis, qui erant in ália navi, ut venírent et adjuvárent eos. Et venérunt, et implevérunt ambas navículas, ita ut pæne mergeréntur. Quod cum vidéret Simon Petrus, prócidit ad génua Jesu, dicens: Exi a me, quia homo peccátor sum, Dómine. Stupor enim circumdéderat eum et omnes, qui cum illo erant, in captúra píscium, quam céperant: simíliter autem Jacóbum et Joánnem, fílios Zebedǽi, qui erant sócii Simónis. Et ait ad Simónem Jesus: Noli timére: ex hoc jam hómines eris cápiens. Et subdúctis ad terram návibus, relictis ómnibus, secuti sunt eum."}],"pt":[{"k":"text","t":"Continuação ++ do Santo Evangelho segundo S. Lucas."},{"k":"ref","t":"Lc 5:1-11"},{"k":"text","t":"Naquele tempo encontrando-se Jesus, nas margens do lago Genesaré, rodeado pela multidão que queria ouvir a sua palavra, viu duas barcas à beira do lago, havendo os pescadores saído delas para lavar as redes. Então, entrou Jesus em uma das barcas, a qual pertencia a Simão, pedindo-lhe que a desviasse um pouco da terra. Depois assentou-se na barca e começou a doutrinar o povo. Quando Jesus acabou de falar, disse a Simão: “Afasta-te para o largo e lança as redes para pescares”. Simão respondeu-Lhe: “Mestre, trabalhámos toda a noite e não pescámos nada; mas, obedecendo à vossa palavra, lançarei a rede”. E, lançando-a, pescaram tão grande quantidade de peixes, que a rede se rompia! Logo fizeram sinal aos companheiros, que estavam na outra barca, para que fossem auxiliá-los. Foram eles e encheram ambas as barcas; e de tal sorte que quase se afundavam! Simão-Pedro, vendo isto, caiu de joelhos aos pés de Jesus e disse: “Afastai-Vos de mim, Senhor, pois sou um homem pecador!”. Simão estava atônito, assim como os companheiros, por causa da pesca que haviam feito! O mesmo acontecia a Tiago e a João, filhos de Zebedeu, que estavam com Simão. Então, Jesus disse a Simão: “Não tenhas receio; doravante serás pescador de homens”. E eles, tendo conduzido as barcas para terra, deixaram tudo e seguiram-n’O."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 12:4-5"},{"k":"text","t":"Illúmina óculos meos, ne umquam obdórmiam in morte: ne quando dicat inimícus meus: Præválui advérsus eum."}],"pt":[{"k":"ref","t":"Sl. 12:4-5"},{"k":"text","t":"Iluminai os meus olhos, para que não adormeça na morte e o meu inimigo não diga mais tarde: prevaleci contra ele."}]},"Secreta":{"la":[{"k":"text","t":"Oblatiónibus nostris, quǽsumus, Dómine, placáre suscéptis: et ad te nostras étiam rebélles compélle propítius voluntátes."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Deixai-Vos aplacar, Senhor, recebendo as nossas oblações; e dignai-Vos propiciamente compelir a nossa vontade rebelde a submeter-se a Vós."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 17:3"},{"k":"text","t":"Dóminus firmaméntum meum, et refúgium meum, et liberátor meus: Deus meus, adjútor meus."}],"pt":[{"k":"ref","t":"Sl. 17:3"},{"k":"text","t":"O Senhor é o meu sustentáculo, o meu refúgio e o meu libertador: Ele é o meu Deus e auxílio!"}]},"Postcommunio":{"la":[{"k":"text","t":"Mystéria nos, Dómine, quǽsumus, sumpta puríficent: et suo múnere tueántur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Vos imploramos, Senhor, que estes mistérios, que recebemos, nos purifiquem; e que pela sua virtude nos sirvam de proteção."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"petrus","la":"Ss. Apostolorum Petri et Pauli","pt":"São Pedro e São Paulo, Apóstolos","color":"ruber","classis":1,"tempus":"postpent","date":"06-29","gloria":true,"credo":true,"praef":"Apostolis","notes":["Festa de I classe; cor vermelha dos mártires; Prefácio dos Apóstolos."],"source":"Sancti/06-29","parts":{"Introitus":{"la":[{"k":"ref","t":"Acts 12:11"},{"k":"text","t":"Nunc scio vere, quia misit Dóminus Angelum suum: et erípuit me de manu Heródis et de omni exspectatióne plebis Judæórum."},{"k":"ref","t":"Ps 138:1-2"},{"k":"text","t":"Dómine; probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"gloriapatri"},{"k":"text","t":"Nunc scio vere, quia misit Dóminus Angelum suum: et erípuit me de manu Heródis et de omni exspectatióne plebis Judæórum."}],"pt":[{"k":"ref","t":"Act 12:11"},{"k":"text","t":"Agora reconheço, verdadeiramente, que o Senhor enviou o seu Anjo: e me livrou das mãos de Herodes e daquilo que esperava o povo judaico!"},{"k":"ref","t":"Sl 138:1-2"},{"k":"text","t":"Experimentastes-me, Senhor, e ficastes-me conhecendo: ficastes conhecendo quando me deito e quando me levanto."},{"k":"gloriapatri"},{"k":"text","t":"Agora reconheço, verdadeiramente, que o Senhor enviou o seu Anjo: e me livrou das mãos de Herodes e daquilo que esperava o povo judaico!"}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui hodiérnam diem Apostolórum tuórum Petri et Pauli martýrio consecrásti: da Ecclésiæ tuæ, eórum in ómnibus sequi præcéptum; per quos religiónis sumpsit exórdium."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus, que consagrastes este dia com o martírio dos vossos Apóstolos Pedro e Paulo, concedei à vossa Igreja a graça de seguir em tudo as lições daqueles pelos quais a religião teve princípio."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Actuum Apostolórum"},{"k":"ref","t":"Act 12:1-11"},{"k":"text","t":"In diébus illis: Misit Heródes rex manus, ut afflígeret quosdam de ecclésia. Occidit autem Jacóbum fratrem Joánnis gládio. Videns autem, quia placéret Judæis, appósuit, ut apprehénderet et Petrum. Erant autem dies azymórum. Quem cum apprehendísset, misit in cárcerem, tradens quátuor quaterniónibus mílitum custodiéndum, volens post Pascha prodúcere eum pópulo. Et Petrus quidem servabátur in cárcere. Orátio autem fiébat sine intermissióne ab ecclésia ad Deum pro eo. Cum autem productúrus eum esset Heródes, in ipsa nocte erat Petrus dórmiens inter duos mílites, vinctus caténis duábus: et custódes ante óstium custodiébant cárcerem. Et ecce, Angelus Dómini ástitit: et lumen refúlsit in habitáculo: percussóque látere Petri, excitávit eum, dicens: Surge velóciter. Et cecidérunt caténæ de mánibus ejus. Dixit autem Angelus ad eum: Præcíngere, et cálcea te cáligas tuas. Et fecit sic. Et dixit illi: Circúmda tibi vestiméntum tuum, et séquere me. Et éxiens sequebátur eum, et nesciébat, quia verum est, quod fiébat per Angelum: existimábat autem se visum vidére. Transeúntes autem primam et secúndam custódiam, venérunt ad portam férream, quæ ducit ad civitátem: quæ ultro apérta est eis. Et exeúntes processérunt vicum unum: et contínuo discéssit Angelus ab eo. Et Petrus ad se revérsus, dixit: Nunc scio vere, quia misit Dóminus Angelum suum, et erípuit me de manu Heródis et de omni exspectatióne plebis Judæórum."}],"pt":[{"k":"text","t":"Lição dos Atos dos Apóstolos."},{"k":"ref","t":"Act 12:1-11"},{"k":"text","t":"Naqueles dias, mandou o rei Herodes que perseguissem alguns membros pertencentes à Igreja. Então, mandou matar à espada Tiago, irmão de João; e, vendo que isto agradava aos judeus, mandou também prender Pedro. Isto aconteceu no dia dos Ázimos. Havendo, pois, Pedro sido preso, mandou-o para o cárcere, encarregando a sua guarda a quatro esquadras de quatro soldados cada uma; e querendo que, depois da Páscoa, comparecesse diante de todo o povo. Enquanto Pedro estava guardado no cárcere, a Igreja dirigia incessantes preces a Deus em seu favor. Ora, durante a noite precedente ao dia que Herodes designara para o suplício, dormia Pedro entre dois soldados, estando ligado com duas correntes e guardando os soldados a porta da prisão. E eis que um Anjo do Senhor apareceu e uma luz brilhou na prisão, o qual, tocando no lado de Pedro, acordou-o, dizendo: “Ergue-te depressa”. Logo as cadeias caíram das suas mãos. Então disse-lhe o Anjo: “Toma o teu cinto e calça-te”. Ele assim fez. E o Anjo continuou: “Enverga a tua capa e segue-me”. Pedro saiu e seguiu-o, não sabendo se aquilo que o Anjo fazia era realidade, mas pensando que era uma visão. Logo que passaram o primeiro e o segundo posto dos guardas, chegaram à porta de ferro que conduz à cidade, a qual se abriu por si diante deles. Tendo-a passado, entraram em uma rua, em cuja extremidade o Anjo deixou Pedro. Então este, voltando a si, disse: “Agora reconheço, verdadeiramente, que o Senhor enviou o seu Anjo e me livrou de Herodes e daquilo que esperava o povo judaico!”."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 44:17-18"},{"k":"text","t":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine."},{"k":"V","t":"Pro pátribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi. Allelúja, allelúja."},{"k":"ref","t":"Matt 16:18"},{"k":"text","t":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"pt":[{"k":"ref","t":"Sl 44:17-18"},{"k":"text","t":"Constitui-los-eis príncipes em toda a terra: e perpetuarão, ó Senhor, a recordação do vosso nome."},{"k":"V","t":"Para substituir vossos pais, dar-vos-á filhos: e, assim, os povos Vos louvarão em todos os séculos dos séculos. Aleluia, aleluia."},{"k":"ref","t":"Mt 18:18"},{"k":"text","t":"Tu és Pedro e sobre esta pedra edificarei a minha Igreja. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 16:13-19"},{"k":"text","t":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt 16:13-19"},{"k":"text","t":"Naquele tempo, foi Jesus para a região de Cesareia, de Filipe, e interrogou os seus discípulos, dizendo-lhes: “Quem dizem os homens que é o Filho do homem?”. Eles responderam: “Uns dizem que é João Batista, outros que é Elias e outros que é Jeremias ou algum dos Profetas”. Jesus disse-lhes: “E quem dizeis vós que eu sou?”. Respondendo, Simão-Pedro disse: “Tu és Cristo, Filho de Deus vivo!”. E Jesus disse-lhe: “Bem-aventurado és tu, Simão Barjona, porque não foi a carne nem o sangue que te revelaram o que dizes, mas meu Pai, que está nos céus. E Eu digo-te: tu és Pedro, e sobre esta pedra edificarei a minha Igreja; e as portas do inferno não prevalecerão contra ela. Eu te darei as chaves do reino dos céus; e tudo o que ligares sobre a terra será ligado também nos céus; e tudo o que desatares sobre a terra será desatado também nos céus”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 44:17-18"},{"k":"text","t":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine, in omni progénie et generatióne."}],"pt":[{"k":"ref","t":"Sl 44:17-18"},{"k":"text","t":"Constitui-los-eis príncipes em toda a terra: e perpetuarão, ó Senhor, a recordação do vosso nome, em todos os séculos dos séculos."}]},"Secreta":{"la":[{"k":"text","t":"Hóstias, Dómine, quas nómini tuo sacrándas offérimus, apostólica prosequátur orátio: per quam nos expiári tríbuas et deféndi."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, que a oração dos vossos Apóstolos acompanhe as hóstias que vamos consagrar em honra do vosso nome, e permiti que nos sirvam de expiação das nossas faltas e de nossa defesa."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Matt 16:18"},{"k":"text","t":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam."}],"pt":[{"k":"ref","t":"Mt 16:18"},{"k":"text","t":"Tu és Pedro, e sobre esta pedra edificarei a minha Igreja."}]},"Postcommunio":{"la":[{"k":"text","t":"Quos cœlésti, Dómine, aliménto satiásti: apostólicis intercessiónibus ab omni adversitáte custódi."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Dignai-Vos, Senhor, pela intercessão dos vossos Apóstolos, preservar de todas as adversidades aqueles que saciastes com o alimento celestial."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"assumpt","la":"In Assumptione B. Mariæ Virginis","pt":"Assunção da Bem-aventurada Virgem Maria","color":"albus","classis":1,"tempus":"postpent","date":"08-15","gloria":true,"credo":true,"praef":"Maria","praefIns":{"la":"Assumptióne","pt":"Assunção"},"notes":["Missa “Signum magnum”, promulgada por Pio XII em 1950 com o dogma da Assunção."],"source":"Sancti/08-15","parts":{"Introitus":{"la":[{"k":"ref","t":"Ap 12:1"},{"k":"text","t":"Signum magnum appáruit in cœlo: múlier amicta sole, et luna sub pédibus ejus, et in cápite ejus coróna stellárum duódecim."},{"k":"ref","t":"Ps 97:1"},{"k":"text","t":"Cantáte Dómino cánticum novum: quóniam mirabília fecit."},{"k":"gloriapatri"},{"k":"text","t":"Signum magnum appáruit in cœlo: múlier amicta sole, et luna sub pédibus ejus, et in cápite ejus coróna stellárum duódecim."}],"pt":[{"k":"ref","t":"Apoc 12:1"},{"k":"text","t":"Um grande prodígio apareceu no céu: uma mulher revestida com o Sol, tendo a lua sob os seus pés e na cabeça uma coroa com doze estrelas."},{"k":"ref","t":"Sl 97:1"},{"k":"text","t":"Cantai ao Senhor um cântico novo, pois Ele operou maravilhas."},{"k":"gloriapatri"},{"k":"text","t":"Um grande prodígio apareceu no céu: uma mulher revestida com o Sol, tendo a lua sob os seus pés e na cabeça uma coroa com doze estrelas."}]},"Oratio":{"la":[{"k":"text","t":"Omnípotens sempitérne Deus, qui Immaculátam Vírginem Maríam, Fílii tui Genetrícem, córpore et ánima ad cœléstem glóriam assumpsísti: concéde, quǽsumus; ut, ad superna semper inténti, ipsíus glóriæ mereámur esse consórtes."},{"k":"concl","t":"Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Per eundem"}],"pt":[{"k":"text","t":"Onipotente e sempiterno Deus, que elevastes em corpo e alma até à glória celestial a Imaculada Virgem Maria, Mãe de vosso Filho, concedei-nos, Vos suplicamos, que, tendo nós sempre presente ao nosso espírito os dons celestiais, mereçamos tornar-nos participantes da mesma glória."},{"k":"concl","t":"Pelo mesmo Jesus Cristo vosso Filho, Nosso Senhor que convosco vive e reina na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per eundem"}]},"Lectio":{"la":[{"k":"text","t":"Léctio libri Judith"},{"k":"ref","t":"Judith 13, 22-25; 15:10"},{"k":"text","t":"Benedíxit te Dóminus in virtúte sua, quia per te ad níhilum redégit inimícos nostros. Benedícta es tu, fília, a Dómino Deo excelso, præ ómnibus muliéribus super terram. Benedíctus Dóminus, qui creávit cœlum et terram, qui te diréxit in vúlnera cápitis príncipis inimicórum nostrórum; quia hódie nomen tuum ita magnificávit, ut non recédat laus tua de ore hóminum, qui mémores fúerint virtútis Dómini in ætérnum, pro quibus non pepercísti ánimæ tuæ propter angústias et tribulatiónem géneris tui, sed subvenísti ruínæ ante conspéctum Dei nostri. Tu glória Jerúsalem, tu lætítia Israël, tu honorificéntia pópuli nostri."}],"pt":[{"k":"text","t":"Lição do Livro de Judite."},{"k":"ref","t":"Jdt 13, 22-25; 15:10"},{"k":"text","t":"Abençoou-te o Senhor com seu poder e por ti aniquilou os nossos inimigos. Bendita és tu, ó filha, entre todas as mulheres, ante o Senhor Deus Altíssimo, e bendito é o Senhor, que criou o céu e a terra e dirigiu os teus passos para cortares a cabeça do chefe dos nossos inimigos; pois, hoje, de tal modo Ele engrandeceu o teu nome que nunca mais o teu elogio se apagará na boca dos que eternamente se lembrarem do poder do Senhor, por amor dos quais não poupaste a tua vida, ao ver as angústias e tribulações do teu povo, antes impediste a sua ruína na presença do nosso Deus. Tu és a glória de Jerusalém, a alegria de Israel e a honra do nosso povo."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 44:11-12; 44:14"},{"k":"text","t":"Audi, fília, et vide, et inclína aurem tuam, et concupíscet rex pulchritúdinem tuam."},{"k":"V","t":"Tota decóra ingréditur fília regis, textúræ áureæ sunt amíctus ejus."},{"k":"text","t":"Allelúja, allelúja."},{"k":"V","t":"Assumpta est María in cœlum: gaudet exércitus Angelórum. Allelúja."}],"pt":[{"k":"ref","t":"Sl 44:11-12; 44:14"},{"k":"text","t":"Ouvi, ó filha, vede e aplicai os vossos ouvidos: e o Rei cobiçará a vossa formosura!"},{"k":"V","t":"A filha do Rei entra toda gloriosa no seu palácio: os seus vestidos são tecidos de brocado de ouro. Aleluia, aleluia."},{"k":"V","t":"Maria foi elevada ao céu em corpo e alma: alegra-se o exército dos Anjos. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Lucam"},{"k":"ref","t":"Luc 1:41-50"},{"k":"text","t":"In illo témpore: Repléta est Spíritu Sancto Elísabeth et exclamávit voce magna, et dixit: Benedícta tu inter mulíeres, et benedíctus fructus ventris tui. Et unde hoc mihi ut véniat mater Dómini mei ad me? Ecce enim ut facta est vox salutatiónis tuæ in áuribus meis, exsultávit in gáudio infans in útero meo. Et beáta, quæ credidísti, quóniam perficiéntur ea, quæ dicta sunt tibi a Dómino. Et ait María: Magníficat ánima mea Dóminum; et exsultávit spíritus meus in Deo salutári meo; quia respéxit humilitátem ancíllæ suæ, ecce enim ex hoc beátam me dicent omnes generatiónes. Quia fecit mihi magna qui potens est, et sanctum nomen ejus, et misericórdia ejus a progénie in progénies timéntibus eum."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Lucas."},{"k":"ref","t":"Lc 1:41-50"},{"k":"text","t":"Naquele tempo: Isabel ficou cheia do Espírito Santo e exclamou, em voz alta: “Bendita sois vós entre as mulheres e bendito é o fruto do vosso ventre. E donde me vem a mim que a mãe do meu Senhor venha até mim? Porquanto, desde que a voz da vossa saudação chegou a meus ouvidos, o meu filho exultou de alegria no meu seio! Bem-aventurada sois, porque acreditastes que se há de cumprir o que vos foi dito da parte do Senhor”. Maria disse então: “Minha alma glorifica o Senhor e o meu espírito se alegra em Deus, meu Salvador, que se dignou olhar para a humildade da sua serva; por isso, eis que todas as gerações me chamarão bem-aventurada. Pois Aquele que é onipotente, e o seu nome é santo, operou em mim maravilhas, e a sua misericórdia multiplicar-se-á de geração em geração sobre os que O temem”."}]},"Offertorium":{"la":[{"k":"ref","t":"Gen 3:15"},{"k":"text","t":"Inimicítias ponam inter te et mulíerem, et semen tuum et semen illíus."}],"pt":[{"k":"ref","t":"Gn 3:15"},{"k":"text","t":"Porei inimizades entre ti e a Mulher, e entre a tua prole e a sua Prole."}]},"Secreta":{"la":[{"k":"text","t":"Ascéndat ad te, Dómine, nostræ devotiónis oblátio, et, beatíssima Vírgine María in cœlum assumpta intercedénte, corda nostra, caritátis igne succénsa, ad te júgiter ádspirent."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ascenda até Vós, Senhor, a oblação da nossa piedade; e, por intercessão da beatíssima Virgem Maria, elevada ao céu em corpo e alma, permiti que, abrasados nossos corações no fogo da caridade, continuamente por Vós aspirem."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Luc 1:48-49"},{"k":"text","t":"Beátam me dicent omnes generatiónes, quia fecit mihi magna qui potens est."}],"pt":[{"k":"ref","t":"Lc 1:48-49"},{"k":"text","t":"Chamar-me-ão Bem-aventurada todas as gerações, pois Aquele, que é onipotente, operou em mim maravilhas."}]},"Postcommunio":{"la":[{"k":"text","t":"Sumptis, Dómine, salutáribus sacraméntis: da, quǽsumus; ut, méritis et intercessióne beátæ Vírginis Maríæ in cœlum assúmptæ, ad resurrectiónis glóriam perducámur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Havendo recebido, Senhor, os vossos salutares sacramentos, concedei-nos, Vos suplicamos, que, pelos méritos e intercessão da Bem-aventurada Virgem Maria, elevada ao céu em corpo e alma, sejamos conduzidos à glória da ressurreição."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"rex","la":"D.N. Jesu Christi Regis","pt":"Nosso Senhor Jesus Cristo Rei","color":"albus","classis":1,"tempus":"postpent","date":"rex","gloria":true,"credo":true,"praef":"Regis","notes":["Último domingo de outubro. Prefácio de Cristo Rei."],"source":"Sancti/10-DU","parts":{"Introitus":{"la":[{"k":"ref","t":"Apoc 5:12; 1:6"},{"k":"text","t":"Dignus est Agnus, qui occísus est, accípere virtútem, et divinitátem, et sapiéntiam, et fortitúdinem, et honórem. Ipsi glória et impérium in sǽcula sæculórum."},{"k":"ref","t":"Ps 71:1"},{"k":"text","t":"Deus, judícium tuum Regi da: et justítiam tuam Fílio Regis."},{"k":"gloriapatri"},{"k":"text","t":"Dignus est Agnus, qui occísus est, accípere virtútem, et divinitátem, et sapiéntiam, et fortitúdinem, et honórem. Ipsi glória et impérium in sǽcula sæculórum."}],"pt":[{"k":"ref","t":"Apoc 5:12; 1:6"},{"k":"text","t":"O Cordeiro, que foi imolado, é digno de receber o poder, a divindade, a sabedoria, a fortaleza, a honra: A Ele a glória e o império em todos os séculos dos séculos."},{"k":"ref","t":"Sl 71:1"},{"k":"text","t":"Ó Deus, dai ao Rei o poder de julgar; e a vossa justiça ao Filho do Rei."},{"k":"gloriapatri"},{"k":"text","t":"O Cordeiro, que foi imolado, é digno de receber o poder, a divindade, a sabedoria, a fortaleza, a honra: A Ele a glória e o império em todos os séculos dos séculos."}]},"Oratio":{"la":[{"k":"text","t":"Omnípotens sempitérne Deus, qui in dilécto Fílio tuo, universórum Rege, ómnia instauráre voluísti: concéde propítius; ut cunctæ famíliæ géntium, peccáti vúlnere disgregátæ, ejus suavissímo subdántur império:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Onipotente e eterno Deus, que tudo quisestes restaurar no vosso dileto Filho, Rei de todas as coisas, concedei-nos propício que todas as famílias do mundo, livres da chaga do pecado, se submetam ao Seu suavíssimo império."},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses."},{"k":"ref","t":"Col 1:12-20"},{"k":"text","t":"Fratres: Grátias ágimus Deo Patri, qui dignos nos fecit in partem sortis sanctórum in lúmine: qui erípuit nos de potestáte tenebrárum, et tránstulit in regnum Fílii dilectiónis suæ, in quo habémus redemptiónem per sánguinem ejus, remissiónem peccatórum: qui est imágo Dei invisíbilis, primogénitus omnis creatúræ: quóniam in ipso cóndita sunt univérsa in cœlis et in terra, visibília et invisibília, sive Throni, sive Dominatiónes, sive Principátus, sive Potestátes: ómnia per ipsum, et in ipso creáta sunt: et ipse est ante omnes, et ómnia in ipso constant. Et ipse est caput córporis Ecclésiæ, qui est princípium, primogénitus ex mórtuis: ut sit in ómnibus ipse primátum tenens; quia in ipso complácuit omnem plenitúdinem inhabitáre; et per eum reconciliáre ómnia in ipsum, pacíficans per sánguinem crucis ejus, sive quæ in terris, sive quæ in cœlis sunt, in Christo Jesu Dómino nostro."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Colossenses."},{"k":"ref","t":"Col 1:12-20"},{"k":"text","t":"Meus irmãos: Damos graças a Deus Pai, porque nos fez dignos de participar da herança dos Santos na luz, nos livrou do poder das trevas e nos conduziu para o reino do seu muito amado Filho, no qual possuímos a redenção pelo seu sangue e a remissão dos pecados. Ele é a imagem de Deus invisível e o primogênito de todas as criaturas; porquanto n’Ele foram criadas todas as coisas nos céus e na terra, visíveis e invisíveis, quer sejam os Tronos, quer as Dominações, quer os Principados, quer as Potestades. Tudo foi criado por Ele e n’Ele próprio. Ele existe antes de todas as coisas e todas as coisas subsistem por Ele. Ele é a cabeça do corpo da Igreja e o princípio e o primogênito de todos os mortais, para que assim conserve a primazia de todas as coisas, pois foi do agrado do Pai que n’Ele residisse toda a plenitude e por Ele se reconciliem em si próprio todas as coisas, pacificando pelo seu sangue na Cruz tanto o que está na terra, como o que está no céu, em Nosso Senhor Jesus Cristo."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 71:8; 78:11"},{"k":"text","t":"Dominábitur a mari usque ad mare, et a flúmine usque ad términos orbis terrárum."},{"k":"V","t":"Et adorábunt eum omnes reges terræ: omnes gentes sérvient ei. Allelúja, allelúja."},{"k":"ref","t":"Dan 7:14."},{"k":"text","t":"Potéstas ejus, potéstas ætérna, quæ non auferétur: et regnum ejus, quod non corrumpétur. Allelúja."}],"pt":[{"k":"ref","t":"Sl 71:8; 78:11"},{"k":"text","t":"Dominará de mar a mar e desde o rio aos confins da redondeza da terra! V. Adorá-l’O-ão todos os reis da terra: e todos os povos O servirão! Aleluia, aleluia."},{"k":"ref","t":"Dn 7:14"},{"k":"text","t":"Seu poder é eterno, nunca Lhe será tirado; seu reino é tal que nunca será corrompido. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem."},{"k":"ref","t":"Joann 18:33-37"},{"k":"text","t":"In illo témpore: Dixit Pilátus ad Jesum: Tu es Rex Judæórum? Respóndit Jesus: A temetípso hoc dicis, an álii dixérunt tibi de me? Respóndit Pilátus: Numquid ego Judǽus sum? Gens tua et pontífices tradidérunt te mihi: quid fecísti? Respóndit Jesus: Regnum meum non est de hoc mundo. Si ex hoc mundo esset regnum meum, minístri mei útique decertárent, ut non tráderer Judǽis: nunc autem regnum meum non est hinc. Dixit ítaque ei Pilátus: Ergo Rex es tu? Respóndit Jesus: Tu dicis, quia Rex sum ego. Ego in hoc natus sum et ad hoc veni in mundum, ut testimónium perhíbeam veritáti: omnis, qui est ex veritáte, audit vocem meam."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 18:33-37"},{"k":"text","t":"Naquele tempo, disse Pilatos a Jesus: “Tu és o rei dos Judeus?”. Respondeu Jesus: “Tu dizes isso de ti mesmo, ou foram outros que to disseram de mim?”. Respondeu Pilatos: “Sou, porventura, judeu? Foram os teus compatriotas e os pontífices que te entregaram nas minhas mãos. O que fizeste?”. Jesus respondeu: “Meu reino não é deste mundo. Se o meu reino fosse deste mundo, certamente os meus ministros haviam de pelejar para que Eu não fosse entregue aos judeus; porém, Eu o declaro agora, o meu reino não é daqui”. Disse-Lhe, então, Pilatos: “És, portanto, rei?”. Jesus respondeu: “Tu dizes que Eu sou rei. Eu para isso nasci e para isso vim a este mundo, a fim de dar testemunho da verdade. Todo aquele que é da verdade, escuta a minha voz”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 2:8."},{"k":"text","t":"Póstula a me, et dabo tibi gentes hereditátem tuam, et possessiónem tuam términos terræ."}],"pt":[{"k":"ref","t":"Sl 2:8"},{"k":"text","t":"Pede-me: e dar-te-ei as nações como herança; e como domínio os confins da terra!"}]},"Secreta":{"la":[{"k":"text","t":"Hóstiam tibi, Dómine, humánæ reconciliatiónis offérimus: præsta, quǽsumus; ut, quem sacrifíciis præséntibus immolámus, ipse cunctis géntibus unitátis et pacis dona concédat, Jesus Christus Fílius tuus, Dóminus noster:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Vos oferecemos, Senhor, a hóstia da reconciliação humana, implorando-Vos que este mesmo Jesus Cristo, vosso Filho e Senhor nosso, o qual imolamos no presente sacrifício, conceda a todos os povos os benefícios da união e da paz:"},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 28:10; 28:11"},{"k":"text","t":"Sedébit Dóminus Rex in ætérnum: Dóminus benedícet pópulo suo in pace."}],"pt":[{"k":"ref","t":"Sl 28:10; 28:11"},{"k":"text","t":"Assentar-se-á, eternamente, o Senhor como Rei e abençoará o seu povo em paz."}]},"Postcommunio":{"la":[{"k":"text","t":"Immortalitátis alimóniam consecúti, quǽsumus, Dómine: ut, qui sub Christi Regis vexíllis militáre gloriámur, cum ipso, in cœlésti sede, júgiter regnáre possímus:"},{"k":"concl","t":"Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus per ómnia sǽcula sæculórum.","key":"Qui tecum"}],"pt":[{"k":"text","t":"Tendo nós alcançado o alimento da imortalidade, Vos suplicamos, Senhor, permiti que possamos reinar perpetuamente na celestial mansão, juntamente com Jesus Cristo, sob cujas bandeiras nos gloriamos de militar:"},{"k":"concl","t":"Que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui tecum"}]}}},{"id":"omnes","la":"Omnium Sanctorum","pt":"Todos os Santos","color":"albus","classis":1,"tempus":"postpent","date":"11-01","gloria":true,"credo":true,"praef":"Communis","notes":["No Missal de 1962 a festa de Todos os Santos usa o Prefácio comum."],"source":"Sancti/11-01","parts":{"Introitus":{"la":[{"k":"text","t":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre Sanctórum ómnium: de quorum sollemnitáte gaudent Angeli et colláudant Fílium Dei."},{"k":"ref","t":"Ps 32:1"},{"k":"text","t":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"gloriapatri"},{"k":"text","t":"Gaudeámus omnes in Dómino, diem festum celebrántes sub honóre Sanctórum ómnium: de quorum sollemnitáte gaudent Angeli et colláudant Fílium Dei."}],"pt":[{"k":"text","t":"Alegremo-nos todos no Senhor, neste dia em que celebramos a festa em honra de Todos os Santos, de cuja solenidade se regozijam os Anjos, louvando unissonamente o Filho de Deus."},{"k":"ref","t":"Sl 32:1"},{"k":"text","t":"Aclamai o Senhor, ó justos; pois é aos que possuem o coração reto que pertence louvar o Senhor."},{"k":"gloriapatri"},{"k":"text","t":"Alegremo-nos todos no Senhor, neste dia em que celebramos a festa em honra de Todos os Santos, de cuja solenidade se regozijam os Anjos, louvando unissonamente o Filho de Deus."}]},"Oratio":{"la":[{"k":"text","t":"Omnípotens sempitérne Deus, qui nos ómnium Sanctórum tuórum mérita sub una tribuísti celebritáte venerári: quǽsumus; ut desiderátam nobis tuæ propitiatiónis abundántiam, multiplicátis intercessóribus, largiáris."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Onipotente e eterno Deus, que nos permitistes a graça de celebrar em uma só festividade os méritos de todos vossos Santos, concedei-nos, Vos rogamos, que, assistidos de tão numerosos intercessores, alcancemos cada vez mais a abundância tão desejada das vossas graças."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio libri Apocalýpsis beáti Joánnis Apóstoli."},{"k":"ref","t":"Apoc 7:2-12"},{"k":"text","t":"In diébus illis: Ecce, ego Joánnes vidi álterum Angelum ascendéntem ab ortu solis, habéntem signum Dei vivi: et clamávit voce magna quátuor Angelis, quibus datum est nocére terræ et mari, dicens: Nolíte nocére terræ et mari neque arbóribus, quoadúsque signémus servos Dei nostri in fróntibus eórum. Et audívi númerum signatórum, centum quadragínta quátuor mília signáti, ex omni tribu filiórum Israël. Ex tribu Juda duódecim mília signáti. Ex tribu Ruben duódecim mília signáti. Ex tribu Gad duódecim mília signati. Ex tribu Aser duódecim mília signáti. Ex tribu Néphthali duódecim mília signáti. Ex tribu Manásse duódecim mília signáti. Ex tribu Símeon duódecim mília signáti. Ex tribu Levi duódecim mília signáti. Ex tribu Issachar duódecim mília signati. Ex tribu Zábulon duódecim mília signáti. Ex tribu Joseph duódecim mília signati. Ex tribu Bénjamin duódecim mília signáti. Post hæc vidi turbam magnam, quam dinumeráre nemo póterat, ex ómnibus géntibus et tríbubus et pópulis et linguis: stantes ante thronum et in conspéctu Agni, amícti stolis albis, et palmæ in mánibus eórum: et clamábant voce magna, dicéntes: Salus Deo nostro, qui sedet super thronum, et Agno. Et omnes Angeli stabant in circúitu throni et seniórum et quátuor animálium: et cecidérunt in conspéctu throni in fácies suas et adoravérunt Deum, dicéntes: Amen. Benedíctio et cláritas et sapiéntia et gratiárum áctio, honor et virtus et fortitúdo Deo nostro in sǽcula sæculórum. Amen."}],"pt":[{"k":"text","t":"Lição do Livro do Apocalipse do Bem-aventurado Apóstolo João."},{"k":"ref","t":"Apoc 7:2-12"},{"k":"text","t":"Naqueles dias, eu, João, vi um outro Anjo que subia do lado do nascer do sol, tendo na mão o sinal de Deus vivo e clamando com voz forte aos quatro Anjos, que haviam recebido o poder de ferirem a terra e o mar, e dizendo: “Não prejudiqueis nem a terra, nem o mar, nem as árvores, enquanto não houvermos marcado na fronte os servos do nosso Deus”. E ouvi que o número daqueles que haviam sido marcados com o sinal, eram cento e quarenta e quatro mil de todas as tribos de Israel: havia doze mil da tribo de Judá, marcados com o sinal; doze mil da tribo de Ruben, marcados com o sinal; doze mil da tribo de Gad, marcados com o sinal; doze mil da tribo de Aser, marcados com o sinal; doze mil da tribo de Naftali, marcados com o sinal; doze mil da tribo de Manassés, marcados com o sinal; doze mil da tribo de Simeão, marcados com o sinal; doze mil da tribo de Levi, marcados com o sinal; doze mil da tribo de Issacar, marcados com o sinal; doze mil da tribo de Zabulão, marcados com o sinal; doze mil da tribo de José, marcados com o sinal; e doze mil da tribo de Benjamim, marcados com o sinal. Depois disto vi uma grande multidão (que ninguém podia contar) de todas as nações, de todas as tribos, de todos os povos e de todas as línguas, que estavam de pé, diante do trono e do Cordeiro, vestidos com túnicas brancas, empunhando palmas e clamando com voz forte: “Glória ao nosso Deus, que está sentado no trono, e ao Cordeiro!”. E todos os Anjos se conservaram em volta do trono, dos anciãos e dos quatro animais. E, prostrados diante do trono e com o rosto em terra, adoravam Deus, dizendo: “Amen! Bênção, glória, sabedoria, ação de graças, honra, soberania e império ao nosso Deus em todos os séculos. Amen”."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 33:10; 33:11"},{"k":"text","t":"Timéte Dóminum, omnes Sancti ejus: quóniam nihil deest timéntibus eum."},{"k":"V","t":"Inquiréntes autem Dóminum, non defícient omni bono. Allelúja, allelúja."},{"k":"ref","t":"Matt 11:28"},{"k":"text","t":"Veníte ad me, omnes, qui laborátis et oneráti estis: et ego refíciam vos. Allelúja."}],"pt":[{"k":"ref","t":"Sl 33:10; 33:11"},{"k":"text","t":"Temei o Senhor, ó vós, que sois os seus Anjos; pois àqueles que O temem nada faltará."},{"k":"V","t":"Aqueles que procuram o Senhor não serão privados de nenhum bem. Aleluia, aleluia."},{"k":"ref","t":"Mt 11:28"},{"k":"text","t":"Vinde a mim, vós, todos, que estais aflitos: e Eu vos aliviarei. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 5:1-12"},{"k":"text","t":"In illo témpore: Videns Jesus turbas, ascéndit in montem, et cum sedísset, accessérunt ad eum discípuli ejus, et apériens os suum, docébat eos, dicens: Beáti páuperes spíritu: quóniam ipsórum est regnum cœlórum. ¶ Beáti mites: quóniam ipsi possidébunt terram. Beáti, qui lugent: quóniam ipsi consolabúntur. Beáti, qui esúriunt et sítiunt justítiam: quóniam ipsi saturabúntur. Beáti misericórdes: quóniam ipsi misericórdiam consequántur. Beáti mundo corde: quóniam ipsi Deum vidébunt. Beáti pacífici: quóniam fílii Dei vocabúntur. Beáti, qui persecutiónem patiúntur propter justítiam: quóniam ipsórum est regnum cœlórum. Beáti estis, cum maledíxerint vobis et persecúti vos fúerint, et díxerint omne malum advérsum vos, mentiéntes, propter me: gaudete et exsultáte, quóniam merces vestra copiósa est in cœlis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt 5:1-12"},{"k":"text","t":"Naquele tempo, vendo Jesus as turbas do povo, que O seguiam, subiu para uma montanha. Então assentou-se, aproximando-se d’Ele os discípulos. Depois, tomando a palavra, pregou assim aos seus discípulos: “Bem-aventurados os pobres de espírito, porque deles é o reino dos céus. Bem-aventurados os mansos, porque possuirão a terra. Bem-aventurados os que choram, porque serão consolados. Bem-aventurados os que têm fome e sede de justiça, porque serão saciados. Bem-aventurados os misericordiosos, porque serão tratados com misericórdia. Bem-aventurados os que possuem o coração puro, porque verão Deus. Bem-aventurados os pacíficos, porque serão chamados filhos de Deus. Bem-aventurados os que sofrem perseguição por amor da justiça, porque lhes pertencerá o reino dos céus. Bem-aventurados, vós, quando os homens vos amaldiçoarem, perseguirem e caluniarem por minha causa: regozijai-vos, então, e exultai de alegria, pois uma copiosa recompensa vos está preparada nos céus”."}]},"Offertorium":{"la":[{"k":"ref","t":"Sap 3:1-3"},{"k":"text","t":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiæ: visi sunt óculis insipiéntium mori: illi autem sunt in pace, allelúja."},{"k":"text","t":"(sed post Septuagesimam dicitur)"},{"k":"text","t":"pace."}],"pt":[{"k":"ref","t":"Sb 3:1-3"},{"k":"text","t":"As almas dos justos estão nas mãos de Deus e o tormento da malícia as não tocará! Aos olhos dos insensatos pareciam quase a morrer, todavia estão na paz. Aleluia."}]},"Secreta":{"la":[{"k":"text","t":"Múnera tibi, Dómine, nostra devotiónis offérimus: quæ et pro tuórum tibi grata sint honóre Justórum, et nobis salutária, te miseránte, reddántur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Vos oferecemos, Senhor, estes dons da nossa devoção; e, em atenção aos merecimentos dos vossos justos, dignai-Vos aceitá-los, e pela vossa misericórdia fazei que nos sejam salutares."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Matt 5:8-10"},{"k":"text","t":"Beáti mundo corde, quóniam ipsi Deum vidébunt; beáti pacífici, quóniam filii Dei vocabúntur: beáti, qui persecutiónem patiúntur propter justítiam, quóniam ipsórum est regnum cœlórum."}],"pt":[{"k":"ref","t":"Mt 5:8-10"},{"k":"text","t":"Bem-aventurados os que possuem o coração puro, porque verão a Deus; bem-aventurados os pacíficos, porque serão chamados filhos de Deus; bem-aventurados os que sofrem perseguição por amor da justiça, porque o reino do céu lhes pertence."}]},"Postcommunio":{"la":[{"k":"text","t":"Da, quǽsumus, Dómine, fidélibus pópulis ómnium Sanctórum semper veneratióne lætári: et eórum perpétua supplicatióne muníri."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Senhor, Vos rogamos, fazei que os vossos povos fiéis venerem sempre com alegria os vossos Santos e sejam sempre protegidos pela sua intercessão."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"defuncti","la":"In Commemoratione Omnium Fidelium Defunctorum — Ad primam Missam","pt":"Comemoração de Todos os Fiéis Defuntos — Primeira Missa","color":"niger","classis":1,"tempus":"postpent","date":"11-02","gloria":false,"credo":false,"praef":"Defunctorum","ps42":false,"gloriaPatri":false,"requiem":true,"ite":"requiescant","sequentia":true,"notes":["Missa de Réquiem: omitem-se o Salmo 42 e o “Gloria Patri”.","No Intróito o celebrante não se benze: traça o sinal da cruz sobre o livro, pelos defuntos.","Não se abençoa a água no Ofertório; o acólito não beija as galhetas.","Agnus Dei com “dona eis réquiem”; não se bate no peito.","Omite-se a primeira oração antes da Comunhão (Domine Jesu Christe, qui dixisti).","“Requiéscant in pace” em lugar do “Ite, missa est”; não se dá a bênção.","Sequência “Dies iræ”."],"source":"Sancti/11-02m1","parts":{"Introitus":{"la":[{"k":"ref","t":"4 Esdr 2:34; 2:35"},{"k":"text","t":"Réquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis."},{"k":"ref","t":"Ps 64:2-3"},{"k":"text","t":"Te decet hymnus, Deus, in Sion, et tibi reddétur votum in Jerúsalem: exáudi oratiónem meam, ad te omnis caro véniet."},{"k":"text","t":"Réquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis."}],"pt":[{"k":"ref","t":"4 Ezd 2:34; 2:35"},{"k":"text","t":"Dai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua."},{"k":"ref","t":"Sl 64:2-3"},{"k":"text","t":"A Vós, Senhor, dirigimos estes hinos em Sião: e oferecemos estes votos em Jerusalém: ouvi a minha oração: todas as criaturas devem comparecer ante Vós."},{"k":"text","t":"Dai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua."}]},"Oratio":{"la":[{"k":"text","t":"Fidélium, Deus, ómnium Cónditor et Redémptor: animábus famulórum famularúmque tuárum remissiónem cunctórum tríbue peccatórum; ut indulgéntiam, quam semper optavérunt, piis supplicatiónibus consequántur:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Ó Deus, Criador e Redentor de todos os fiéis, concedei às almas dos vossos servos a remissão de todos seus pecados, a fim de que pelas nossas humilíssimas orações alcancem da vossa misericórdia o perdão que sempre desejaram."},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","t":"1 Cor 15:51-57"},{"k":"text","t":"Fratres: Ecce, mystérium vobis dico: Omnes quidem resurgámus, sed non omnes immutábimur. In moménto, in ictu óculi, in novíssima tuba: canet enim tuba, et mórtui resúrgent incorrúpti: et nos immutábimur. Opórtet enim corruptíbile hoc induere incorruptiónem: et mortále hoc indúere immortalitátem. Cum autem mortále hoc indúerit immortalitátem, tunc fiet sermo, qui scriptus est: Absórpta est mors in victória. Ubi est, mors, victória tua? Ubi est, mors, stímulus tuus? Stímulus autem mortis peccátum est: virtus vero peccáti lex. Deo autem grátias, qui dedit nobis victóriam per Dóminum nostrum Jesum Christum."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Coríntios."},{"k":"ref","t":"1 Cor 15:51-57"},{"k":"text","t":"Irmãos: Eis um mistério que vos revelo: Ressuscitaremos todos certamente; mas não seremos todos mudados. Num instante, num abrir e fechar de olhos, ao som da última trombeta, porque, então a trombeta soará e os mortos ressuscitarão incorruptíveis, e nós seremos transmudados. Pois é preciso que este corpo corruptível se revista da incorruptibilidade, e que este corpo mortal se revista da imortalidade. Quando este corpo corruptível se revestir da incorruptibilidade e este corpo mortal se revestir da imortalidade, então se cumprirá a palavra que está escrita: “A morte foi absorvida pela vitória. Onde está, ó morte, a tua vitória? Onde está, ó morte, o teu aguilhão?”. Ora, o aguilhão da morte é o pecado; e a força do pecado é a lei. Graças, pois, sejam rendidas a Deus, que nos concedeu a vitória por Jesus Cristo, Senhor nosso."}]},"Graduale":{"la":[{"k":"ref","t":"4 Esdr 2:34-35"},{"k":"text","t":"Réquiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis."},{"k":"ref","t":"Ps 111:7."},{"k":"V","t":"In memória ætérna erit justus: ab auditióne mala non timébit."},{"k":"rubric","t":"Tractus"},{"k":"text","t":"Absólve, Dómine, ánimas ómnium fidélium ab omni vínculo delictórum."},{"k":"V","t":"Et grátia tua illis succurrénte, mereántur evádere judícium ultiónis."},{"k":"V","t":"Et lucis ætérnæ beatitúdine pérfrui."}],"pt":[{"k":"ref","t":"4 Ezdr 2:34-35"},{"k":"text","t":"Dai-lhes, Senhor, o eterno repouso, e que lhes resplandeça a luz perpétua."},{"k":"ref","t":"Sl 111:7"},{"k":"V","t":"A recordação do homem justo permanecerá eternamente; este não temerá ouvir as sentenças más dos homens."},{"k":"rubric","t":"Tractus"},{"k":"text","t":"Livrai, Senhor, as almas dos fiéis defuntos das cadeias dos seus pecados:"},{"k":"V","t":"E que com o socorro da vossa graça consigam evitar o juízo da vingança:"},{"k":"V","t":"E gozem a bem-aventurança da luz eterna."}]},"Sequentia":{"la":[{"k":"text","t":"Dies iræ, dies illa"},{"k":"text","t":"Solvet sæclum in favílla:"},{"k":"text","t":"Teste David cum Sibýlla."},{"k":"text","t":"Quantus tremor est futúrus,"},{"k":"text","t":"Quando judex est ventúrus,"},{"k":"text","t":"Cuncta stricte discussúrus!"},{"k":"text","t":"Tuba mirum spargens sonum"},{"k":"text","t":"Per sepúlcra regiónum,"},{"k":"text","t":"Coget omnes ante thronum."},{"k":"text","t":"Mors stupébit et natúra,"},{"k":"text","t":"Cum resúrget creatúra,"},{"k":"text","t":"Judicánti responsúra."},{"k":"text","t":"Liber scriptus proferétur,"},{"k":"text","t":"In quo totum continétur,"},{"k":"text","t":"Unde mundus judicétur."},{"k":"text","t":"Judex ergo cum sedébit,"},{"k":"text","t":"Quidquid latet, apparébit:"},{"k":"text","t":"Nil inúltum remanébit."},{"k":"text","t":"Quid sum miser tunc dictúrus?"},{"k":"text","t":"Quem patrónum rogatúrus,"},{"k":"text","t":"Cum vix justus sit secúrus?"},{"k":"text","t":"Rex treméndæ majestátis,"},{"k":"text","t":"Qui salvándos salvas gratis,"},{"k":"text","t":"Salva me, fons pietátis."},{"k":"text","t":"Recordáre, Jesu pie,"},{"k":"text","t":"Quod sum causa tuæ viæ:"},{"k":"text","t":"Ne me perdas illa die."},{"k":"text","t":"Quærens me, sedísti lassus:"},{"k":"text","t":"Redemísti Crucem passus:"},{"k":"text","t":"Tantus labor non sit cassus."},{"k":"text","t":"Juste judex ultiónis,"},{"k":"text","t":"Donum fac remissiónis"},{"k":"text","t":"Ante diem ratiónis."},{"k":"text","t":"Ingemísco, tamquam reus:"},{"k":"text","t":"Culpa rubet vultus meus:"},{"k":"text","t":"Supplicánti parce, Deus."},{"k":"text","t":"Qui Maríam absolvísti,"},{"k":"text","t":"Et latrónem exaudísti,"},{"k":"text","t":"Mihi quoque spem dedísti."},{"k":"text","t":"Preces meæ non sunt dignæ:"},{"k":"text","t":"Sed tu bonus fac benígne,"},{"k":"text","t":"Ne perénni cremer igne."},{"k":"text","t":"Inter oves locum præsta,"},{"k":"text","t":"Et ab hœdis me sequéstra,"},{"k":"text","t":"Státuens in parte dextra."},{"k":"text","t":"Confutátis maledíctis,"},{"k":"text","t":"Flammis ácribus addíctis:"},{"k":"text","t":"Voca me cum benedíctis."},{"k":"text","t":"Oro supplex et acclínis,"},{"k":"text","t":"Cor contrítum quasi cinis:"},{"k":"text","t":"Gere curam mei finis."},{"k":"text","t":"Lacrimósa dies illa,"},{"k":"text","t":"Qua resúrget ex favílla"},{"k":"text","t":"Judicándus homo reus."},{"k":"text","t":"Huic ergo parce, Deus:"},{"k":"text","t":"Pie Jesu Dómine,"},{"k":"text","t":"Dona eis réquiem."},{"k":"text","t":"Amen."}],"pt":[{"k":"text","t":"Dia da ira aquele dia"},{"k":"text","t":"em que o universo será reduzido a cinzas,"},{"k":"text","t":"segundo as profecias de David e Sibila."},{"k":"text","t":"Qual não será o terror dos homens"},{"k":"text","t":"quando o soberano Juiz vier examinar"},{"k":"text","t":"todas as ações com rigor!"},{"k":"text","t":"O som estridente da trombeta acordará os mortos,"},{"k":"text","t":"nas profundezas das sepulturas,"},{"k":"text","t":"reunindo-os todos diante do trono do Senhor."},{"k":"text","t":"A morte e a natureza ficarão estupefatas"},{"k":"text","t":"quando a criatura comparecer"},{"k":"text","t":"para ser julgada pelo Juiz."},{"k":"text","t":"Um livro aparecerá,"},{"k":"text","t":"onde está escrito tudo sobre o que há de consistir"},{"k":"text","t":"o julgamento do mundo."},{"k":"text","t":"Quando o Juiz se assentar no tribunal,"},{"k":"text","t":"tudo o que estiver oculto ficará descoberto,"},{"k":"text","t":"e nenhum crime ficará impune."},{"k":"text","t":"Infeliz de mim! Que poderei dizer então?"},{"k":"text","t":"Que protetor procurarei,"},{"k":"text","t":"quando somente o justo está tranquilo?!"},{"k":"text","t":"Ó Rei, cuja majestade é tremenda,"},{"k":"text","t":"mas que salvais, gratuitamente, os escolhidos,"},{"k":"text","t":"salvai-me, ó fonte de piedade!"},{"k":"text","t":"Recordai-Vos, ó piíssimo Jesus,"},{"k":"text","t":"de que vieste ao mundo por minha causa:"},{"k":"text","t":"não me condeneis nesse dia."},{"k":"text","t":"Ó Vós, que Vos fatigastes em minha procura"},{"k":"text","t":"e que para me resgatardes morrestes na Cruz:"},{"k":"text","t":"não queirais que fiquem infrutíferos tantos esforços."},{"k":"text","t":"Ó justo Juiz, que castigais com justiça,"},{"k":"text","t":"concedei-me o perdão das minhas faltas"},{"k":"text","t":"antes do dia do julgamento."},{"k":"text","t":"Eu choro, como réu;"},{"k":"text","t":"as minhas culpas envergonham-me."},{"k":"text","t":"Ó Deus, que minhas súplicas me alcancem perdão."},{"k":"text","t":"Ó Vós, que absolvestes Maria"},{"k":"text","t":"e ouvistes o ladrão,"},{"k":"text","t":"e me concedestes também a esperança!"},{"k":"text","t":"Bem sei que minhas preces não são dignas;"},{"k":"text","t":"mas Vós, que sois bom,"},{"k":"text","t":"não consintais que eu arda no fogo eterno."},{"k":"text","t":"Colocai-me entre os cordeiros,"},{"k":"text","t":"à vossa direita,"},{"k":"text","t":"e separai-me dos pecadores."},{"k":"text","t":"Livrai-me da confusão"},{"k":"text","t":"e do suplicio dos malditos condenados"},{"k":"text","t":"e introduzi-me junto dos benditos de vosso Pai."},{"k":"text","t":"Prostrado ante Vós, suplicante,"},{"k":"text","t":"com o coração esmagado, como reduzido a cinzas,"},{"k":"text","t":"Vos imploro, ó da morte."},{"k":"text","t":"Dia de lágrimas aquele em"},{"k":"text","t":"que o homem renasça da sua cinza"},{"k":"text","t":"para ser julgado!"},{"k":"text","t":"Tende, pois, piedade dele, ó meu Deus!"},{"k":"text","t":"Ó piíssimo Jesus, ó Senhor,"},{"k":"text","t":"concedei-lhe o repouso eterno."},{"k":"text","t":"Amen."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Joánnem"},{"k":"ref","t":"Joann 5:25-29"},{"k":"text","t":"In illo témpore: Dixit Jesus turbis Judæórum: Amen, amen, dico vobis, quia venit hora, et nunc est, quando mórtui áudient vocem Fílii Dei: et qui audíerint, vivent. Sicut enim Pater habet vitam in semetípso, sic dedit et Fílio habére vitam in semetípso: et potestátem dedit ei judícium fácere, quia Fílius hóminis est. Nolíte mirári hoc, quia venit hora, in qua omnes, qui in monuméntis sunt, áudient vocem Fílii Dei: et procédent, qui bona fecérunt, in resurrectiónem vitæ: qui vero mala egérunt, in resurrectiónem judícii."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. João."},{"k":"ref","t":"Jo 5:25-29"},{"k":"text","t":"Naquele tempo, disse Jesus às turbas dos judeus: “Em verdade, em verdade vos digo: A hora chega (ela chegou já) em que os mortos ouvirão a voz do Filho de Deus; e os que a ouvirem, viverão. Porque, assim como o Pai tem a vida em si, assim Ele deu ao Filho o poder de ter a vida em si; e deu-lhe, também, o poder de julgar, pois Ele é o Filho do homem. Não vos admireis disto, pois vem a hora em que todos aqueles que estão nos túmulos ouvirão a voz do Filho de Deus. Então, aqueles que tiverem praticado obras boas sairão para a ressurreição da vida eterna; e aqueles que tiverem praticado obras más ressuscitarão para a condenação”."}]},"Offertorium":{"la":[{"k":"text","t":"Dómine Jesu Christe, Rex glóriæ, líbera ánimas ómnium fidélium defunctórum de pœnis inférni et de profúndo lacu: líbera eas de ore leónis, ne absórbeat eas tártarus, ne cadant in obscúrum: sed sígnifer sanctus Míchaël repræséntet eas in lucem sanctam:"},{"k":"text","t":"* Quam olim Abrahæ promisísti et sémini ejus."},{"k":"V","t":"Hóstias et preces tibi, Dómine, laudis offérimus: tu súscipe pro animábus illis, quarum hódie memóriam fácimus: fac eas, Dómine, de morte transíre ad vitam."},{"k":"text","t":"* Quam olim Abrahæ promisísti et sémini ejus."}],"pt":[{"k":"text","t":"Senhor Jesus Cristo, Rei da glória, livrai as almas de todos os fiéis defuntos das penas do inferno e do lago profundo; livrai-as da boca do leão; que o inferno as não sepulte, nem elas se abismem nas trevas desse lugar tremendo; mas que S. Miguel, que é o porta-estandarte divino, as conduza até à luz santa. Como outrora prometestes a Abraão e à sua posteridade."},{"k":"V","t":"Vos oferecemos, Senhor, estas hóstias e estas orações de louvor: aceitai-as pelas almas daqueles que hoje comemoramos, e fazei-as passar da morte à vida: Como outrora prometestes a Abraão e à sua posteridade."}]},"Secreta":{"la":[{"k":"text","t":"Hóstias, quǽsumus, Dómine, quas tibi pro animábus famulórum famularúmque tuárum offérimus, propitiátus inténde: ut, quibus fídei christiánæ méritum contulísti, dones et prǽmium."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Olhai benigno, Senhor, Vos suplicamos, para as hóstias que Vos oferecemos pelas almas dos vossos servos, a fim de que, depois de lhes haverdes concedido o dom da fé cristã, lhes proporcioneis a recompensa."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"4 Esdr 2:35; 2:34"},{"k":"text","t":"Lux ætérna lúceat eis, Dómine:"},{"k":"text","t":"* Cum Sanctis tuis in ætérnum: quia pius es."},{"k":"V","t":"Requiem ætérnam dona eis, Dómine: et lux perpétua lúceat eis."},{"k":"text","t":"* Cum Sanctis tuis in ætérnum: quia pius es."}],"pt":[{"k":"ref","t":"4 Ezdr 2:35; 2:34"},{"k":"text","t":"Que a luz eterna lhes resplandeça: Com os vossos Santos em todos os séculos, ó Senhor, pois sois bom."},{"k":"V","t":"Dai-lhes, Senhor, o eterno repouso, e que a luz perpétua lhes resplandeça: Com os vossos santos em todos os séculos, ó Senhor, pois sois misericordioso."}]},"Postcommunio":{"la":[{"k":"text","t":"Animábus, quǽsumus, Dómine, famulórum famularúmque tuárum orátio profíciat supplicántium: ut eas et a peccátis ómnibus éxuas, et tuæ redemptiónis fácias esse partícipes:"},{"k":"concl","t":"Qui vivis et regnas cum Deo Patre, in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.","key":"Qui vivis"}],"pt":[{"k":"text","t":"Que as nossas humildes preces sejam proveitosas às almas dos vossos servos e servas, a fim de que, soltas das cadeias dos seus pecados, participem dos frutos da vossa redenção."},{"k":"concl","t":"Vós que, sendo Deus, viveis e reinais com Deus Pai na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Qui vivis"}]}}},{"id":"greg","la":"S. Gregorii Thaumaturgi Episcopi et Confessoris","pt":"São Gregório Taumaturgo, Bispo e Confessor","color":"albus","classis":3,"tempus":"postpent","date":"11-17","gloria":true,"credo":false,"praef":"Communis","notes":["Festa de III classe: Glória, sem Credo, Prefácio comum.","Missa “Statuit” do Comum de um Confessor Pontífice, com Evangelho próprio."],"source":"Sancti/11-17","parts":{"Introitus":{"la":[{"k":"ref","t":"Eccli 45:30"},{"k":"text","t":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum."},{"k":"ref","t":"Ps 131:1."},{"k":"text","t":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"gloriapatri"},{"k":"text","t":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum."}],"pt":[{"k":"ref","t":"Sb 45:30"},{"k":"text","t":"Deus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal."},{"k":"ref","t":"Sl 131:1"},{"k":"text","t":"Lembrai-vos de David, ó Senhor, e da sua grande mansidão."},{"k":"gloriapatri"},{"k":"text","t":"Deus estabeleceu com ele aliança de paz e tornou-o príncipe, para que possuísse eternamente a dignidade sacerdotal."}]},"Oratio":{"la":[{"k":"text","t":"Da, quǽsumus, omnípotens Deus: ut beáti Gregórii Confessóris tui atque Pontíficis veneránda solémnitas, et devotiónem nobis áugeat et salútem."},{"k":"concl","t":"Per Dominum.","key":"Per Dominum.","missing":true}],"pt":[{"k":"text","t":"Dignai-Vos permitir, ó Deus onipotente, que a veneranda solenidade do vosso Confessor e Pontífice Gregório aumente a nossa piedade e nos assegure a salvação."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio libri Sapiéntiæ"},{"k":"ref","t":"Eccli 44:16-27; 45, 3-20"},{"k":"text","t":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo, et invéntus est justus: et in témpore iracúndiæ factus est reconciliátio. Non est invéntus símilis illi, qui conservávit legem Excélsi. Ideo jurejurándo fecit illum Dóminus créscere in plebem suam. Benedictiónem ómnium géntium dedit illi, et testaméntum suum confirmávit super caput ejus. Agnóvit eum in benedictiónibus suis: conservávit illi misericórdiam suam: et invénit grátiam coram óculis Dómini. Magnificávit eum in conspéctu regum: et dedit illi corónam glóriæ. Státuit illi testaméntum ætérnum, et dedit illi sacerdótium magnum: et beatificávit illum in glória. Fungi sacerdótio, et habére laudem in nómine ipsíus, et offérre illi incénsum dignum in odórem suavitátis."}],"pt":[{"k":"text","t":"Lição do Livro da Sabedoria."},{"k":"ref","t":"Sb 44:16-27; 45:3-20"},{"k":"text","t":"Eis o grande sacerdote, que nos dias da sua vida agradou a Deus e foi julgado justo; e no tempo da ira se tornou a reconciliação dos homens. Ninguém o igualou na observância das leis do Altíssimo. Eis porque o Senhor jurou que o tornaria grande no meio do seu povo. O Senhor abençoou nele todos os povos; e com ele ratificou a sua aliança. O Senhor deu-lhe as suas bênçãos e continuou a dispensar-lhe a sua misericórdia, vendo-se bem que este homem achou graça aos olhos do Senhor, que, por isso mesmo, o engrandeceu diante dos reis e lhe deu uma coroa de glória. Estabeleceu com ele uma aliança eterna, elevou-o ao sumo sacerdócio, e tornou-o feliz na glória para exercer o sacerdócio, louvar o seu nome e oferecer-lhe dignamente incenso de odor agradável."}]},"Graduale":{"la":[{"k":"ref","t":"Eccli 44:16"},{"k":"text","t":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","t":"Eccli 44:20"},{"k":"text","t":"Non est invéntus símilis illi, qui conserváret legem Excélsi. Allelúja, allelúja."},{"k":"ref","t":"Ps 109:4"},{"k":"text","t":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"pt":[{"k":"ref","t":"Sb 44:16"},{"k":"text","t":"Eis o grande sacerdote que nos dias da sua vida agradou a Deus."},{"k":"ref","t":"Sb 44:20"},{"k":"V","t":"Não foi encontrado outrem semelhante a ele na observância das leis do Altíssimo. Aleluia, aleluia."},{"k":"ref","t":"Sl 109:4"},{"k":"text","t":"Tu és sacerdote para sempre, segundo a ordem de Melquisedeque. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Marcum"},{"k":"ref","t":"Marc 11:22-24"},{"k":"text","t":"In illo témpore: Respóndens Jesus discípulis suis, ait illis: Habéte fidem Dei. Amen, dico vobis, quia, quicúmque díxerit huic monti: Tóllere et míttere in mare, et non hæsitáverit in corde suo, sed credíderit, quia, quodcúmque díxerit, fiat, fiet ei. ¶ Proptérea dico vobis: Omnia quæcúmque orántes pétitis, crédite quia accipiétis, et evénient vobis."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Marcos."},{"k":"ref","t":"Mc 11:22-24"},{"k":"text","t":"Naquele tempo, Jesus disse aos seus discípulos: “Tende fé em Deus. Em verdade vos digo que todo aquele que disser a esta montanha “tira-te e lança-te no mar”, e disser isto sem hesitar no seu coração e até acreditando que tudo o que disse acontecerá, fique certo de que o verá cumprir-se. Eis porque vos digo: Tudo quanto pedirdes na oração acreditai que o alcançareis e vereis”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 88:21-22"},{"k":"text","t":"Invéni David servum meum, óleo sancto meo unxi eum: manus enim mea auxiliábitur ei, et bráchium meum confortábit eum."}],"pt":[{"k":"ref","t":"Sl 88:21-22"},{"k":"text","t":"Encontrei o meu servo David: e ungi-o com meu óleo sagrado: a minha mão o socorrerá e o meu braço o fortalecerá."}]},"Secreta":{"la":[{"k":"text","t":"Sancti tui, quǽsumus, Dómine, nos ubíque lætíficant: ut, dum eórum mérita recólimus, patrocínia sentiámus."},{"k":"concl","t":"Per Dominum.","key":"Per Dominum.","missing":true}],"pt":[{"k":"text","t":"Que os vossos santos, Senhor, Vos suplicamos, nos alegrem em toda a parte, a fim de que, honrando os seus méritos, sintamos o efeito do seu patrocínio."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Luc 12:42"},{"k":"text","t":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram."}],"pt":[{"k":"ref","t":"Lc 12:42"},{"k":"text","t":"Eis o servo fiel e prudente que o Senhor estabeleceu acima da sua família para distribuir, oportunamente, a cada um a sua medida de trigo."}]},"Postcommunio":{"la":[{"k":"text","t":"Præsta, quǽsumus, omnípotens Deus: ut, de percéptis munéribus grátias exhibéntes, intercedénte beáto Gregórii Confessóre tuo atque Pontífice, benefícia potióra sumámus."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Dignai-Vos permitir, ó Deus onipotente, que, dando-Vos nós graças pelos benefícios recebidos, alcancemos por intercessão do B. N., vosso Confessor e Pontífice, ainda outros maiores."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"caecilia","la":"S. Cæciliæ Virginis et Martyris","pt":"Santa Cecília, Virgem e Mártir","color":"ruber","classis":3,"tempus":"postpent","date":"11-22","gloria":true,"credo":false,"praef":"Communis","notes":["Festa de III classe; cor vermelha das virgens mártires; padroeira da música sacra."],"source":"Sancti/11-22","parts":{"Introitus":{"la":[{"k":"ref","t":"Ps 118:46-47"},{"k":"text","t":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis."},{"k":"ref","t":"Ps 118:1"},{"k":"text","t":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"gloriapatri"},{"k":"text","t":"Loquébar de testimóniis tuis in conspéctu regum, et non confundébar: et meditábar in mandátis tuis, quæ diléxi nimis."}],"pt":[{"k":"ref","t":"Sl 118:46-47"},{"k":"text","t":"Falava dos vossos testemunhos na presença dos reis, sem qualquer vergonha, e meditava nos vossos mandamentos, que amava profundamente. (Aleluja, aleluja.)"},{"k":"ref","t":"Sl 118:1"},{"k":"text","t":"Bem-aventurados aqueles que são imaculados nos seus caminhos e cumprem a Lei do Senhor."},{"k":"gloriapatri"},{"k":"text","t":"Falava dos vossos testemunhos na presença dos reis, sem qualquer vergonha, e meditava nos vossos mandamentos, que amava profundamente. (Aleluja, aleluja.)"}]},"Oratio":{"la":[{"k":"text","t":"Deus, qui nos ánnua beátæ Cæcíliæ Vírginis et Mártyris tuæ sollemnitáte lætíficas: da, ut, quam venerámur offício, étiam piæ conversatiónis sequámur exémplo."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Ó Deus, que nos alegrais com a solenidade anual da B. Cecília, vossa Virgem e Mártir, dignai-Vos permitir que, honrando-a com estes cultos, imitemos também os exemplos da sua piedosa vida."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio libri Sapiéntiæ"},{"k":"ref","t":"Eccli 51:13-17"},{"k":"text","t":"Dómine, Deus meus, exaltásti super terram habitatiónem meam, et pro morte defluénte deprecáta sum. Invocávi Dóminum, Patrem Dómini mei, ut non derelínquat me in die tribulatiónis meæ, et in témpore superbórum sine adjutório. Laudábo nomen tuum assídue, et collaudábo illud in confessióne, et exaudíta est orátio mea. Et liberásti me de perditióne, et eripuísti me de témpore iníquo. Proptérea confitébor et laudem dicam tibi, Dómine, Deus noster."}],"pt":[{"k":"text","t":"Lição do Livro da Sabedoria."},{"k":"ref","t":"Sb 51:13-17"},{"k":"text","t":"Senhor, meu Deus, elevastes a minha morada acima da terra. Roguei-Vos que me livrásseis da morte, que me ameaça. Supliquei ao Senhor, Pai do meu Senhor, que me não abandone sem socorro no dia da minha aflição e durante o poderio dos soberbos. Louvarei incessantemente o vosso nome e glorificá-lo-ei na minha ação de graças, porque ouvistes a minha oração, livrastes-me da perdição e arrancastes-me da ocasião iníqua! Eis porque Vos glorificarei, cantando louvores em vossa honra, ó Senhor, nosso Deus."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 44:11; 44:12"},{"k":"text","t":"Audi, fília, et vide, et inclína aurem tuam: quia concupívit Rex spéciem tuam."},{"k":"ref","t":"Ps 44:5"},{"k":"text","t":"Spécie tua et pulchritúdine tua inténde, próspere procéde et regna."},{"k":"text","t":"Allelúja, allelúja."},{"k":"ref","t":"Matt 25:4; 25:6"},{"k":"text","t":"Quinque prudéntes vírgines accepérunt óleum in vasis suis cum lampádibus: média autem nocte clamor factus est: Ecce, sponsus venit: exíte óbviam Christo Dómino. Allelúja."}],"pt":[{"k":"ref","t":"Ps 44:11; 44:12"},{"k":"text","t":"Escutai, ó minha filha, vede e inclinai o vosso ouvido; o Rei está cheio de amor por vós, por causa da vossa beleza!"},{"k":"ref","t":"Ps 44:5"},{"k":"V","t":"Com a vossa glória e com vossa formosura caminhai, triunfai e reinai. Aleluia, aleluia."},{"k":"ref","t":"Mt 25:4; 25:6"},{"k":"text","t":"As cinco virgens prudentes tomaram óleo em seus vasos para suas lâmpadas. No meio da noite uma voz soou: eis que chega o esposo: ide ao encontro de Cristo, Senhor. Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 25:1-13"},{"k":"text","t":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Símile erit regnum coelórum decem virgínibus: quæ, accipiéntes lámpades suas, exiérunt óbviam sponso et sponsæ. Quinque autem ex eis erant fátuæ, et quinque prudéntes: ¶ sed quinque fátuæ, accéptis lampádibus, non sumpsérunt óleum secum: prudéntes vero accepérunt óleum in vasis suis cum lampádibus. Moram autem faciénte sponso, dormitavérunt omnes et dormiérunt. Média autem nocte clamor factus est: Ecce, sponsus venit, exíte óbviam ei. Tunc surrexérunt omnes vírgines íllæ, et ornavérunt lámpades suas. Fátuæ autem sapiéntibus dixérunt: Date nobis de óleo vestro: quia lámpades nostræ exstinguúntur. Respondérunt prudéntes, dicéntes: Ne forte non suffíciat nobis et vobis, ite pótius ad vendéntes, et émite vobis. Dum autem irent émere, venit sponsus: et quæ parátæ erant, intravérunt cum eo ad núptias, et clausa est jánua. Novíssime vero véniunt et réliquæ vírgines, dicéntes: Dómine, Dómine, áperi nobis. At ille respóndens, ait: Amen, dico vobis, néscio vos. Vigiláte ítaque, quia nescítis diem neque horam."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt 25:1-13"},{"k":"text","t":"Naquele tempo, disse Jesus aos seus discípulos esta parábola: “O reino dos céus é semelhante a dez virgens que, empunhando suas lâmpadas, saíram ao encontro do esposo e da esposa. Porém, cinco destas virgens eram loucas e as outras cinco eram prudentes. Ora, as cinco loucas, empunhando suas lâmpadas, não levaram azeite. Ao contrário, as prudentes tomaram azeite em seus vasos para suas lâmpadas. Como o esposo se demorasse em chegar, tiveram sono e dormiram. Quando era meia-noite, ouviu-se um clamor dizer: “Eis que chega o esposo; ide ao seu encontro”. Então todas estas virgens se ergueram e prepararam as suas lâmpadas. As loucas disseram às prudentes: “Dai-nos do vosso azeite, porque as nossas lâmpadas apagam-se”. As prudentes responderam-lhes: “Não, porque pode suceder que, como a vós, nos falte o azeite; ide antes aos que o vendem, e comprai-o”. Ora, enquanto elas foram comprar o azeite, veio o esposo. Então, as que estavam preparadas entraram com ele para as bodas; e fechou-se a porta. Por fim vieram as outras virgens, e disseram: “Senhor, senhor, abri-nos a porta”. Ele respondeu: “Na verdade vos digo: não vos conheço. Vigiai, pois, visto que não sabeis nem o dia nem a hora”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 44:15-16"},{"k":"text","t":"Afferéntur Regi Vírgines post eam: próximæ ejus afferéntur tibi in lætítia et exsultatióne: adducéntur in templum Regi Dómino."}],"pt":[{"k":"ref","t":"Sl 44:15-16"},{"k":"text","t":"Após ela, serão apresentadas virgens ao Rei: as suas companheiras serão introduzidas no meio da alegria e do júbilo; elas serão conduzidas ao templo do Rei, seu Senhor. (Aleluja.)"}]},"Secreta":{"la":[{"k":"text","t":"Hæc hóstia, Dómine, placatiónis et laudis, quǽsumus: ut, intercedénte beáta Cæcília Vírgine et Mártyre tua, nos propitiatióne tua dignos semper effíciat."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Que esta hóstia de propiciação e de louvor, Senhor, Vos rogamos, nos torne sempre dignos da vossa misericórdia, pela intercessão da B. Cecília, vossa Virgem e Mártir."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Ps 118:78; 118:80"},{"k":"text","t":"Confundántur supérbi, quia injúste iniquitátem fecérunt in me: ego autem in mandátis tuis exercébor, in tuis justificatiónibus, ut non confúndar."}],"pt":[{"k":"ref","t":"Sl 118:78; 118:80"},{"k":"text","t":"Sejam confundidos os soberbos, porque praticaram iniquidades contra mim. Para não ser confundido no último dia, cumprirei os vossos mandamentos e preceitos. (Aleluja.)"}]},"Postcommunio":{"la":[{"k":"text","t":"Satiásti, Dómine, famíliam tuam munéribus sacris: ejus, quǽsumus, semper interventióne nos réfove, cujus sollémnia celebrámus."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Saciastes, Senhor, a vossa família com vossos sacratíssimos dons; e dignai-Vos favorecer-nos sempre, Vos imploramos, pela intercessão daquela cuja festa celebramos."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}},{"id":"pent24","la":"Dominica XXIV et ultima post Pentecosten","pt":"XXIV e Último Domingo depois de Pentecostes","color":"viridis","classis":2,"tempus":"postpent","date":"pent24","gloria":true,"credo":true,"praef":"Trinitate","notes":["Último domingo do ano litúrgico: o Evangelho anuncia a vinda do Filho do homem (Mt 24)."],"source":"Tempora/Pent24-0","parts":{"Introitus":{"la":[{"k":"ref","t":"Jer 29:11; 29:12; 29:14"},{"k":"text","t":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."},{"k":"ref","t":"Ps 84:2"},{"k":"text","t":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"gloriapatri"},{"k":"text","t":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."}],"pt":[{"k":"ref","t":"Jr 29:11-12; 29:14"},{"k":"text","t":"Disse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos."},{"k":"ref","t":"Sl 84:2"},{"k":"text","t":"Abençoastes, Senhor, a vossa terra e livrastes Jacob do cativeiro."},{"k":"gloriapatri"},{"k":"text","t":"Disse o Senhor: tenho pensamentos de paz e não de ira: invocar-me-eis e ouvir-vos-ei; e farei regressar de todos os países os vossos cativos."}]},"Oratio":{"la":[{"k":"text","t":"Excita, quǽsumus, Dómine, tuórum fidélium voluntátes: ut, divíni óperis fructum propénsius exsequéntes; pietátis tuæ remédia majóra percípiant."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Despertai, Senhor, Vos imploramos, a vontade dos vossos fiéis, para que, procurando com mais fervor o fruto das obras divinas, alcancem da vossa misericórdia os melhores remédios."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Lectio":{"la":[{"k":"text","t":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses"},{"k":"ref","t":"Col 1:9-14"},{"k":"text","t":"Fratres: Non cessámus pro vobis orántes et postulántes, ut impleámini agnitióne voluntátis Dei, in omni sapiéntia et intelléctu spiritáli: ut ambulétis digne Deo per ómnia placéntes: in omni ópere bono fructificántes, et crescéntes in scientia Dei: in omni virtúte confortáti secúndum poténtiam claritátis ejus in omni patiéntia, et longanimitáte cum gáudio, grátias agentes Deo Patri, qui dignos nos fecit in partem sortis sanctórum in lúmine: qui erípuit nos de potestáte tenebrárum, et tránstulit in regnum Fílii dilectiónis suæ, in quo habémus redemptiónem per sánguinem ejus, remissiónem peccatórum."}],"pt":[{"k":"text","t":"Lição da Epístola do Bem-aventurado Apóstolo Paulo aos Colossenses."},{"k":"ref","t":"Col 1:9-14"},{"k":"text","t":"Meus irmãos: Não cessamos de orar a Deus por vós e de pedir-Lhe que vos conceda o verdadeiro conhecimento da sua vontade em toda a plenitude da sabedoria e da inteligência espiritual, para que tenhais uma conduta digna de Deus, agradando-Lhe em todas as coisas, dando frutos em todas as espécies de boas obras e progredindo no conhecimento de Deus. Que sejais fortificados com o poder da glória de Deus para suportardes tudo com paciência, longanimidade e alegria, dando graças a Deus Pai, que nos tornou dignos de tomar parte na herança dos Santos na luz e nos livrou do poder das trevas, para nos transportarmos ao reino do seu amantíssimo Filho, em quem alcançámos pelo seu Sangue a Redenção e a remissão dos pecados."}]},"Graduale":{"la":[{"k":"ref","t":"Ps 43:8-9"},{"k":"text","t":"Liberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti."},{"k":"V","t":"In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja."},{"k":"ref","t":"Ps 129:1-2"},{"k":"text","t":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja."}],"pt":[{"k":"ref","t":"Sl 43:8-9"},{"k":"text","t":"Livrastes-nos, Senhor, daqueles que nos afligiam: e confundistes os que nos odiavam."},{"k":"V","t":"Glorificar-nos-emos constantemente em Deus e louvaremos eternamente o vosso nome. Aleluia, aleluia."},{"k":"ref","t":"Sl 129:1-2"},{"k":"text","t":"Do fundo do abismo Vos invoquei, Senhor: escutai a minha oração. Aleluia."},{"k":"text","t":"Aleluia."}]},"Evangelium":{"la":[{"k":"text","t":"Sequéntia ++ sancti Evangélii secúndum Matthǽum"},{"k":"ref","t":"Matt 24:15-35"},{"k":"text","t":"In illo témpore: Dixit Jesus discípulis suis: Cum vidéritis abominatiónem desolatiónis, quæ dicta est a Daniéle Prophéta, stantem in loco sancto: qui legit, intélligat: tunc qui in Judǽa sunt, fúgiant ad montes: et qui in tecto, non descéndat tóllere áliquid de domo sua: et qui in agro, non revertátur tóllere túnicam suam. Væ autem prægnántibus et nutriéntibus in illis diébus. Oráte autem, ut non fiat fuga vestra in híeme vel sábbato. Erit enim tunc tribulátio magna, qualis non fuit ab inítio mundi usque modo, neque fiet. Et nisi breviáti fuíssent dies illi, non fíeret salva omnis caro: sed propter eléctos breviabúntur dies illi. Tunc si quis vobis díxerit: Ecce, hic est Christus, aut illic: nolíte crédere. Surgent enim pseudochrísti et pseudoprophétæ, et dabunt signa magna et prodígia, ita ut in errórem inducántur - si fíeri potest - étiam elécti. Ecce, prædíxi vobis. Si ergo díxerint vobis: Ecce, in desérto est, nolíte exíre: ecce, in penetrálibus, nolíte crédere. Sicut enim fulgur exit ab Oriénte et paret usque in Occidéntem: ita erit et advéntus Fílii hóminis. Ubicúmque fúerit corpus, illic congregabúntur et áquilæ. Statim autem post tribulatiónem diérum illórum sol obscurábitur, et luna non dabit lumen suum, et stellæ cadent de cælo, et virtútes cœlórum commovebúntur: et tunc parébit signum Fílii hóminis in cœlo: et tunc plangent omnes tribus terræ: et vidébunt Fílium hóminis veniéntem in núbibus cæli cum virtúte multa et majestáte. Et mittet Angelos suos cum tuba et voce magna: et congregábunt eléctos ejus a quátuor ventis, a summis cœlórum usque ad términos eórum. Ab árbore autem fici díscite parábolam: Cum jam ramus ejus tener fúerit et fólia nata, scitis, quia prope est æstas: ita et vos cum vidéritis hæc ómnia, scitóte, quia prope est in jánuis. Amen, dico vobis, quia non præteríbit generátio hæc, donec ómnia hæc fiant. Cœlum et terra transíbunt, verba autem mea non præteríbunt."}],"pt":[{"k":"text","t":"Continuação ++ do santo Evangelho segundo S. Mateus."},{"k":"ref","t":"Mt. 24:15-35"},{"k":"text","t":"Naquele tempo, disse Jesus aos seus discípulos: Quando virdes a abominação da desolação, anunciada pelo Profeta Daniel, reinando no lugar santo, que aquele que lê entenda: Então, aqueles que estão na Judeia fujam para as montanhas; aquele que se achar em cima do telhado não desça para ir buscar qualquer coisa a casa; e aquele que estiver nos campos não volte a casa para procurar algum vestido. Ai das mulheres que estiverem prestes a ser mães: ou a amamentar seus filhos nesses dias! Rogai ao Senhor que a vossa fuga não seja nem no Inverno, nem ao sábado; pois a aflição será tão grande que não houve coisa semelhante desde o princípio do mundo até ao presente, como não haverá nunca mais; e, se esses dias não fossem abreviados (e sê-lo-ão em atenção aos escolhidos), ninguém seria salvo. Então, se alguém vos disser: “O Cristo está aqui, ou está acolá”, não acrediteis; pois aparecerão falsos cristos e falsos profetas, que praticarão grandes maravilhas e prodígios até mesmo seduzirem (se tal fora possível) os próprios escolhidos. Eu vo-lo anuncio, desde já. Se, pois, vos disserem: “Ei-l’O está no deserto”, não saiais; ou se vos disserem: “Ei-l’O aqui, no lugar mais retirado de casa”, não acrediteis também; pois, assim como o relâmpago parte do Oriente e brilha até ao Ocidente, assim será também a vinda do Filho do homem. Em qualquer lugar em que estiver o cadáver aí se reunirão as águias. Imediatamente após a tribulação destes dias o sol se obscurecerá, a lua não projetará luz, as estrelas cairão do céu e os poderes dos céus serão abalados. E aparecerá no céu o sinal do Filho do homem, e todas as tribos da terra se lamentarão: e verão o Filho do homem sobre as nuvens do céu, revestido de grande poder e majestade! Ele enviará os seus Anjos, que farão retinir a trombeta em som estridente, e logo convocarão os escolhidos dos quatro ventos, desde uma extremidade dos céus até à outra! Compreendei isto por esta parábola, tirada da figueira: “Quando os seus ramos estão tenros e as folhas começam a despontar, conheceis que está próximo o estio; assim também, quando virdes todas estas coisas, sabereis que o Filho do homem está próximo, que está à porta”. Em verdade vos digo: “Esta geração não passará sem que isto aconteça. Passarão o céu e a terra; mas as minhas palavras não passarão!”."}]},"Offertorium":{"la":[{"k":"ref","t":"Ps 129:1-2"},{"k":"text","t":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine."}],"pt":[{"k":"ref","t":"Sl 129:1-2"},{"k":"text","t":"Das profundezas dos abismos Vos invoquei, Senhor; escutai, Senhor, a minha voz: das profundezas dos abismos Vos invoquei."}]},"Secreta":{"la":[{"k":"text","t":"Propítius esto, Dómine, supplicatiónibus nostris: et, pópuli tui oblatiónibus precibúsque suscéptis, ómnium nostrum ad te corda convérte; ut, a terrenis cupiditátibus liberáti, ad cœléstia desidéria transeámus."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Sede propício, Senhor, às nossas súplicas, e, depois de haverdes recebido as ofertas e as orações do vosso povo, convertei a Vós os nossos corações, a fim de que, sendo livres das cobiças deste mundo, não tenhamos outra aspiração senão a dos bens do céu."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]},"Communio":{"la":[{"k":"ref","t":"Marc 11:24"},{"k":"text","t":"Amen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis."}],"pt":[{"k":"ref","t":"Mc 11:24"},{"k":"text","t":"Na verdade vos digo: “Tudo o que pedirdes nas vossas orações, acreditai que o recebereis; e far-se-á como pedirdes”."}]},"Postcommunio":{"la":[{"k":"text","t":"Concéde nobis, quǽsumus, Dómine: ut per hæc sacraménta quæ súmpsimus, quidquid in nostra mente vitiósum est, ipsorum medicatiónis dono curétur."},{"k":"concl","t":"Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum.","key":"Per Dominum"}],"pt":[{"k":"text","t":"Permiti, Senhor, Vos suplicamos, que pela virtude destes sacramentos, que recebemos, tudo quanto houver de vicioso na nossa alma seja curado pelo efeito deste remédio divino."},{"k":"concl","t":"Por Nosso Senhor Jesus Cristo, vosso Filho que, sendo Deus, vive e reina convosco na unidade do Espírito Santo, por todos os séculos dos séculos.","key":"Per Dominum"}]}}}],"prefaces":{"Communis":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessione dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai onipotente, eterno Deus, por Nosso Senhor Jesus Cristo. Pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades se prostram reverentes; e os Céus, as Virtudes dos céus e os bem-aventurados Serafins a celebram em comum alegria e louvor. Dignai-Vos permitir, Vos imploramos, que as nossas vozes suplicantes se unam às deles, dizendo:\n"},"Nat":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Quia per incarnáti Verbi mystérium nova mentis nostræ óculis lux tuæ claritátis infúlsit: ut, dum visibíliter Deum cognóscimus, per hunc in invisibílium amorem rapiámur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cæléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes.\n","pt":"v. Verdadeiramente é digno e justo, racional e salutar dar-Vos graças, Senhor santo, Pai onipotente, eterno Deus, em todos os lugares e sempre, porque pelo mistério do Verbo Incarnado um novo clarão do vosso esplendor iluminou a nossa alma, a fim de que, ao passo que conhecemos Deus de uma maneira visível, sejamos inspirados por Ele no amor às coisas invisíveis. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo incessantemente:\n"},"Epi":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Quia, cum Unigénitus tuus in substántia nostræ mortalitátis appáruit, nova nos immortalitátis suæ luce reparávit. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\n","pt":"v. Verdadeiramente é digno e justo, racional e salutar dar-Vos graças, Senhor santo, Pai onipotente, eterno Deus, em todos os lugares e sempre: Pois o vosso Filho Unigênito, revestido com a substancia da nossa carne mortal, reparou as faltas da natureza humana, comunicando-lhe o novo esplendor da sua imortalidade. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo incessantemente:\n"},"Quad":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine, sancte Pater, omnípotens ætérne Deus: Qui corporáli ieiúnio vítia cómprimis, mentem élevas, virtútem largíris et prǽmia: per Christum Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes, ac beáta Séraphim, sócia exsultatióne concélebrant. Cum quibus et nostras voces, ut admítti iúbeas, deprecámur, súpplici confessióne dicéntes:  \n","pt":"v. Verdadeiramente é digno e justo, racional e salutar dar-Vos graças em todos os lugares e sempre, Senhor santo, Pai onipotente, eterno Deus, pois Vós, pelo jejum natural, reprimis os vícios, elevais o espírito e concedeis-nos a virtude e o prêmio por Cristo, Nosso Senhor: pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram e as Potestades trêmulas a reverenciam; e os Céus, as Virtudes dos Céus e os bem-aventurados Serafins se associam em comum louvor. Dignai-Vos permitir, Senhor, que as nossas vozes suplicantes se unam às deles, dizendo:\n"},"Quad5":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui salútem humáni géneris in ligno Crucis constituísti: ut, unde mors oriebátur, inde vita resúrgeret: et, qui in ligno vincébat, in ligno quoque vincerétur: per Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti júbeas, deprecámur, súpplici confessióne dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai onipotente, eterno Deus, que estabelecestes na árvore da Cruz a salvação do gênero humano, para que renascesse a vida, onde a morte houvera princípio, e que aquilo que outrora vencera na árvore, fosse vencido na árvore também, por Jesus Cristo, Nosso Senhor: pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos Céus e os bem-aventurados Serafins a celebram em comuns transportes de alegria: aos quais, Vos suplicamos, permiti que se unam as nossas vozes, dizendo em humilde e suplicante confissão:\n"},"Pasch":{"la":"v. Vere dignum et justum est, æquum et salutáre: Te quidem, Dómine, omni témpore, sed in~\nhoc potíssimum~\n(sed tempore Passionis)\nhac potíssimum nocte~\n(sed octava Paschæ)\nhac potíssimum die~\ngloriósius prædicáre, cum Pascha nostrum immolátus est Christus. Ipse enim verus est Agnus, qui ábstulit peccáta mundi. Qui mortem nostram moriéndo destrúxit et vitam resurgéndo reparávit. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar, que Vos louvemos sempre, mas mais gloriosamente~\nprincipalmente neste tempo,~\n(sed tempore Passionis)\nprincipalmente nesta noite,~\n(sed oitava Paschæ)\nprincipalmente neste dia,~\nem que Jesus Cristo foi imolado, como nova Páscoa. Pois Ele é o verdadeiro Cordeiro que tirou os pecados do mundo e que pela sua Ressurreição nos restituiu a vida. Por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo incessantemente:\n"},"Asc":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Qui post resurrectiónem suam ómnibus discípulis suis maniféstus appáruit et, ipsis cernéntibus, est elevátus in cælum, ut nos divinitátis suæ tribúeret esse partícipes. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\n","pt":"v. Verdadeiramente é digno e justo, racional e salutar que em todos os lugares e sempre Vos rendamos graças, Senhor santo, Pai onipotente, eterno Deus, por Jesus Cristo, Nosso Senhor, que depois da sua Ressurreição apareceu visivelmente a todos seus discípulos, em cuja presença subiu ao céu, a fim de nos tornar participantes da sua divindade. E, por isso, unidos aos Anjos e Arcanjos, aos Tronos e Dominações e a toda a milícia do exército celestial, cantamos um hino em vossa honra, dizendo incessantemente:\n"},"Spiritu":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. Qui, ascéndens super omnes cælos sedénsque ad déxteram tuam, promíssum Spíritum Sanctum * * in fílios adoptiónis effúdit. Quaprópter profúsis gáudiis totus in orbe terrárum mundus exsúltat. Sed et supérnæ Virtútes atque angélicæ Potestátes hymnum glóriæ tuæ cóncinunt, sine fine dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar dar-Vos graças, em todos os lugares e sempre, Senhor santo, Pai onipotente, eterno Deus, por Nosso Senhor Jesus Cristo, que, subindo ao mais alto dos céus e estando sentado à vossa direita, fez descer, (neste dia) sobre os seus filhos adotivos o Espírito Santo, como havia prometido. Por isso o mundo inteiro, em transportes de alegria, exulta de contentamento, enquanto as Virtudes do céu e as Potestades angelicais cantam um hino à vossa glória, dizendo incessantemente:\n"},"Trinitate":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui cum unigénito Fílio tuo et Spíritu Sancto unus es Deus, unus es Dóminus: non in uníus singularitáte persónæ, sed in uníus Trinitáte substántiæ. Quod enim de tua glória, revelánte te, crédimus, hoc de Fílio tuo, hoc de Spíritu Sancto sine differéntia discretiónis sentímus. Ut in confessióne veræ sempiternǽque Deitátis, et in persónis propríetas, et in esséntia únitas, et in majestáte adorétur æquálitas. Quam laudant Angeli atque Archángeli, Chérubim quoque ac Séraphim: qui non cessant clamáre cotídie, una voce dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai onipotente, eterno Deus, que com vosso Filho Unigênito e com o Espírito Santo sois um só Deus, um só Senhor, não na unidade de uma só pessoa, mas na Trindade de uma só substância. Porquanto, o que acreditamos a respeito da vossa glória, acreditamo-lo também, pela vossa revelação, a respeito do vosso Filho e do Espírito Santo, de tal modo que, confessando a verdadeira e eterna divindade, adoramos nas pessoas a propriedade, na essência a unidade e a igualdade na majestade. É esta majestade, que louvam os Anjos e Arcanjos, os Querubins e Serafins, que não cessam quotidianamente de cantar em uníssono:\n"},"Maria":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in *Festivitáte* beátæ Maríæ semper Vírginis collaudáre, benedícere et prædicáre. Quæ et Unigénitum tuum Sancti Spíritus obumbratióne concépit: et, virginitátis glória permanénte, lumen ætérnum mundo effúdit, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti jubeas, deprecámur, súpplici confessióne dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar render-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai onipotente, eterno Deus, e de sempre Vos louvar, bendizer e anunciar da Bem-aventurada Maria, sempre Virgem. Foi ela quem concebeu o vosso Filho Unigênito por obra do Espírito Santo, e, sem a mais leve perda de glória da virgindade, deu ao mundo a Luz eterna, Jesus Cristo, Nosso Senhor, por quem os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades a reverenciam, os Céus, as Virtudes dos céus e os bem-aventurados Serafins a festejam em transportes de alegria. E, Vos imploramos, permiti que unamos as nossas vozes às de todos estes, dizendo em suplicante confissão:\n"},"Joseph":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Et te in *Veneratióne* beáti Joseph débitis magnificáre præcóniis, benedícere et prædicáre. Qui et vir justus, a te Deíparæ Vírgini Sponsus est datus: et fidélis servus ac prudens, super Famíliam tuam est constitútus: ut Unigénitum tuum, Sancti Spíritus obumbratióne concéptum, paterna vice custodíret, Jesum Christum, Dóminum nostrum. Per quem majestátem tuam laudant Angeli, adórant Dominatiónes, tremunt Potestátes. Cæli cælorúmque Virtútes ac beáta Séraphim sócia exsultatióne concélebrant. Cum quibus et nostras voces ut admítti júbeas, deprecámur, súpplici confessióne dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar dar-Vos graças em todos os lugares e sempre, ó Senhor santo, Pai onipotente, eterno Deus: e na festividade do bem-aventurado José devemos proclamar, como convém, as vossas grandezas, bendizer-Vos e louvar-Vos. É ele o homem justo, que destinastes para esposo da Virgem Mãe de Deus; é ele o servo fiel e prudente, que colocastes na Sagrada Família, a fim de que guardasse, como se fora pai, o vosso Filho Unigênito, Jesus Cristo, Nosso Senhor, concebido por operação do Espírito Santo; pelo qual os Anjos louvam a vossa majestade, as Dominações a adoram, as Potestades se prostram reverentes, os Céus e os bem-aventurados Serafins a celebram em comuns transportes. Dignai-Vos permitir, Vos suplicamos, que as nossas vozes se unam às deles, dizendo em suplicante confissão:\n"},"Apostolis":{"la":"v. Vere dignum et justum est, æquum et salutáre: Te, Dómine, supplíciter exoráre, ut gregem tuum, Pastor ætérne, non déseras: sed per beátos Apóstolos tuos contínua protectióne custódias. Ut iísdem rectóribus gubernétur, quos óperis tui vicários eídem contulísti præésse pastóres. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar suplicar-Vos humildemente, Senhor, que, como Pastor eterno, que sois, não abandoneis o vosso rebanho, mas antes, por intercessão dos vossos bem-aventurados Apóstolos, o guardeis sob a vossa perpétua proteção, a fim de que seja sempre governado pelos mesmos Diretores, que, encarregados como Vigários de perpetuar a vossa obra, designastes seus Pastores. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\n"},"Regis":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui unigénitum Fílium tuum, Dóminum nostrum Jesum Christum, Sacerdótem ætérnum et universórum Regem, óleo exsultatiónis unxísti: ut, seípsum in ara crucis hóstiam immaculátam et pacíficam ófferens, redemptiónis humánæ sacraménta perágeret: et suo subjéctis império ómnibus creatúris, ætérnum et universále regnum, imménsæ tuæ tráderet Majestáti. Regnum veritátis et vitæ: regnum sanctitátis et grátiæ: regnum justítiæ, amóris et pacis. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar dar-Vos graças em todos os lugares e sempre, Senhor santo, Pai onipotente, eterno Deus, que ungistes com o óleo da alegria o vosso Filho Unigênito, Nosso Senhor Jesus Cristo, como Sacerdote eterno e Rei de todas as coisas, a fim de que, oferecendo-se na ara da Cruz - qual hóstia imaculada e pacífica -, realizasse as maravilhas da redenção humana e, ficando todas as criaturas sujeitas aoseu império, desse à vossa imensa majestade um reino eterno e universal: um reino de verdade e de vida; um reino de santidade e de graça; um reino de justiça, de amor e de paz. E por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos um hino à vossa glória, dizendo incessantemente:\n"},"Cord":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: Qui Unigénitum tuum, in Cruce pendéntem, láncea mílitis transfígi voluísti: ut apértum Cor, divínæ largitátis sacrárium, torréntes nobis fúnderet miseratiónis et grátiæ: et, quod amóre nostri flagráre numquam déstitit, piis esset réquies et pœniténtibus pateret salútis refúgium. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos demos graças, Senhor santo, Pai onipotente, eterno Deus, que quisestes que o vosso Filho Unigênito, suspenso na Cruz, fosse trespassado pela lança do soldado, a fim de que, aberto o Coração - sacrário da liberdade divina -, lançasse sobre nós torrentes de misericórdia e de graça; e, ardendo incessantemente de amor por nós, sirva de descanso aos piedosos e de asilo de salvação aos penitentes. E por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia celestial, cantamos o hino da vossa glória, dizendo sem cessar:\n"},"Defunctorum":{"la":"v. Vere dignum et justum est, æquum et salutáre, nos tibi semper et ubíque grátias ágere: Dómine sancte, Pater omnípotens, ætérne Deus: per Christum, Dóminum nostrum. In quo nobis spes beátæ resurrectiónis effúlsit, ut, quos contrístat certa moriéndi condício, eósdem consolétur futúræ immortalitátis promíssio. Tuis enim fidélibus, Dómine, vita mutátur, non tóllitur: et, dissolúta terréstris hujus incolátus domo, ætérna in cælis habitátio comparátur. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:\n","pt":"v. É verdadeiramente digno e justo, racional e salutar que sempre e em todos os lugares Vos dêmos graças, Senhor santo, Pai onipotente, eterno Deus, por meio de Nosso Senhor Jesus Cristo, em quem nos concedestes a esperança da feliz ressurreição; de sorte que, conquanto a condição certa da nossa morte nos entristeça, fiquemos consolados com a promessa da imortalidade futura. Pois, para os vossos fiéis, Senhor, a vida muda-se, não se acaba; e, desfeita esta Inorada terrena, adquire-se a habitação eterna nos céus. E, por isso, com os Anjos e Arcanjos, com os Tronos e Dominações e com toda a milícia do exército celestial, cantamos o hino da vossa glória, dizendo sem cessar:\n"}},"communicantes":{"C-common1962":{"la":"v. Communicántes, et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi, ","pt":"v. Unidos na mesma comunhão, honramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem, "},"C-Nat1962":{"la":"v. Communicántes, et diem sacratíssimum celebrántes, quo beátæ Maríæ intemeráta virgínitas huic mundo édidit Salvatórem: sed et memóriam venerántes, in primis ejúsdem gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi, ","pt":"v. Unidos na mesma comunhão, e celebrando o dia sacratíssimo em que a intemerata virgindade da bem-aventurada Maria deu à luz deste mundo o Salvador, veneramos a memória, em primeiro lugar, da mesma gloriosa sempre Virgem, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem, "},"C-Epi1962":{"la":"v. Communicántes, et diem sacratíssimum celebrántes, quo Unigénitus tuus, in tua tecum glória coætérnus, in veritáte carnis nostræ visibíliter corporális appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi, ","pt":"v. Unidos na mesma comunhão e celebando o dia sacratíssimo em que o vosso Filho Unigênito, co-eterno convosco na vossa glória, apareceu de modo visível na realidade do nosso corpo de carne, veneramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem, "},"C-Pasc1962":{"la":"v. Communicántes, et diem sacratíssimum celebrántes Resurrectiónis Dómini nostri Jesu Christi secúndum carnem: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi, ","pt":"v. Unidos na mesma comunhão e celebrando o dia sacratíssimo da ressurreição de Nosso Senhor Jesus Cristo segundo a carne, veneramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem, "},"C-Asc1962":{"la":"v. Communicántes, et diem sacratíssimum celebrántes, quo Dóminus noster, unigénitus Fílius tuus, unítam sibi fragilitátis nostræ substántiam in glóriæ tuæ déxtera collocávit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis ejúsdem Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi, ","pt":"v. Unidos na mesma comunhão e celebrando o dia sacratíssimo em que o vosso Filho Unigênito colocou à vossa direita, na glória, a nossa frágil natureza humana unida à sua Divindade, veneramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem, "},"C-Pent1962":{"la":"v. Communicántes, et diem sacratíssimum Pentecóstes celebrántes, quo Spíritus Sanctus Apóstolis innúmeris linguis appáruit: sed et memóriam venerántes, in primis gloriósæ semper Vírginis Maríæ, Genetrícis Dei et Dómini nostri Jesu Christi: sed et beáti Joseph, ejúsdem Vírginis Sponsi, ","pt":"v. Unidos na mesma comunhão e celebrando o dia sacratíssimo em que o Espírito Santo apareceu aos Apóstolos em inumeráveis línguas de fogo, veneramos a memória, em primeiro lugar, da gloriosa sempre Virgem Maria, Mãe de Deus e Senhor nosso Jesus Cristo, e também de S. José, o Esposo da mesma Virgem, "},"H-Pent":{"la":"quam tibi offérimus pro his quoque, quos regeneráre dignatus es ex aqua et Spíritu Sancto, tríbuens eis remissiónem omnium peccatórum, ","pt":"também por aqueles que Vos dignastes regenerar pela água e pelo Espírito Santo, concedendo-lhes a remissão de todos os pecados, "}}}; })(window.DG = window.DG || {});
